"use client";

/**
 * AgentWorkspace — the full agent surface, composed from Vercel AI Elements.
 *
 * Four places, one fact each, the way Claude lays its own app out:
 *
 *   - History is a shadcn Sidebar on the left (`WorkspaceHistory`): New chat,
 *     conversations grouped by age, Archive / Delete with Undo. Its trigger
 *     sits first in the header; on a phone it is the sidebar's own Sheet.
 *   - The header is thin (`WorkspaceHeader`): trigger, mark, name and title,
 *     the voice orb only while voice is active, the settings gear.
 *   - The thread (`WorkspaceThread`) is the whole response flow. Status lives
 *     in the reply that has it — Thinking, Reasoning, the chain of tool steps,
 *     approvals inside their tool, the run's Plan / Task / Undo inline in the
 *     reply that started it. There is no run bar, activity column or live
 *     status row any more.
 *   - The composer (`WorkspaceComposer`) is PromptInput, with the run's Queue
 *     (`RunQueue`) docked above it while messages wait behind a busy agent.
 *
 * Every control stays gated twice — on `transport.capabilities` and on the
 * transport method existing — which each part enforces on its own props.
 * Settings (autonomy, temperature, length) are lifted here because they ride
 * every send as `SendOptions.settings`, and only when the transport advertises
 * `capabilities.settings`.
 */

import * as React from "react";
import { toast } from "sonner";

import { Sidebar, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";

import { resolveState } from "@/components/agent/core/resolve-state";
import { isBusy, type ToolStateMap } from "@/components/agent/core/states";
import type { RunStatus } from "@/components/agent/core/run";
import { DEFAULT_EFFORTS, type AgentCommand, type AgentTransport, type ModelOption, type PromptSource, type SendOptions } from "@/components/agent/core/types";
import type { ConversationSummary } from "@/components/agent/core/conversations";
import type { SpeechAdapter } from "@/components/agent/voice/speech";
import type { AvatarRenderer } from "@/components/agent/avatar/types";

import type { OpenInTarget } from "@/components/ai-elements/open-in-chat";

import { WorkspaceHeader } from "./workspace/workspace-header";
import { WorkspaceThread } from "./workspace/workspace-thread";
import { WorkspaceHistory } from "./workspace/workspace-history";
import { WorkspaceComposer, type VoiceState } from "./workspace/workspace-composer";
import { RunQueue } from "./workspace/run-inline";
import { RUN_IN_FLIGHT } from "./workspace/reply-model";
import {
  DEFAULT_RESPONSE_LENGTH,
  DEFAULT_TEMPERATURE,
  type AutonomyMode,
} from "./workspace/workspace-settings";

/** `EffortSlider` takes a mutable array; one stable copy so the default never changes identity. */
const DEFAULT_EFFORT_LIST: string[] = [...DEFAULT_EFFORTS];

export type AgentWorkspaceProps = {
  transport: AgentTransport;
  /** The agent's face in the header, animated per state. Defaults to the built-in CubeAvatar. */
  avatar?: AvatarRenderer;
  /** Browser speech: the read-aloud voices offered in settings. */
  speech?: SpeechAdapter;
  /** Read aloud: resolves to a playable audio url for a reply's text. Absent renders no Read aloud action. */
  speak?: (text: string, voiceId?: string | null) => Promise<string>;
  /** Chat services each reply's "Open in…" menu offers, opened with the user message as the query. Absent or empty renders no menu. */
  openIn?: OpenInTarget[];
  toolStates?: ToolStateMap;
  /** The agent's display name in the header. Defaults to "Agent". */
  name?: string;
  /** The conversation's own title. Absent renders nothing — no placeholder. */
  title?: string;
  conversations?: {
    items: ConversationSummary[];
    /** The conversation currently open — highlighted in the history. */
    activeId?: string;
    onOpen: (id: string) => void;
    /** Starts a fresh conversation. Absent renders no "New chat" control. */
    onNew?: () => void;
    onArchive?: (id: string) => void;
    onDelete?: (id: string) => void;
    /** Undo for Delete's toast — puts the row back. */
    onRestore?: (item: ConversationSummary) => void;
  };
  models?: ModelOption[];
  /** What `@` offers in the composer. Shown only when `transport.capabilities.sources` is true. */
  sources?: PromptSource[];
  /** What `/` offers in the composer; `skill` commands are also in its + menu. */
  commands?: AgentCommand[];
  /**
   * Effort levels, low to high, for the composer's Effort control. The chosen
   * level rides `SendOptions.settings.effort`, so it shows only when the
   * transport advertises `capabilities.settings`. Defaults to `DEFAULT_EFFORTS`; pass `[]` for no Effort control.
   */
  efforts?: string[];
  /** Starter prompts for an empty conversation. */
  suggestions?: string[];
  /** Controlled open state for the settings sheet; uncontrolled when omitted. */
  settingsOpen?: boolean;
  onSettingsOpenChange?: (open: boolean) => void;
  /** Controlled open state for the history sidebar (desktop); uncontrolled, open by default, when omitted. */
  historyOpen?: boolean;
  onHistoryOpenChange?: (open: boolean) => void;
  className?: string;
};

export function AgentWorkspace({
  transport,
  avatar,
  speech,
  speak,
  openIn,
  toolStates,
  name,
  title,
  conversations,
  models,
  sources,
  commands,
  efforts = DEFAULT_EFFORT_LIST,
  suggestions,
  settingsOpen: settingsOpenProp,
  onSettingsOpenChange,
  historyOpen,
  onHistoryOpenChange,
  className,
}: AgentWorkspaceProps) {
  const [composerValue, setComposerValue] = React.useState("");
  const [webSearch, setWebSearch] = React.useState(false);
  const [modelId, setModelId] = React.useState<string | null>(null);
  const [voiceState, setVoiceState] = React.useState<VoiceState>("idle");
  const [awaitingFirstEvent, setAwaitingFirstEvent] = React.useState(false);
  const [turnsAtSend, setTurnsAtSend] = React.useState(0);

  /* Settings sheet — controlled or not. */
  const [internalSettingsOpen, setInternalSettingsOpen] = React.useState(false);
  const settingsOpen = settingsOpenProp ?? internalSettingsOpen;
  const setSettingsOpen = React.useCallback(
    (open: boolean) => {
      setInternalSettingsOpen(open);
      onSettingsOpenChange?.(open);
    },
    [onSettingsOpenChange],
  );

  /* Settings forwarded on every send when the transport can receive them. */
  const [autonomy, setAutonomy] = React.useState<AutonomyMode>("ask");
  const [length, setLength] = React.useState(DEFAULT_RESPONSE_LENGTH);
  const [temperature, setTemperature] = React.useState(DEFAULT_TEMPERATURE);
  // The middle level until the reader picks.
  const [effort, setEffort] = React.useState(() => efforts[Math.floor((efforts.length - 1) / 2)] ?? "");
  const resetSettings = React.useCallback(() => {
    setAutonomy("ask");
    setLength(DEFAULT_RESPONSE_LENGTH);
    setTemperature(DEFAULT_TEMPERATURE);
  }, []);

  const run = transport.runState?.run ?? null;
  const connection = transport.runState?.connection ?? "connected";

  /* "Submitted" only until the first sign of a reply — the next turn, or the
     run moving. Adjusted during render so this frame already shows it. */
  if (awaitingFirstEvent && transport.turns.length > turnsAtSend + 1) setAwaitingFirstEvent(false);

  const state = resolveState({
    turns: transport.turns,
    signals: { isLoading: transport.isLoading, awaitingFirstEvent },
    toolStates,
    run,
    connection,
  });
  const busy = isBusy(state);
  const runInFlight = run !== null && RUN_IN_FLIGHT.has(run.status);
  const status: "ready" | "submitted" | "streaming" | "error" = awaitingFirstEvent
    ? "submitted"
    : busy
      ? "streaming"
      : transport.error
        ? "error"
        : "ready";

  /* One toast per real transition, never on mount. The reply already says
     everything else; these two happen while the reader may be looking away. */
  const prevRunStatus = React.useRef<RunStatus | undefined>(undefined);
  const prevConnection = React.useRef<typeof connection | undefined>(undefined);
  React.useEffect(() => {
    const previous = prevRunStatus.current;
    if (run?.status && previous && run.status !== previous && run.status === "completed") {
      toast.success("Run completed");
    }
    prevRunStatus.current = run?.status;
  }, [run?.status]);
  React.useEffect(() => {
    const previous = prevConnection.current;
    if (previous && previous !== "connected" && connection === "connected") toast.success("Connection restored");
    prevConnection.current = connection;
  }, [connection]);

  const gatedModels = React.useMemo(
    () => (transport.capabilities.models ? models?.map((m) => ({ id: m.value, name: m.label })) : undefined),
    [transport.capabilities.models, models],
  );

  /* The model the picker shows is the model a send asks for — the first one until the reader picks. */
  const activeModel = modelId ?? gatedModels?.[0]?.id ?? null;

  const withSettings = React.useCallback(
    (options: SendOptions): SendOptions => ({
      ...options,
      ...(webSearch ? { webSearch: true } : {}),
      ...(transport.capabilities.settings
        ? { settings: { autonomy, temperature, length, ...(effort ? { effort } : {}), ...(options.settings?.effort ? { effort: options.settings.effort } : {}) } }
        : {}),
    }),
    [webSearch, transport.capabilities.settings, autonomy, temperature, length, effort],
  );

  const send = React.useCallback(
    (text: string, options: SendOptions = {}) => {
      const opts = withSettings({ ...(activeModel ? { model: activeModel } : {}), ...options });
      /* While the agent works — or a run is merely paused or waiting on the
         reader — a queue-capable transport holds the message rather than
         starting something new in the middle of the run. */
      if ((busy || runInFlight) && transport.capabilities.queue && transport.enqueue) {
        transport.enqueue(text, opts);
        return;
      }
      setTurnsAtSend(transport.turns.length);
      setAwaitingFirstEvent(true);
      void transport.send(text, opts).finally(() => setAwaitingFirstEvent(false));
    },
    [withSettings, activeModel, busy, runInFlight, transport],
  );

  const voiceId = speech?.voiceId ?? null;
  const speakWithVoice = React.useMemo(
    () => (speak ? (text: string) => speak(text, voiceId) : undefined),
    [speak, voiceId],
  );

  const shownVoiceState: VoiceState = voiceState === "idle" && speech?.isSpeaking ? "speaking" : voiceState;

  const settings = {
    autonomy,
    onAutonomyChange: setAutonomy,
    length,
    onLengthChange: setLength,
    temperature,
    onTemperatureChange: setTemperature,
    voice: voiceId,
    onVoiceChange: speech?.setVoiceId,
    voices: speech?.isSupported ? speech.voices : undefined,
    agent: transport.agent,
    onReset: resetSettings,
    disabled: !transport.isReady,
  };

  const hasHistory = Boolean(conversations);

  const frame = cn(
    "relative h-full min-h-0 overflow-hidden rounded-lg border border-border bg-background",
    className,
  );

  const body = (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col">
      <WorkspaceHeader
        avatar={avatar}
        state={state}
        name={name}
        title={title}
        leading={
          hasHistory ? (
            /* Icon-only and alone at the header edge: the full target, not the toolbar size. */
            <SidebarTrigger className="min-h-(--size-target-min) min-w-(--size-target-min)" />
          ) : undefined
        }
        voiceState={shownVoiceState}
        settings={settings}
        showSettings={Boolean(transport.capabilities.settings)}
        settingsOpen={settingsOpen}
        onSettingsOpenChange={setSettingsOpen}
      />

      <WorkspaceThread
        transport={transport}
        busy={busy}
        starters={suggestions}
        onSend={send}
        speak={speakWithVoice}
        openIn={openIn}
        composerEmpty={!composerValue.trim()}
        className="min-h-0 flex-1"
      />

      <div className="px-4 pb-4">
        <WorkspaceComposer
          className="mx-auto w-full max-w-(--width-prose)"
          transport={transport}
          value={composerValue}
          onValueChange={setComposerValue}
          onSubmit={send}
          onStop={transport.abort}
          status={status}
          models={gatedModels}
          model={activeModel ?? undefined}
          onModelChange={setModelId}
          webSearch={webSearch}
          onWebSearchChange={setWebSearch}
          sources={sources}
          commands={commands}
          efforts={transport.capabilities.settings ? efforts : undefined}
          effort={effort}
          onEffortChange={setEffort}
          dock={run ? <RunQueue transport={transport} run={run} /> : undefined}
          onVoiceStateChange={setVoiceState}
          disabled={!transport.isReady}
          disabledReason={!transport.isReady ? "Waiting for the assistant to connect." : undefined}
        />
      </div>
    </div>
  );

  /* No history, no sidebar machinery: the provider (its keyboard shortcut, its
     cookie, its context) mounts only when there is a list to open. */
  if (!conversations) {
    return (
      <div className={cn("flex w-full", frame)} data-slot="agent-workspace">
        {body}
      </div>
    );
  }

  return (
    <SidebarProvider
      open={historyOpen}
      onOpenChange={onHistoryOpenChange}
      className={frame}
      data-slot="agent-workspace"
    >
      {/* The Sidebar is page-fixed by default; inside an embedded workspace it
          is pinned to the workspace instead (`absolute h-full` win over
          `fixed h-svh` through tailwind-merge). */}
      <Sidebar className="absolute h-full" aria-label="Conversations">
        <WorkspaceHistory {...conversations} />
      </Sidebar>
      {body}
    </SidebarProvider>
  );
}

/* ============================================================================
   AVATAR MOTION — owned by components/agent/avatar, not by the design system

   The fifteen cube signatures from the design handoff, one per state family.
   They are not `anim-*` utilities: `cube.tsx` assembles
   `animation: agent-cube-<name> <seconds ÷ speed> var(--ease-move) infinite`
   per cube from the scene recipe. Durations are the handoff's; easing is
   always `--ease-move` except spin3d, which is linear.

   This file is imported by `cube-avatar.tsx` and ships with the `agent`
   registry item. It is NOT part of `source-foundation`: a consumer re-theming
   the system's motion never has to read it. Timing still comes from the
   scale in styles/motion.css — nothing here declares a duration or a curve.

   `appear` and `drop` end at opacity 0 on purpose (cubes arrive one by one and
   hard-cut back, Game Boy logo style); the reduced-motion block at the bottom
   restores the static layout so no scene freezes to an empty box.
   ========================================================================= */

@keyframes agent-cube-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

@keyframes agent-cube-rise {
  0%, 55%, 100% { transform: translateY(0); }
  20%, 35% { transform: translateY(-11px); }
}

@keyframes agent-cube-appear {
  0% { opacity: 0; transform: translateY(8px); }
  10% { opacity: 1; transform: translateY(0); }
  93% { opacity: 1; transform: translateY(0); }
  95%, 100% { opacity: 0; }
}

@keyframes agent-cube-drop {
  0% { opacity: 0; transform: translateY(-24px); }
  18% { opacity: 1; transform: translateY(0); }
  93% { opacity: 1; }
  95%, 100% { opacity: 0; }
}

@keyframes agent-cube-glide {
  0% { transform: translate(0, 0); }
  100% { transform: translate(39px, 19.5px); }
}

@keyframes agent-cube-blinkfade {
  0%, 100% { opacity: 0.15; }
  50% { opacity: 0.95; }
}

@keyframes agent-cube-blinkslow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.25; }
}

@keyframes agent-cube-lift {
  0%, 100% { transform: translateY(0); }
  45%, 60% { transform: translateY(-6.5px); }
}

@keyframes agent-cube-lift2 {
  0%, 100% { transform: translateY(0); }
  45%, 60% { transform: translateY(-13px); }
}

@keyframes agent-cube-settle {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

@keyframes agent-cube-pull {
  0%, 60%, 100% { transform: translateY(0); }
  25%, 40% { transform: translateY(-20px); }
}

@keyframes agent-cube-shake {
  0%, 100% { transform: translateY(0); }
  20% { transform: translateY(-2.5px); }
  40% { transform: translateY(2.5px); }
  60% { transform: translateY(-2px); }
  80% { transform: translateY(2px); }
}

@keyframes agent-cube-bounce {
  0%, 100% { transform: translateY(0); }
  35% { transform: translateY(-16px); }
  55% { transform: translateY(0); }
  70% { transform: translateY(-6px); }
  82% { transform: translateY(0); }
}

@keyframes agent-cube-spin3d {
  0% { transform: rotateX(0deg) rotateY(0deg) rotateZ(0deg); }
  100% { transform: rotateX(360deg) rotateY(360deg) rotateZ(360deg); }
}

/* The avatar cross-fade. Swapping state replaces the whole scene, so the
   outgoing one is not animated out — it is simply replaced under a fade, which
   is why this is an entrance only. */
@keyframes agent-cube-scene-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* ── Reduced motion, handled explicitly ──────────────────────────────────────
   The blanket rule elsewhere in this file collapses every animation to 0.01ms
   and one iteration. For most things that is a freeze at the final keyframe,
   which is correct — but `appear` and `drop` END at opacity 0, so the blanket
   rule would freeze half the scenes to nothing at all. The handoff's
   instruction is to fall back to the static cube layout, so that is stated here
   rather than inherited: no animation, everything visible, no transforms.

   `!important` on a class beats the inline `opacity: 0` those two keyframes
   need as their starting state.

   Only `.agent-cube-anim` is targeted, never the positioning group. In SVG,
   `transform` is a presentation attribute mapped to the CSS property, so a CSS
   `transform: none` outranks `transform="translate(x,y)"` — pointing this rule
   at every <g> would stack all twenty-odd cubes on the origin. The animated
   groups carry no transform attribute of their own, which is what makes them
   the safe thing to clear. */
.agent-cube-scene.agent-cube-frozen .agent-cube-anim,
.agent-cube-frozen .agent-cube-scene .agent-cube-anim {
  animation: none !important;
  opacity: 1 !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .agent-cube-scene .agent-cube-anim {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

"use client";

import { useEffect, useRef, useState } from "react";

import { AGENT_STATE_LABEL, type AgentState } from "../core/states";
import { anim } from "./cube";
import { CubeScene } from "./cube";
import { sceneFor } from "./scenes";
import type { AvatarRendererProps, AvatarSize } from "./types";
import { cn } from "@/lib/utils";

import "./avatar.css";

/**
 * The default face: twenty-six isometric cube scenes.
 *
 * This is one implementation of `AvatarRenderer`, not a fixture. The console
 * takes the renderer as a prop and defaults to this one; swapping in different
 * artwork is a prop, not a fork. Everything specific to *these* cubes — the
 * geometry, the recipes, the keyframes — is confined to this folder.
 *
 * Two things are handled here rather than in the scenes:
 *
 *   The cross-fade. Changing state replaces the entire SVG, and a hard swap
 *   between two busy scenes reads as a glitch. The outgoing scene is held for
 *   the length of one fade while the incoming one fades over it.
 *
 *   Idle. It is the only state that is not an isometric projection: the handoff
 *   specifies a real CSS 3D cube on a perspective, rotating on all three axes.
 *   It gets its own branch because it genuinely is a different object.
 */

/** Rendered width of the scene box. Scenes size themselves within it. */
const SIZE: Record<AvatarSize, { box: string; scale: number }> = {
  sm: { box: "size-8", scale: 0.19 },
  md: { box: "size-12", scale: 0.29 },
  lg: { box: "size-20", scale: 0.48 },
  xl: { box: "size-32", scale: 0.78 },
};

/** Matches --duration-fast. The handoff asks for 150–200ms between states. */
const CROSSFADE_MS = 150;

/**
 * The incoming scene's fade.
 *
 * Hoisted out of the JSX so it is one object rather than a new one per render,
 * and so the reason below sits on the line it explains.
 *
 * allow-dynamic-motion: CROSSFADE_MS is also read in JavaScript, to schedule
 * when the outgoing scene unmounts, so the same number has to exist as a JS
 * value — it cannot live only as a class. It tracks --duration-fast.
 */
const SCENE_IN = { animation: `agent-cube-scene-in ${CROSSFADE_MS}ms var(--ease-enter) both` };

export function CubeAvatar({
  state = "idle",
  size = "md",
  accent = "var(--agent)",
  speed = 1,
  className,
}: AvatarRendererProps) {
  const box = SIZE[size];
  const previous = useCrossfade(state);

  return (
    <span
      data-agent-avatar={state}
      role="img"
      aria-label={AGENT_STATE_LABEL[state]}
      className={cn("agent-cube-scene relative grid shrink-0 place-items-center", box.box, className)}
      // The single knob. Every accent face in the set is mixed from this, so a
      // caller passing `accent` recolours twenty-six scenes at once — and the
      // default routes it at the product's own agent token, which is what makes
      // the avatar follow a retheme instead of pinning the handoff's yellow.
      style={{ "--agent-cube-accent": accent } as React.CSSProperties}
    >
      {/* The outgoing scene sits underneath at full opacity and is simply
          dropped when the fade ends. Only the incoming one animates — it mounts
          fresh, and a CSS transition on a freshly-mounted element has no prior
          value to travel from, so this has to be a keyframe rather than a
          transition or the "fade" is an instant swap. */}
      {previous && previous !== state ? (
        <Scene key={previous} state={previous} scale={box.scale} speed={speed} />
      ) : null}
      <Scene key={state} state={state} scale={box.scale} speed={speed} entering />
    </span>
  );
}

/**
 * Holds the outgoing state for one fade.
 *
 * Returns the state being faded out, or null when nothing is transitioning.
 */
function useCrossfade(state: AgentState): AgentState | null {
  const [outgoing, setOutgoing] = useState<AgentState | null>(null);
  const current = useRef(state);

  useEffect(() => {
    if (current.current === state) return;
    const leaving = current.current;
    current.current = state;
    setOutgoing(leaving);
    const timer = window.setTimeout(() => setOutgoing(null), CROSSFADE_MS);
    return () => window.clearTimeout(timer);
  }, [state]);

  return outgoing;
}

function Scene({
  state,
  scale,
  speed,
  entering,
}: {
  state: AgentState;
  scale: number;
  speed: number;
  entering?: boolean;
}) {
  return (
    <span
      className="pointer-events-none absolute inset-0 grid place-items-center"
      style={entering ? SCENE_IN : undefined}
    >
      {state === "idle" ? (
        <IdleCube scale={scale} speed={speed} />
      ) : (
        <IsoScene state={state} scale={scale} speed={speed} />
      )}
    </span>
  );
}

function IsoScene({
  state,
  scale,
  speed,
}: {
  state: Exclude<AgentState, "idle">;
  scale: number;
  speed: number;
}) {
  const scene = sceneFor(state, { speed });
  return <CubeScene cubes={scene.cubes} width={scene.width * scale} />;
}

/**
 * Idle — a real cube, not a projection.
 *
 * Six faces on a `preserve-3d` parent, rotating on X, Y and Z at once. Linear,
 * and slow: this is the resting state, and anything faster reads as activity.
 * The face size scales with the avatar, so `translateZ` is half of it.
 */
function IdleCube({ scale, speed }: { scale: number; speed: number }) {
  const face = 44 * scale * 1.35;
  const half = face / 2;

  const faces: { background: string; transform: string }[] = [
    { background: "color-mix(in oklab, var(--agent-cube-accent) 55%, var(--agent-cube-top))", transform: `rotateX(90deg) translateZ(${half}px)` },
    { background: "var(--agent-cube-back)", transform: `rotateX(-90deg) translateZ(${half}px)` },
    { background: "var(--agent-cube-accent)", transform: `translateZ(${half}px)` },
    { background: "var(--agent-cube-left)", transform: `rotateY(180deg) translateZ(${half}px)` },
    {
      background: "color-mix(in oklab, var(--agent-cube-accent) 80%, var(--agent-cube-accent-shade))",
      transform: `rotateY(90deg) translateZ(${half}px)`,
    },
    { background: "var(--agent-cube-right)", transform: `rotateY(-90deg) translateZ(${half}px)` },
  ];

  return (
    <span
      className="grid place-items-center"
      style={{ perspective: `${360 * scale}px`, width: face, height: face }}
    >
      <span
        className="agent-cube-anim relative block"
        style={{
          width: face,
          height: face,
          transformStyle: "preserve-3d",
          ...anim("spin3d", 9, { speed }, { linear: true }),
        }}
      >
        {faces.map((f) => (
          <span
            key={f.transform}
            className="absolute block border"
            style={{
              width: face,
              height: face,
              background: f.background,
              transform: f.transform,
              borderColor: "var(--agent-cube-stroke)",
              boxSizing: "border-box",
            }}
          />
        ))}
      </span>
    </span>
  );
}

/**
 * The isometric cube renderer.
 *
 * One projection, three polygons per cube, one sort. Every one of the
 * twenty-six SVG scenes is this file plus a list of coordinates — which is the
 * reason the scenes can be data rather than twenty-six hand-drawn components.
 *
 * Geometry is the design handoff's, unchanged:
 *   screenX = (x − y) · 13
 *   screenY = (x + y) · 6.5 − z · 13
 *
 * Colours are not the handoff's literals but the tokens they were transcribed
 * into (`--agent-cube-*` in globals.css), so the set re-themes with the product
 * and survives `check:tokens`. The accent's three faces are mixed from a single
 * `--agent-cube-accent`, so overriding that one variable recolours everything.
 */

import type { CSSProperties } from "react";

/** Half-width, half-height, cube height. The isometric unit. */
const HW = 13;
const HH = 6.5;
const CH = 13;

export function iso(x: number, y: number, z = 0): [number, number] {
  return [(x - y) * HW, (x + y) * HH - z * CH];
}

/** Face polygons, relative to the cube's origin. */
const FACE = {
  top: "0,0 13,6.5 0,13 -13,6.5",
  left: "-13,6.5 0,13 0,26 -13,19.5",
  right: "13,6.5 0,13 0,26 13,19.5",
} as const;

/* ── Face colours ────────────────────────────────────────────────────────────
 *
 * The accent's top and right faces are derived rather than declared, exactly as
 * the handoff specifies, so that a caller setting `--agent-cube-accent` to any
 * hue gets a correctly lit cube instead of three unrelated colours. `oklab` for
 * the lighting mixes because it keeps perceived lightness linear; `srgb` for the
 * transparency mix because that one is compositing, not shading.
 */
const NEUTRAL = {
  top: "var(--agent-cube-top)",
  left: "var(--agent-cube-left)",
  right: "var(--agent-cube-right)",
  stroke: "var(--agent-cube-stroke)",
} as const;

const ACCENT_TOP = "color-mix(in oklab, var(--agent-cube-accent) 55%, var(--agent-cube-top))";
const ACCENT_RIGHT =
  "color-mix(in oklab, var(--agent-cube-accent) 80%, var(--agent-cube-accent-shade))";
const ACCENT_STROKE =
  "color-mix(in oklab, var(--agent-cube-accent) 45%, var(--agent-cube-stroke))";

const ACCENT = {
  top: ACCENT_TOP,
  left: "var(--agent-cube-accent)",
  right: ACCENT_RIGHT,
  stroke: ACCENT_STROKE,
} as const;

const ERROR = {
  top: "var(--agent-cube-error-top)",
  left: "var(--agent-cube-error-left)",
  right: "var(--agent-cube-error-right)",
  stroke: "var(--agent-cube-error-stroke)",
} as const;

/** The "missing box" — an accent cube at 45%, dashed. Reads as a slot to fill. */
const GHOST = {
  top: `color-mix(in srgb, ${ACCENT_TOP} 45%, transparent)`,
  left: "color-mix(in srgb, var(--agent-cube-accent) 45%, transparent)",
  right: `color-mix(in srgb, ${ACCENT_RIGHT} 45%, transparent)`,
  stroke: "color-mix(in oklab, var(--agent-cube-accent) 70%, var(--agent-cube-ghost-ink))",
} as const;

const DASH = "3 2.5";

/* ── The cube ────────────────────────────────────────────────────────────── */

export type Cube = {
  x: number;
  y: number;
  z?: number;
  accent?: boolean;
  red?: boolean;
  dashed?: boolean;
  /**
   * Forces this cube to the front of the painter's sort. Anything that floats
   * above or moves across the scene needs it, or it disappears behind the
   * geometry it is supposed to be travelling over.
   */
  boost?: number;
  /** Animation applied to the cube itself. */
  style?: CSSProperties;
  /** A second wrapper, for scenes that compose two motions (glide + bob). */
  outer?: CSSProperties;
};

function faces(cube: Cube) {
  if (cube.red) return { palette: ERROR, dash: undefined };
  if (cube.dashed) return { palette: GHOST, dash: DASH };
  if (cube.accent) return { palette: ACCENT, dash: undefined };
  return { palette: NEUTRAL, dash: undefined };
}

function CubeShape({ cube, index }: { cube: Cube; index: number }) {
  const [sx, sy] = iso(cube.x, cube.y, cube.z ?? 0);
  const { palette, dash } = faces(cube);

  const polygon = (points: string, fill: string) => (
    <polygon
      points={points}
      fill={fill}
      stroke={palette.stroke}
      strokeWidth={0.8}
      strokeLinejoin="round"
      {...(dash ? { strokeDasharray: dash } : {})}
    />
  );

  // Draw order within a cube is fixed: left, right, then top. The top face has
  // to land last or the two side faces overdraw its lower edges.
  const body = (
    <g className="agent-cube-anim" style={cube.style}>
      {polygon(FACE.left, palette.left)}
      {polygon(FACE.right, palette.right)}
      {polygon(FACE.top, palette.top)}
    </g>
  );

  return (
    <g key={index} transform={`translate(${sx},${sy})`}>
      {cube.outer ? (
        <g className="agent-cube-anim" style={cube.outer}>
          {body}
        </g>
      ) : (
        body
      )}
    </g>
  );
}

/* ── The scene ───────────────────────────────────────────────────────────── */

/**
 * Painter's sort: back to front by depth, then by height.
 *
 * `x + y` is distance from the viewer in the isometric grid, so sorting on it
 * puts nearer cubes later in document order and therefore on top. `boost` lifts
 * a cube out of that ordering entirely, and `z` breaks ties within one grid cell
 * so a stack draws bottom-up.
 */
function sortCubes(cubes: Cube[]): Cube[] {
  return cubes.slice().sort((a, b) => {
    const depth = a.x + a.y + (a.boost ?? 0) - (b.x + b.y + (b.boost ?? 0));
    return depth || (a.z ?? 0) - (b.z ?? 0);
  });
}

/**
 * The viewBox is measured from the cubes rather than declared.
 *
 * A scene's extent depends on its own geometry, and hand-tuning twenty-six viewBoxes
 * is how a scene silently clips the first time someone edits a recipe. `overflow:
 * visible` on the SVG covers the rest: a lifted or bouncing cube travels outside
 * the static bounds by design.
 */
const PAD = 10;

export function CubeScene({
  cubes,
  width,
  className,
}: {
  cubes: Cube[];
  width: number;
  className?: string;
}) {
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;

  for (const cube of cubes) {
    const [sx, sy] = iso(cube.x, cube.y, cube.z ?? 0);
    minX = Math.min(minX, sx - HW);
    maxX = Math.max(maxX, sx + HW);
    minY = Math.min(minY, sy);
    maxY = Math.max(maxY, sy + HH * 2 + CH);
  }

  const viewBox = [
    minX - PAD,
    minY - PAD,
    maxX - minX + PAD * 2,
    maxY - minY + PAD * 2,
  ].join(" ");

  return (
    <svg
      viewBox={viewBox}
      width={width}
      className={className}
      style={{ display: "block", overflow: "visible" }}
      aria-hidden
    >
      {sortCubes(cubes).map((cube, index) => (
        <CubeShape key={`${cube.x}-${cube.y}-${cube.z ?? 0}-${index}`} cube={cube} index={index} />
      ))}
    </svg>
  );
}

/* ── Animation helpers ───────────────────────────────────────────────────────
 *
 * Scenes declare motion through these rather than writing the shorthand, so the
 * speed multiplier is applied in exactly one place and every scene stays on
 * var(--ease-in-out).
 */

export type Timing = { speed: number };

/** `animation` shorthand for one of the cube keyframes. */
export function anim(
  name: string,
  seconds: number,
  { speed }: Timing,
  options: { delay?: number; alternate?: boolean; linear?: boolean } = {},
): CSSProperties {
  const duration = (seconds / speed).toFixed(2);
  const easing = options.linear ? "linear" : "var(--ease-move)";
  return {
    // allow-dynamic-motion: the one place in this system where the shorthand
    // genuinely cannot be a utility class. Twenty-six scenes hold up to twenty
    // cubes each, and every cube needs its own keyframe name, its own duration
    // divided by the avatar's `speed` prop, and its own stagger delay. That is
    // several hundred combinations. Only the keyframes live in ./avatar.css;
    // `easing` above is always `linear` or `var(--ease-in-out)`, never a
    // literal curve.
    animation: `agent-cube-${name} ${duration}s ${easing} infinite${
      options.alternate ? " alternate" : ""
    }`,
    ...(options.delay ? { animationDelay: `${(options.delay / speed).toFixed(2)}s` } : {}),
  };
}

/**
 * The `appear` family, which starts invisible.
 *
 * Split out because the initial `opacity: 0` is load-bearing: without it every
 * cube in the scene flashes at full opacity on the first frame before the
 * animation takes over, and the whole Game Boy-logo effect is lost.
 */
export function appear(seconds: number, delay: number, timing: Timing): CSSProperties {
  return { opacity: 0, ...anim("appear", seconds, timing, { delay }) };
}

export function drop(seconds: number, delay: number, timing: Timing): CSSProperties {
  return { opacity: 0, ...anim("drop", seconds, timing, { delay }) };
}

/**
 * The twenty-six state recipes.
 *
 * Each is a function from a speed multiplier to a list of cubes. That is the
 * whole extent of what a state *is* here — geometry and timing, no component, no
 * branching, no per-state file. Editing a motion signature means editing one
 * generator, and adding a state means adding one entry.
 *
 * Transcribed from the design handoff. Grid coordinates, delays and durations
 * are its numbers exactly; the widths are its per-scene overrides.
 *
 * `idle` is the one exception and has no entry: it is a real CSS 3D cube rather
 * than an isometric projection, so it is drawn directly in `CubeAvatar`.
 */

import { anim, appear, drop, type Cube, type Timing } from "./cube";
import type { AgentState } from "../core/states";

export type Scene = { cubes: Cube[]; width: number };
type Generator = (timing: Timing) => Scene;

/** The eight perimeter cells of a 3×3, in ring order. Used by two scenes. */
const RING: [number, number][] = [
  [0, 0],
  [1, 0],
  [2, 0],
  [2, 1],
  [2, 2],
  [1, 2],
  [0, 2],
  [0, 1],
];

/** Default scene width. Overridden per scene where the geometry is wider or narrower. */
const W = 168;

const scenes: Record<Exclude<AgentState, "idle">, Generator> = {
  /** Five cubes waiting their turn, bobbing in sequence. */
  queued: (t) => ({
    width: 190,
    cubes: Array.from({ length: 5 }, (_, x) => ({
      x,
      y: 0,
      accent: x === 2,
      style: anim("bob", 2.2, t, { delay: x * 0.22 }),
    })),
  }),

  /** A staircase assembling itself — each column one step taller than the last. */
  planning: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 4; x += 1) {
      for (let y = 0; y < 2; y += 1) {
        for (let z = 0; z <= x; z += 1) {
          cubes.push({ x, y, z, accent: z === x, style: appear(3.6, x * 0.35 + z * 0.12, t) });
        }
      }
    }
    return { width: 160, cubes };
  },

  /** One cube pulled up out of the middle of a stack, over and over. */
  retrieving: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 3; x += 1) {
      for (let y = 0; y < 3; y += 1) {
        cubes.push(
          x === 1 && y === 1
            ? { x, y, boost: 100, accent: true, style: anim("pull", 2.6, t) }
            : { x, y },
        );
      }
    }
    return { width: W, cubes };
  },

  /** Cubes falling onto a platform, one after another. */
  ingesting: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 2; x += 1) {
      for (let y = 0; y < 2; y += 1) {
        cubes.push({ x, y });
        cubes.push({ x, y, z: 1, accent: true, style: drop(2.8, (x * 2 + y) * 0.4, t) });
      }
    }
    return { width: 120, cubes };
  },

  /** A diagonal ripple across a 4×4 — deliberately no opacity change. */
  running: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 4; x += 1) {
      for (let y = 0; y < 4; y += 1) {
        cubes.push({
          x,
          y,
          accent: x + y === 3,
          style: anim("settle", 1.6, t, { delay: (x + y) * 0.15 }),
        });
      }
    }
    return { width: W, cubes };
  },

  /** Two islands, and a courier gliding from one to the other. */
  delegating: (t) => {
    const cubes: Cube[] = [];
    for (const base of [0, 4]) {
      for (let x = base; x < base + 2; x += 1) {
        for (let y = 0; y < 2; y += 1) {
          cubes.push({ x, y, style: anim("settle", 3, t, { delay: base ? 1.5 : 0 }) });
        }
      }
    }
    // No bob on the courier: it travels in a straight line, which is what makes
    // it read as carrying something rather than wandering.
    cubes.push({
      x: 1,
      y: 0,
      z: 1,
      boost: 100,
      accent: true,
      outer: anim("glide", 2.2, t, { alternate: true }),
    });
    return { width: 190, cubes };
  },

  /** A slot at the near corner, blinking to be filled. */
  awaiting_approval: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 3; x += 1) {
      for (let y = 0; y < 3; y += 1) {
        cubes.push(
          x === 2 && y === 2
            ? { x, y, boost: 100, dashed: true, style: anim("blinkslow", 2.2, t) }
            : { x, y },
        );
      }
    }
    return { width: W, cubes };
  },

  /** A pulse chasing the perimeter, checking each cell in turn. */
  validating: (t) => {
    const cubes: Cube[] = [{ x: 1, y: 1 }];
    RING.forEach(([x, y], i) => {
      cubes.push({ x, y, accent: true, style: anim("blinkfade", 2, t, { delay: i * 0.25 }) });
    });
    return { width: W, cubes };
  },

  /** One cube bouncing off the stack and landing again. */
  retrying: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 2; x += 1) {
      for (let y = 0; y < 2; y += 1) cubes.push({ x, y });
    }
    cubes.push({ x: 0, y: 0, z: 1, boost: 100, accent: true, style: anim("bounce", 2, t) });
    return { width: 120, cubes };
  },

  /** The centre cube shaking, in red. The only scene that leaves the accent. */
  error: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 3; x += 1) {
      for (let y = 0; y < 3; y += 1) {
        cubes.push(
          x === 1 && y === 1 ? { x, y, red: true, style: anim("shake", 1.4, t) } : { x, y },
        );
      }
    }
    return { width: W, cubes };
  },

  /** The perimeter assembling first, then the conclusion in the middle. */
  summarizing: (t) => {
    const cubes: Cube[] = RING.map(([x, y], i) => ({ x, y, style: appear(4, i * 0.26, t) }));
    cubes.push({ x: 1, y: 1, accent: true, style: appear(4, 2.1, t) });
    return { width: W, cubes };
  },

  /** A diagonal wave of consideration across a 3×3. */
  thinking: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 3; x += 1) {
      for (let y = 0; y < 3; y += 1) {
        cubes.push({
          x,
          y,
          accent: x === 1 && y === 1,
          style: anim("bob", 1.8, t, { delay: 0.16 * (x + y) }),
        });
      }
    }
    return { width: W, cubes };
  },

  /** Scattered cells rising in sequence — work happening in several places. */
  processing: (t) => {
    const raised: Record<string, number> = {
      "0,1": 0,
      "1,3": 0.6,
      "2,0": 1.2,
      "3,2": 1.8,
      "1,1": 2.4,
    };
    const cubes: Cube[] = [];
    for (let x = 0; x < 4; x += 1) {
      for (let y = 0; y < 4; y += 1) {
        const delay = raised[`${x},${y}`];
        cubes.push({
          x,
          y,
          accent: delay !== undefined,
          ...(delay === undefined ? {} : { style: anim("rise", 3, t, { delay }) }),
        });
      }
    }
    return { width: W, cubes };
  },

  /** Two blocks, and a bridge being built between them. */
  calling_tools: (t) => {
    const cubes: Cube[] = [];
    for (const base of [0, 4]) {
      for (let x = base; x < base + 2; x += 1) {
        for (let y = 0; y < 2; y += 1) cubes.push({ x, y, style: anim("settle", 2.4, t) });
      }
    }
    (
      [
        [2, 0, 0],
        [2, 1, 0.3],
        [3, 0, 0.6],
        [3, 1, 0.9],
      ] as const
    ).forEach(([x, y, delay]) => cubes.push({ x, y, accent: true, style: appear(3, delay, t) }));
    return { width: 196, cubes };
  },

  /** A scanner hunting over a platform with holes in it. */
  searching: (t) => {
    const holes: Record<string, "dashed" | "gone"> = {
      "2,1": "dashed",
      "1,3": "gone",
      "3,0": "gone",
    };
    const cubes: Cube[] = [];
    for (let x = 0; x < 4; x += 1) {
      for (let y = 0; y < 4; y += 1) {
        const hole = holes[`${x},${y}`];
        if (hole === "gone") continue;
        cubes.push(hole === "dashed" ? { x, y, dashed: true } : { x, y });
      }
    }
    // Two motions composed: the outer glides across, the inner bobs in place.
    cubes.push({
      x: 0,
      y: 1,
      z: 1.5,
      boost: 100,
      accent: true,
      outer: anim("glide", 2.6, t, { alternate: true }),
      style: anim("bob", 1.3, t),
    });
    return { width: W, cubes };
  },

  /** Three layers lifting apart, like pages coming off a stack. */
  reading: (t) => {
    const cubes: Cube[] = [];
    for (let z = 0; z < 3; z += 1) {
      for (let x = 0; x < 3; x += 1) {
        for (let y = 0; y < 2; y += 1) {
          cubes.push({
            x,
            y,
            z,
            accent: z === 2,
            // Same duration and phase on both lifted layers, so they travel
            // together and never intersect.
            ...(z === 0 ? {} : { style: anim(z === 1 ? "lift" : "lift2", 2.2, t) }),
          });
        }
      }
    }
    return { width: 150, cubes };
  },

  /** Rows surfacing from the back — older context coming forward. */
  recalling: (t) => {
    const cubes: Cube[] = [];
    for (let row = 0; row < 3; row += 1) {
      for (let x = 0; x < 4; x += 1) {
        cubes.push({
          x,
          y: 2 - row,
          accent: row === 0,
          ...(row === 2 ? {} : { style: appear(3.2, (1 - row) * 0.5 + x * 0.12, t) }),
        });
      }
    }
    return { width: W, cubes };
  },

  /** A grid filling in cube by cube, left to right, like typing. */
  writing: (t) => {
    const cubes: Cube[] = [];
    for (let y = 0; y < 3; y += 1) {
      for (let x = 0; x < 4; x += 1) {
        cubes.push({
          x,
          y,
          accent: y === 2 && x === 3,
          style: appear(3.4, (y * 4 + x) * 0.13, t),
        });
      }
    }
    return { width: W, cubes };
  },

  /** A solid, finished block, breathing in phase. */
  done: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 2; x += 1) {
      for (let y = 0; y < 2; y += 1) {
        for (let z = 0; z < 2; z += 1) {
          cubes.push({ x, y, z, accent: z === 1, style: anim("settle", 3.2, t) });
        }
      }
    }
    return { width: 110, cubes };
  },

  /** A pause glyph — two upright columns, holding still rather than working. */
  paused: (t) => {
    const cubes: Cube[] = [];
    for (const x of [0, 2]) {
      for (let z = 0; z < 3; z += 1) {
        cubes.push({ x, y: 0, z, style: anim("settle", 3.6, t) });
      }
    }
    return { width: 90, cubes };
  },

  /** A 2×2 block coming apart — each cube fades in reverse order, so the block
   *  reads as dissolving from the far corner back toward the viewer. */
  cancelling: (t) => {
    const cells: [number, number][] = [
      [0, 0],
      [1, 0],
      [0, 1],
      [1, 1],
    ];
    const cubes: Cube[] = cells.map(([x, y], i) => ({
      x,
      y,
      accent: i === 0,
      style: appear(2.4, (cells.length - 1 - i) * 0.3, t),
    }));
    return { width: 90, cubes };
  },

  /** The `writing` grid, mirrored: it fills right to left, like a record being
   *  taken back rather than typed. */
  undoing: (t) => {
    const cubes: Cube[] = [];
    for (let y = 0; y < 3; y += 1) {
      for (let x = 0; x < 4; x += 1) {
        cubes.push({
          x,
          y,
          accent: y === 2 && x === 0,
          style: appear(3.4, (y * 4 + (3 - x)) * 0.13, t),
        });
      }
    }
    return { width: W, cubes };
  },

  /** A 2×2×2 block missing its far top corner, the cube beneath the gap
   *  accented — most of the work landed, one piece did not. */
  partial: (t) => {
    const cubes: Cube[] = [];
    for (let x = 0; x < 2; x += 1) {
      for (let y = 0; y < 2; y += 1) {
        for (let z = 0; z < 2; z += 1) {
          if (x === 1 && y === 1 && z === 1) continue; // the missing corner
          cubes.push({
            x,
            y,
            z,
            accent: x === 1 && y === 1 && z === 0,
            style: anim("settle", 3.2, t),
          });
        }
      }
    }
    return { width: 110, cubes };
  },

  /** Two stacks, three grid steps apart — the same distance `delegating`'s
   *  courier travels — with one cube handed from the left stack to an open
   *  slot at the right. */
  handoff: (t) => {
    const cubes: Cube[] = [
      { x: 0, y: 0, style: anim("settle", 3, t) },
      { x: 3, y: 0, dashed: true },
    ];
    cubes.push({
      x: 0,
      y: 0,
      z: 1,
      boost: 100,
      accent: true,
      outer: anim("glide", 2.4, t, { alternate: true }),
    });
    return { width: 160, cubes };
  },

  /** One cube, dimmed and alone, settling slowly — nothing to show because
   *  nothing can be heard from. */
  offline: (t) => ({
    width: 60,
    cubes: [{ x: 0, y: 0, style: { ...anim("settle", 5, t), opacity: 0.55 } }],
  }),
};

export function sceneFor(state: Exclude<AgentState, "idle">, timing: Timing): Scene {
  return scenes[state](timing);
}

/**
 * The avatar contract.
 *
 * The console never imports a specific avatar. It takes an `AvatarRenderer` and
 * calls it, which is what makes the face genuinely swappable: a different art
 * direction — a mascot, a video, a Lottie, a photograph — is one module that
 * satisfies this type, and nothing in the state machine, the transcript or the
 * transport moves.
 *
 * The four props are the whole surface, and each earns its place:
 *   `state`  the only required one — which of the twenty-six to draw
 *   `size`   the console needs it at three scales; a renderer may ignore this
 *   `accent` the brand hook, so one avatar set serves several products
 *   `speed`  a global multiplier, for tuning the whole set at once
 */

import type { AgentState } from "../core/states";

export type AvatarSize = "sm" | "md" | "lg" | "xl";

export type AvatarRendererProps = {
  state: AgentState;
  size?: AvatarSize;
  /**
   * Any CSS colour. Passed straight through to `--agent-cube-accent`, so
   * `var(--agent)` works as well as a literal — and is what the console uses by
   * default, which is how the avatar follows a retheme.
   */
  accent?: string;
  /** Multiplier. Every duration in the set divides by this. */
  speed?: number;
  className?: string;
};

export type AvatarRenderer = (props: AvatarRendererProps) => React.ReactNode;

/**
 * Getting a file from the user to the agent, and back.
 *
 * The honest position, stated once here so no component has to reason about it:
 *
 *   A Lens message is a string. `sendMessage(text, context?)` has no binary
 *   channel, so the only way an attachment reaches the model is inside that
 *   string. Text-bearing files therefore travel in full and the agent can quote
 *   them; an image or a PDF cannot, and its filename travels instead.
 *
 * Both outcomes are recorded on the attachment as `delivery`, and the console
 * renders that distinction rather than showing one paperclip for both. A
 * paperclip that sometimes means "the agent read your spreadsheet" and sometimes
 * means "the agent knows you have a spreadsheet" is worse than no paperclip.
 *
 * The seam for fixing this properly is `TransportCapabilities.attachments`. A
 * transport that advertises `"content"` for binaries — a multimodal endpoint, or
 * Lens once `sendMessage` grows a content-parts overload — supplies its own
 * serialiser and nothing above this file changes.
 */

import { attachmentKind, type Attachment } from "./types";

/**
 * How much of one file we are willing to put in a prompt.
 *
 * 128k characters is roughly 32k tokens: enough for a real CSV export or a long
 * document, and short of the point where one attachment evicts the conversation
 * that motivated it. Truncation is announced in the payload rather than done
 * silently, because a model that reasons over half a file while believing it has
 * all of it produces confidently wrong answers.
 */
export const MAX_INLINE_CHARS = 128_000;

/** Above this, the picker refuses the file outright rather than reading it. */
export const MAX_FILE_BYTES = 25 * 1024 * 1024;

/** Kinds whose bytes are meaningfully text. */
const TEXTUAL = new Set(["data", "code", "other"]);

export function isTextual(attachment: Attachment): boolean {
  if (attachment.mime.startsWith("text/")) return true;
  if (attachment.mime === "application/json") return true;
  return TEXTUAL.has(attachment.kind) && attachment.kind !== "audio";
}

/**
 * Read what a File actually is, without trusting the picker's MIME.
 *
 * Browsers report `application/octet-stream` for plenty of ordinary text files
 * depending on the OS and the extension registry, so kind is derived from both
 * the MIME and the filename and the two are allowed to disagree.
 */
export async function readAttachment(file: File): Promise<Attachment> {
  const kind = attachmentKind(file.type, file.name);
  const base: Attachment = {
    id: `att-${crypto.randomUUID()}`,
    name: file.name,
    mime: file.type || "application/octet-stream",
    kind,
    size: file.size,
    url: URL.createObjectURL(file),
  };

  if (!isTextual(base)) return base;

  try {
    const text = await file.text();
    return { ...base, text };
  } catch {
    // An unreadable file still deserves to appear in the tray — the user picked
    // it, and silently dropping it looks like the picker is broken.
    return base;
  }
}

/**
 * Fold attachments into the message the agent receives.
 *
 * Returns the text to send plus the same attachments with `delivery` stamped on
 * each, so the transcript can say which ones actually made it.
 *
 * The block is delimited and named rather than pasted raw: a 3,000-line CSV
 * dropped into the middle of a sentence reads to the model as the user's own
 * words. The fences tell it where the user stops and the file starts.
 */
export function serialiseAttachments(
  text: string,
  attachments: Attachment[],
): { text: string; attachments: Attachment[] } {
  if (!attachments.length) return { text, attachments };

  const stamped: Attachment[] = [];
  const blocks: string[] = [];
  const referenced: string[] = [];

  for (const attachment of attachments) {
    // An image that has been through a vision pass carries its transcription on
    // `text`. It is fenced as an <image> rather than a <file> and labelled as a
    // reading, because the agent is receiving a description of a picture and not
    // the picture — and a model that believes it saw the thing itself will
    // answer questions the transcription cannot actually support.
    if (attachment.kind === "image" && attachment.text) {
      blocks.push(
        [
          `<image name="${escapeAttribute(attachment.name)}" type="${escapeAttribute(attachment.mime)}">`,
          "A vision model read this image on your behalf. Its reading follows.",
          attachment.text,
          "</image>",
        ].join("\n"),
      );
      stamped.push({ ...attachment, delivery: { sent: "content" } });
      continue;
    }

    if (attachment.text !== undefined && isTextual(attachment)) {
      const truncated = attachment.text.length > MAX_INLINE_CHARS;
      const body = truncated ? attachment.text.slice(0, MAX_INLINE_CHARS) : attachment.text;
      blocks.push(
        [
          `<file name="${escapeAttribute(attachment.name)}" type="${escapeAttribute(attachment.mime)}"${
            truncated ? ` truncated="true" of-bytes="${attachment.size}"` : ""
          }>`,
          body,
          "</file>",
        ].join("\n"),
      );
      stamped.push({ ...attachment, delivery: { sent: "content" } });
      continue;
    }

    referenced.push(`${attachment.name} (${attachment.mime}, ${formatBytes(attachment.size)})`);
    stamped.push({
      ...attachment,
      delivery: {
        sent: "reference",
        reason:
          attachment.kind === "image"
            ? "This agent's protocol carries text, so the image itself was not sent."
            : "This file is not text, so its contents could not be inlined.",
      },
    });
  }

  const parts = [text.trim()];
  if (blocks.length) parts.push(blocks.join("\n\n"));
  if (referenced.length) {
    // Stated as a fact about the conversation rather than as content, so the
    // model does not attempt to reason about bytes it was never given.
    parts.push(
      `<attached-but-not-readable>\n${referenced.join(
        "\n",
      )}\n</attached-but-not-readable>\nThe files above were attached by the user but their contents are not available to you. Ask the user to paste the relevant part if you need it.`,
    );
  }

  return { text: parts.filter(Boolean).join("\n\n"), attachments: stamped };
}

/**
 * Pull attachments back out of a tool result.
 *
 * The agent side of the same street: a tool that generates a report, a chart or
 * an export returns it under a known key, and the console renders it in the
 * transcript with a download. The key is namespaced so an ordinary result that
 * happens to have an `attachments` field is not mistaken for one.
 */
const PRODUCED_KEY = "__attachments";

export type ProducedAttachment = {
  name: string;
  mime: string;
  /** Inline content. One of `text` or `dataUrl` is required. */
  text?: string;
  dataUrl?: string;
};

export function extractProduced(result: unknown): Attachment[] {
  if (!result || typeof result !== "object") return [];
  const raw = (result as Record<string, unknown>)[PRODUCED_KEY];
  if (!Array.isArray(raw)) return [];

  const out: Attachment[] = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const { name, mime, text, dataUrl } = item as ProducedAttachment;
    if (typeof name !== "string" || typeof mime !== "string") continue;
    if (typeof text !== "string" && typeof dataUrl !== "string") continue;

    const url =
      typeof dataUrl === "string"
        ? dataUrl
        : URL.createObjectURL(new Blob([text as string], { type: mime }));

    out.push({
      id: `att-${crypto.randomUUID()}`,
      name,
      mime,
      kind: attachmentKind(mime, name),
      size: typeof text === "string" ? new Blob([text]).size : 0,
      url,
      ...(typeof text === "string" ? { text } : {}),
      delivery: { sent: "produced" },
    });
  }
  return out;
}

/** Strip the attachment envelope so the generative renderers see a clean result. */
export function withoutProduced(result: unknown): unknown {
  if (!result || typeof result !== "object") return result;
  if (!(PRODUCED_KEY in (result as Record<string, unknown>))) return result;
  const clone = { ...(result as Record<string, unknown>) };
  delete clone[PRODUCED_KEY];
  return clone;
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

function escapeAttribute(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

/**
 * Chat history, as an interface.
 *
 * The fourth seam. `AgentTransport` says what the console talks to,
 * `AvatarRenderer` what it looks like, `SpeechAdapter` what it sounds like — and
 * this says where its conversations live. A caller with Prisma, localStorage, an
 * API, or nothing at all satisfies the same type, and `ChatHistory` renders
 * identically over any of them.
 *
 * Nothing here is async-aware on purpose. The store owns its own loading and
 * error state and exposes the result; a component that had to await a rename
 * would need its own pending state for something the store already knows.
 */

import type { Attachment } from "./types";

export type ConversationSummary = {
  id: string;
  title: string;
  /** ISO timestamp. Rendered relative — "2 hours ago" — by the list. */
  updatedAt: string;
  /** First line of the opening message. Optional; the list degrades without it. */
  preview?: string;
  /**
   * Held at the top of the list, above the time-ordered rest.
   *
   * Optional because pinning is a capability rather than a guarantee: a store
   * that cannot persist the flag simply never sets it, and the list renders one
   * section instead of two. `ChatHistory` decides whether to draw the pin
   * affordance from whether `pin` exists on the store, never from whether this
   * happens to be true on some row.
   */
  pinned?: boolean;
};

/** A restored message. Deliberately narrower than AgentTurn — history is prose. */
export type RestoredMessage = {
  id: string;
  role: "user" | "assistant";
  content: string;
  attachments?: Attachment[];
};

export type ConversationStore = {
  conversations: ConversationSummary[];
  /** The conversation on screen, or null for an unsaved new one. */
  activeId: string | null;
  isLoading: boolean;
  error: string | null;
  /** Load a conversation into the console. */
  open: (id: string) => void;
  /** Clear the console and start an unsaved conversation. */
  create: () => void;
  rename: (id: string, title: string) => void;
  remove: (id: string) => void;
  /** Re-read the list. Called after the console stores a turn. */
  refresh: () => void;
  /**
   * Hold a conversation at the top of the list, or release it.
   *
   * Optional, and the list reads its own affordances off that: no `pin` on the
   * store means no pin button on a card and no pinned section above the list.
   * A control that cannot do anything should not be drawn, and a store that
   * cannot persist a preference should not be asked to pretend.
   */
  pin?: (id: string, pinned: boolean) => void;
  /**
   * Produce a shareable reference to a conversation.
   *
   * Optional for the same reason, and deliberately vague about what "share"
   * means: a link, a copied transcript, an export. That is the product's
   * decision, and the menu item only needs to know whether the product has one.
   */
  share?: (id: string) => void;
};

/**
 * Which of the twenty-six states is true right now.
 *
 * A pure function of the transcript plus a few signals, with no memory of its
 * own. That is the whole design: the face is *derived*, never set, so it cannot
 * claim to be running code when no tool is running. Every branch below points at
 * something that demonstrably happened.
 *
 * Twelve states are structural — they come out of the event stream and are true
 * for any agent. The other eight exist only because the caller told us what its
 * own tools do, through `toolStates`. That split is deliberate: this file will
 * not guess that a tool called `search_docs` means searching, because the next
 * codebase along will have one called `search` that formats a hard drive.
 *
 * Order is the specification. First match wins, and the ladder runs from "the
 * user must act" down through "the agent is acting" to "nothing is happening".
 */

import { runAvatarState, type Connection, type Run } from "./run";
import { stateForTool, type AgentState, type ToolStateMap } from "./states";
import type { ActionTurn, AgentSignals, AgentTurn, TextTurn, ToolTurn } from "./types";

export type ResolveInput = {
  turns: AgentTurn[];
  signals: AgentSignals;
  toolStates?: ToolStateMap;
  /** The run in progress, when there is one. Its status can force the face. */
  run?: Run | null;
  /** Transport connection health. Offline/reconnecting forces the face too. */
  connection?: Connection;
};

export function resolveState({ turns, signals, toolStates, run, connection }: ResolveInput): AgentState {
  // -1. A dead transport outranks even a declared state — an agent cannot
  //     assert "writing" over a socket that is not there to assert it on.
  //     This is the one part of the run/connection ladder that has to come
  //     before `declared`; the rest (run status) stays below it.
  const resolvedConnection = connection ?? "connected";
  if (resolvedConnection !== "connected") return "offline";

  // 0. An agent that reports its own state is believed. Nothing in this file can
  //    know better than the runtime does, so a declared state short-circuits the
  //    whole ladder. No Lens agent sends one today; the channel exists so that
  //    adding it later is a transport change and not a rewrite of this file.
  if (signals.declared) return signals.declared;

  // 0.5. The run lifecycle outranks the turn ladder below. A run that is
  //      paused, cancelling, undoing, partly failed or handed off is not
  //      something the ladder can see — it lives in `run.ts`, not in the
  //      events that make up `turns`.
  const forced = runAvatarState(run ?? null, resolvedConnection);
  if (forced) return forced;

  const last = turns.at(-1);

  // 1. A fatal error outranks everything. A non-fatal one does not: the agent
  //    recovers from those, and freezing the face on a red cube while it carries
  //    on working is worse than not showing it at all.
  if (last?.kind === "error" && last.fatal) return "error";

  // 2. Something is waiting on a human. This sits above the working states
  //    because it is the one situation where the agent has stopped and the user
  //    has not been told why.
  const heldForApproval = turns.some(
    (turn) => turn.kind === "action" && turn.approval === "pending",
  );
  if (heldForApproval) return "awaiting_approval";

  // 3. A tool in flight. What the tool *means* is the caller's to declare; all
  //    this knows is that one is running, hence the honest fallback.
  const runningTool = findLast(turns, (t): t is ToolTurn => t.kind === "tool" && t.status === "running");
  if (runningTool) {
    // A tool being tried again after it failed is a retry first and whatever it
    // does second — that is the more useful thing to show, because it is the
    // signal that the agent may be stuck.
    if (runningTool.attempt > 1) return "retrying";
    return stateForTool(runningTool.name, toolStates) ?? "calling_tools";
  }

  // 4. The browser is doing something on the agent's behalf.
  const runningAction = findLast(
    turns,
    (t): t is ActionTurn => t.kind === "action" && t.status === "running",
  );
  if (runningAction) return "processing";

  // 5. Prose is arriving. Which kind of prose depends on where in the turn we
  //    are, and that is knowable: text before any tool call is the model saying
  //    what it intends to do, text after one is it accounting for what it found,
  //    and text in a turn with no tools at all is just an answer.
  if (last?.kind === "text" && last.streaming) {
    return narrationState(turns, last);
  }

  // 5.5. A plan step is running. `runAvatarState` (0.5, above) returns null
  //      for `run.status === "running"` on purpose — a run mid-step still
  //      wants the turn ladder's finer-grained states (a running tool, a
  //      pending approval) when one applies. But a run can advance a step
  //      with no new *turn* at all — `reduceRunEvent` folds `step_status`
  //      into `run.plan`, never into `turns` — so nothing above this line
  //      necessarily saw it happen. Bug 7: without this, a run that started
  //      running while `awaitingFirstEvent` was still true (see
  //      `agent-workspace.tsx`'s own fix for why that flag used to outlive
  //      the whole run) fell through to `queued` and stayed there for as
  //      long as the step ran.
  if (run?.status === "running") return "processing";

  // 6. Sent, nothing back yet. Distinct from `thinking` — the request may not
  //    have reached a model at all, and a queue is an honest thing to show.
  if (signals.awaitingFirstEvent) return "queued";

  // 7. Loading with nothing else to say about it.
  if (signals.isLoading) return "thinking";

  // 8. A turn that finished. The console holds this briefly and then falls to
  //    idle; the hold is a render concern, not a resolution one, so all that
  //    happens here is reporting that the last thing was a completed answer.
  if (last && isSettled(last)) return "done";

  return "idle";
}

/**
 * Planning or summarizing.
 *
 * The distinction is what came before this paragraph *in the current turn*, so
 * the scan walks back only as far as the user's last message. Text after work is
 * an account of it; text before work is a plan for it.
 *
 * Note what is NOT decided here: `writing`. Mid-stream there is no way to tell
 * an opening paragraph that precedes three tool calls from one that is the whole
 * answer — the difference is entirely in tokens that have not arrived yet.
 * Rather than guess, prose always reads as planning or summarizing, and
 * `writing` is reached the one way it can be proven: a caller maps its mutating
 * tools onto it (`orders.create`, `fs.write`, `leave.decide`). The avatar's
 * writing scene fills a grid in cube by cube, which reads correctly for a record
 * being written — and would read as a lie over a paragraph that turned out to be
 * a preamble.
 */
function narrationState(turns: AgentTurn[], current: TextTurn): AgentState {
  for (let i = turns.length - 1; i >= 0; i -= 1) {
    const turn = turns[i];
    if (turn === current) continue;
    if (turn.kind === "user") break;
    if (turn.kind === "tool" || turn.kind === "action") return "summarizing";
  }
  return "planning";
}

/** A turn that represents a finished piece of work. */
function isSettled(turn: AgentTurn): boolean {
  if (turn.kind === "text") return turn.streaming !== true;
  if (turn.kind === "tool" || turn.kind === "action") return turn.status !== "running";
  return turn.kind === "error";
}

function findLast<T extends AgentTurn>(
  turns: AgentTurn[],
  predicate: (turn: AgentTurn) => turn is T,
): T | null {
  for (let i = turns.length - 1; i >= 0; i -= 1) {
    if (predicate(turns[i])) return turns[i] as T;
  }
  return null;
}

/**
 * The run lifecycle — what one task the agent carries out is doing.
 *
 * The transcript (`timeline.ts`) is what was said. A run is what was DONE: a
 * plan, the effects it had outside the chat, the checkpoints it can resume
 * from, the queue behind it, and — when it cannot finish — who owns it now.
 * Twelve statuses, from the 2026 agent-UX run model; the seven rules the
 * reducer enforces are listed in the spec and tested one by one.
 *
 * Imports nothing but types from `core/`, like every file here.
 */

import type { AgentState } from "./states";
import type { Attachment } from "./types";

export type RunStatus =
  | "proposed" | "queued" | "running" | "paused" | "waiting_for_approval"
  | "partially_failed" | "cancelling" | "cancelled"
  | "compensating" | "compensated" | "handoff_required" | "completed";

export type StepStatus = "pending" | "running" | "done" | "failed" | "skipped";
export type Confidence = "high" | "low";
export type EffectStatus = "committed" | "failed" | "unknown" | "reversed";
export type Connection = "connected" | "reconnecting" | "offline";

export type PlanStep = {
  id: string;
  title: string;
  detail?: string;
  status: StepStatus;
  confidence?: Confidence;
  ms?: number;
};

export type Effect = {
  id: string;
  stepId: string;
  description: string;
  target: string;
  status: EffectStatus;
  reversible: boolean;
  error?: string;
};

export type Checkpoint = { id: string; label: string; turnId: string; at: number; stepId?: string };
export type QueueItem = { id: string; text: string; attachments?: Attachment[]; model?: string; at: number };
export type Handoff = {
  goal: string;
  done: string[];
  failed: string[];
  unknown: string[];
  owner?: string;
  note?: string;
};

/** What failed, why, and what to try next — never a bare "something went wrong". */
export type RunError = {
  what: string;
  why: string;
  next: string;
  kind: "understanding" | "tool" | "access" | "action" | "connection";
  fatal: boolean;
};

export type Run = {
  id: string;
  version: number;
  goal: string;
  status: RunStatus;
  plan: PlanStep[];
  effects: Effect[];
  checkpoints: Checkpoint[];
  queue: QueueItem[];
  handoff?: Handoff;
  error?: RunError;
  startedAt: number;
  endedAt?: number;
};

export type ActivityKind = "status" | "step" | "effect" | "checkpoint" | "approval" | "handoff" | "connection" | "queue";
export type ActivityEntry = {
  id: string;
  at: number;
  kind: ActivityKind;
  text: string;
  status?: StepStatus | EffectStatus | RunStatus;
  /** Why an approval entry was refused, so the UI never has to read `text`. */
  reason?: "approval_expired" | "approval_stale";
};

export type RunState = {
  run: Run | null;
  connection: Connection;
  timeline: ActivityEntry[];
  /** Event ids already applied (rule 2). */
  seen: readonly string[];
};

export const EMPTY_RUN_STATE: RunState = { run: null, connection: "connected", timeline: [], seen: [] };

type Base = { eventId: string; at: number };
export type RunEvent =
  | (Base & { type: "run_proposed"; runId: string; goal: string; version: number; plan: PlanStep[] })
  | (Base & { type: "plan_edited"; version: number; plan: PlanStep[] })
  | (Base & { type: "plan_approved"; version: number })
  | (Base & { type: "run_status"; status: RunStatus; error?: RunError; resumeFrom?: string })
  | (Base & { type: "step_status"; stepId: string; status: StepStatus; confidence?: Confidence; ms?: number })
  | (Base & { type: "effect"; outcome: "committed" | "failed" | "timeout" | "reversed"; effect: Omit<Effect, "status"> })
  | (Base & { type: "checkpoint"; checkpoint: Checkpoint })
  | (Base & { type: "approval_expired"; version: number })
  | (Base & { type: "handoff"; handoff: Handoff })
  | (Base & { type: "queue"; queue: QueueItem[] })
  | (Base & { type: "connection"; connection: Connection });

export const RUN_STATUS_LABEL: Record<RunStatus, string> = {
  proposed: "Waiting for your approval",
  queued: "Queued",
  running: "Running",
  paused: "Paused",
  waiting_for_approval: "Waiting for your approval",
  partially_failed: "Partly done",
  cancelling: "Stopping…",
  cancelled: "Stopped",
  compensating: "Undoing changes…",
  compensated: "Changes undone",
  handoff_required: "Needs a person",
  completed: "Done",
};

const EFFECT_STATUS: Record<"committed" | "failed" | "timeout" | "reversed", EffectStatus> = {
  committed: "committed",
  failed: "failed",
  timeout: "unknown",
  reversed: "reversed",
};

function log(state: RunState, e: RunEvent, kind: ActivityKind, text: string, status?: ActivityEntry["status"], reason?: ActivityEntry["reason"]): ActivityEntry[] {
  return [...state.timeline, { id: e.eventId, at: e.at, kind, text, status, ...(reason ? { reason } : {}) }];
}

function withRun(state: RunState, run: Run, timeline = state.timeline): RunState {
  return { ...state, run, timeline };
}

export function reduceRunEvent(state: RunState, e: RunEvent): RunState {
  if (state.seen.includes(e.eventId)) return state;
  const next = { ...state, seen: [...state.seen, e.eventId] };
  const run = next.run;

  switch (e.type) {
    case "run_proposed": {
      const fresh: Run = {
        id: e.runId, version: e.version, goal: e.goal, status: "proposed", plan: e.plan,
        effects: [], checkpoints: [], queue: run?.queue ?? [], startedAt: e.at,
      };
      return withRun(next, fresh, log(next, e, "status", `Plan proposed: ${e.goal}`, "proposed"));
    }
    case "connection":
      return {
        ...next,
        connection: e.connection,
        timeline: log(next, e, "connection", e.connection === "connected" ? "Connection restored" : e.connection === "reconnecting" ? "Connection lost — reconnecting" : "Offline"),
      };
    case "queue":
      return run
        ? withRun(next, { ...run, queue: e.queue })
        : { ...next, run: null };
  }

  if (!run) return next;

  switch (e.type) {
    case "plan_edited":
      return withRun(next, { ...run, version: e.version, plan: e.plan, status: "proposed" },
        log(next, e, "approval", `Plan edited — now v${e.version}`, "proposed"));
    case "plan_approved":
      if (e.version < run.version) {
        return { ...next, timeline: log(next, e, "approval", `Approval for plan v${e.version} rejected — the plan is now v${run.version}`, undefined, "approval_stale") };
      }
      return withRun(next, { ...run, status: "running" }, log(next, e, "approval", `Plan v${e.version} approved`, "running"));
    case "approval_expired": {
      const version = run.version + 1;
      return withRun(next, { ...run, version, status: "proposed" },
        log(next, e, "approval", `Approval for plan v${e.version} expired — approve v${version} to continue`, "proposed", "approval_expired"));
    }
    case "run_status": {
      let plan = run.plan;
      if (e.resumeFrom) {
        const rerun = new Set(stepsAfterCheckpoint(run, e.resumeFrom));
        plan = plan.map((p) => (rerun.has(p.id) ? { ...p, status: "pending" as const, ms: undefined } : p));
      }
      const terminal = e.status === "completed" || e.status === "cancelled" || e.status === "compensated";
      return withRun(next, { ...run, plan, status: e.status, error: e.error ?? run.error, endedAt: terminal ? e.at : run.endedAt },
        log(next, e, "status", e.resumeFrom ? `Resumed from checkpoint` : RUN_STATUS_LABEL[e.status], e.status));
    }
    case "step_status": {
      let plan = run.plan.map((p) =>
        p.id === e.stepId ? { ...p, status: e.status, confidence: e.confidence ?? p.confidence, ms: e.ms ?? p.ms } : p);
      let status = run.status;
      const settled = e.status !== "running" && e.status !== "pending";
      if (run.status === "cancelling" && settled) {
        status = "cancelled";
        plan = plan.map((p) => (p.status === "pending" ? { ...p, status: "skipped" as const } : p));
      }
      const title = run.plan.find((p) => p.id === e.stepId)?.title ?? e.stepId;
      return withRun(next, { ...run, plan, status, endedAt: status === "cancelled" ? e.at : run.endedAt },
        log(next, e, "step", title, e.status));
    }
    case "effect": {
      const status = EFFECT_STATUS[e.outcome];
      const exists = run.effects.some((f) => f.id === e.effect.id);
      const effects = exists
        ? run.effects.map((f) => (f.id === e.effect.id ? { ...f, ...e.effect, status } : f))
        : [...run.effects, { ...e.effect, status }];
      return withRun(next, { ...run, effects }, log(next, e, "effect", e.effect.description, status));
    }
    case "checkpoint":
      return withRun(next, { ...run, checkpoints: [...run.checkpoints, e.checkpoint] },
        log(next, e, "checkpoint", `Checkpoint: ${e.checkpoint.label}`));
    case "handoff":
      return withRun(next, { ...run, status: "handoff_required", handoff: e.handoff },
        log(next, e, "handoff", "Handed off to a person", "handoff_required"));
  }
  return next;
}

/** Rule 7: the steps after a checkpoint, in plan order. */
export function stepsAfterCheckpoint(run: Run, checkpointId: string): string[] {
  const cp = run.checkpoints.find((c) => c.id === checkpointId);
  if (!cp?.stepId) return run.plan.map((p) => p.id);
  const at = run.plan.findIndex((p) => p.id === cp.stepId);
  return run.plan.slice(at + 1).map((p) => p.id);
}

/** Rule 5: what undoing would reverse, newest first, and what it cannot. */
export function compensationOrder(run: Run): { reverse: Effect[]; irreversible: Effect[] } {
  const committed = run.effects.filter((f) => f.status === "committed");
  return {
    reverse: committed.filter((f) => f.reversible).reverse(),
    irreversible: committed.filter((f) => !f.reversible),
  };
}

/**
 * The avatar state a run forces, or null when the turn-derived state should win.
 * Full precedence, enforced by `resolveState`: connection → declared → run
 * status → the transcript. This function covers only the run-status half.
 */
export function runAvatarState(run: Run | null, connection: Connection): AgentState | null {
  if (connection !== "connected") return "offline";
  if (!run) return null;
  switch (run.status) {
    case "proposed":
    case "waiting_for_approval": return "awaiting_approval";
    case "queued": return "queued";
    case "paused": return "paused";
    case "cancelling": return "cancelling";
    case "cancelled": return "idle";
    case "compensating": return "undoing";
    case "compensated":
    case "completed": return "done";
    case "partially_failed": return "partial";
    case "handoff_required": return "handoff";
    case "running": return null;
  }
}

/**
 * The agent's stream, folded into something renderable.
 *
 * A transport maintains its own message list, but those only ever hold user and
 * assistant *text* — tool calls, tool results and action requests arrive on the
 * event channel and are then dropped. Those are the interesting half of an
 * agentic product, so the console keeps its own timeline built from the raw
 * events and treats the transport purely as delivery.
 *
 * Every entry is immutable; settling a tool call replaces the entry rather than
 * mutating it, so React sees a new array and the renderers stay pure.
 */

import type { AgentEvent, AgentTurn, Attachment, TextTurn, ToolTurn } from "./types";

let seq = 0;
const nextId = () => `turn-${(seq += 1)}`;

/** Reset the id counter. Tests only — ids are otherwise process-lifetime unique. */
export function __resetIds() {
  seq = 0;
}

/** Replace the most recent entry matching `match`. Returns the array unchanged if there is none. */
function settleLast(
  turns: AgentTurn[],
  match: (turn: AgentTurn) => boolean,
  update: (turn: AgentTurn) => AgentTurn,
): AgentTurn[] {
  for (let i = turns.length - 1; i >= 0; i -= 1) {
    if (match(turns[i])) {
      const next = turns.slice();
      next[i] = update(turns[i]);
      return next;
    }
  }
  return turns;
}

export function userTurn(text: string, attachments?: Attachment[]): AgentTurn {
  return {
    kind: "user",
    id: nextId(),
    text,
    at: Date.now(),
    ...(attachments?.length ? { attachments } : {}),
  };
}

/**
 * How many times this tool has already been tried and failed in this run.
 *
 * A model that calls the same tool again after an error is retrying, and that is
 * worth showing — it is the difference between "still working" and "stuck". The
 * count is scoped to the tool name rather than to its arguments, because a retry
 * with corrected arguments is still a retry.
 */
function priorFailures(turns: AgentTurn[], name: string): number {
  let count = 0;
  for (const turn of turns) {
    if (turn.kind === "tool" && turn.name === name && turn.status === "error") count += 1;
  }
  return count;
}

/**
 * Page control arrives twice.
 *
 * A DOM action is invoked through the same tool syntax as everything else, so
 * the runtime emits a tool_call *and* an action_request for it, then a
 * tool_result once the browser reports back. Rendering both puts the same step
 * on screen twice under two different names. The action entry is the one worth
 * keeping — it reads as a sentence and is timed by the browser that did the
 * work — so the tool half is dropped here rather than filtered in the console.
 *
 * Supplied by the transport, because which names are DOM actions is a property
 * of the agent, not of the timeline.
 */
export type ReduceOptions = { domActions?: ReadonlySet<string> };

export function reduceEvent(
  turns: AgentTurn[],
  event: AgentEvent,
  options: ReduceOptions = {},
): AgentTurn[] {
  const domActions = options.domActions;
  if (
    (event.type === "tool_call" || event.type === "tool_result") &&
    domActions?.has(event.name)
  ) {
    return turns;
  }

  switch (event.type) {
    case "text": {
      if (!event.content) return turns;
      const last = turns.at(-1);
      if (last?.kind === "text") {
        return settleLast(
          turns,
          (turn) => turn === last,
          (turn) => ({ ...(turn as TextTurn), text: last.text + event.content, streaming: true }),
        );
      }
      return [...turns, { kind: "text", id: nextId(), text: event.content, streaming: true, at: Date.now() }];
    }

    case "tool_call":
      return [
        ...closeStreaming(turns),
        {
          kind: "tool",
          id: nextId(),
          name: event.name,
          params: event.parameters ?? {},
          status: "running",
          startedAt: Date.now(),
          attempt: priorFailures(turns, event.name) + 1,
        },
      ];

    case "tool_progress":
      return settleLast(
        turns,
        (turn) => turn.kind === "tool" && turn.name === event.name && turn.status === "running",
        (turn) => ({ ...(turn as ToolTurn), partial: event.partial }),
      );

    case "tool_result":
      return settleLast(
        turns,
        (turn) => turn.kind === "tool" && turn.name === event.name && turn.status === "running",
        (turn) => {
          const tool = turn as ToolTurn;
          return {
            ...tool,
            status: event.result?.success ? "ok" : "error",
            result: event.result?.result,
            error: event.result?.error,
            ...(event.attachments?.length ? { attachments: event.attachments } : {}),
            ms: Date.now() - tool.startedAt,
          };
        },
      );

    case "action_request":
      return [
        ...closeStreaming(turns),
        {
          kind: "action",
          // The correlation id is already unique per request and is what the
          // action bridge will quote back when the browser reports the outcome.
          id: event.correlationId,
          action: event.action,
          params: event.parameters ?? {},
          status: "running",
          startedAt: Date.now(),
        },
      ];

    case "error":
      return [
        ...closeStreaming(turns),
        { kind: "error", id: nextId(), message: event.error, fatal: event.fatal },
      ];

    case "done":
      return closeStreaming(turns);

    case "sources":
      return withStreamingText(turns, (turn) => ({ ...turn, sources: event.sources }));

    case "suggestions":
      return withStreamingText(turns, (turn) => ({ ...turn, suggestions: event.items }));

    case "reasoning":
      return withStreamingText(turns, (turn) => ({
        ...turn,
        reasoning: { steps: [...(turn.reasoning?.steps ?? []), event.step], ms: turn.reasoning?.ms },
      }));

    case "reasoning_done":
      return withStreamingText(turns, (turn) => ({
        ...turn,
        reasoning: { steps: turn.reasoning?.steps ?? [], ms: event.ms },
      }));

    case "confidence":
      return withStreamingText(turns, (turn) => ({ ...turn, confidence: event.confidence }));

    case "run":
      // Run events are folded by the transport with `reduceRunEvent`
      // (run.ts), not by the transcript. Nothing here to do.
      return turns;

    default:
      return turns;
  }
}

/**
 * Apply `update` to the current streaming answer, creating one first if the
 * transcript has none — reasoning can arrive before the first text token.
 */
function withStreamingText(
  turns: AgentTurn[],
  update: (turn: TextTurn) => TextTurn,
): AgentTurn[] {
  const last = turns.at(-1);
  if (last?.kind === "text" && last.streaming) {
    return settleLast(turns, (turn) => turn === last, (turn) => update(turn as TextTurn));
  }
  return [...turns, update({ kind: "text", id: nextId(), text: "", streaming: true, at: Date.now() })];
}

/**
 * Mark the trailing text turn as finished streaming.
 *
 * Called whenever something other than more text arrives. Without it the cursor
 * keeps blinking on a paragraph the model stopped writing several tool calls
 * ago, and `resolveState` cannot tell "writing" from "wrote".
 */
function closeStreaming(turns: AgentTurn[]): AgentTurn[] {
  const last = turns.at(-1);
  if (last?.kind !== "text" || !last.streaming) return turns;
  return settleLast(
    turns,
    (turn) => turn === last,
    (turn) => ({ ...(turn as TextTurn), streaming: false }),
  );
}

/** Called once the browser has actually performed a DOM action. */
export function settleAction(
  turns: AgentTurn[],
  action: string,
  outcome: { success: boolean; error?: string },
): AgentTurn[] {
  return settleLast(
    turns,
    (turn) => turn.kind === "action" && turn.action === action && turn.status === "running",
    (turn) => {
      const step = turn as Extract<AgentTurn, { kind: "action" }>;
      return {
        ...step,
        status: outcome.success ? "ok" : "error",
        error: outcome.error,
        ms: Date.now() - step.startedAt,
      };
    },
  );
}

/** Flag an action turn as held at an approval gate. */
export function markApproval(
  turns: AgentTurn[],
  turnId: string,
  approval: "pending" | "approved" | "rejected",
): AgentTurn[] {
  return settleLast(
    turns,
    (turn) => turn.kind === "action" && turn.id === turnId,
    (turn) => ({ ...(turn as Extract<AgentTurn, { kind: "action" }>), approval }),
  );
}

/**
 * Remove the agent protocol's control tags from text destined for a human.
 *
 * The Lens runtime ends every completed turn with `</complete>` and does not
 * strip it. Because text arrives in chunks a tag can also be split across two
 * events, so a trailing partial tag is swallowed too — otherwise the user
 * watches `</comp` sit at the end of a sentence for a beat.
 */
export function stripProtocol(text: string): string {
  return text.replace(/<\/?complete>/g, "").replace(/<\/?[a-z]*$/i, "");
}

/**
 * The vocabulary the workspace renders.
 *
 * Everything here is transport-agnostic on purpose. A transport adapter turns
 * one agent's wire protocol into these shapes; another agent gets another
 * adapter and the rest of the component does not move. Nothing in this file
 * imports React, an SDK, or anything from the product.
 */

import type { LucideIcon } from "lucide-react";
import type { RestoredMessage } from "./conversations";
import type { AgentState } from "./states";

/* ── Attachments ─────────────────────────────────────────────────────────────
 *
 * Deliberately one type in both directions. A file the user picks and a file the
 * agent produces are the same object to everything that draws them, which is
 * what stops the transcript growing two parallel renderers that drift.
 *
 * `text` is the content when we actually hold it. `url` is a blob: or data:
 * source for previewing and downloading. Either may be absent: a 40MB PDF has a
 * url and no text, a tool-generated CSV may have text and no url until one is
 * minted for the download link.
 */

export type AttachmentKind = "image" | "document" | "data" | "code" | "audio" | "other";

export type Attachment = {
  id: string;
  name: string;
  /** MIME type as reported by the picker, or asserted by the producing tool. */
  mime: string;
  kind: AttachmentKind;
  /** Bytes. Shown to the user, and what the size cap is enforced against. */
  size: number;
  /** Object URL for preview and download. Revoked when the workspace unmounts. */
  url?: string;
  /**
   * Decoded content, for the kinds where holding it is useful and cheap.
   * This is also what the transport inlines into the message — see
   * `serialiseAttachments` in `attachments.ts`.
   */
  text?: string;
  /** Set by the transport once it knows whether the content actually travelled. */
  delivery?: AttachmentDelivery;
};

/**
 * Whether the agent can genuinely see this attachment.
 *
 * Stated rather than implied, because the honest answer varies by transport and
 * by file type, and a paperclip icon that means "we sent the name" looks exactly
 * like one that means "we sent the file". The workspace renders this.
 */
export type AttachmentDelivery =
  /** Content was inlined into the message. The agent can read it. */
  | { sent: "content" }
  /** Only the filename and type travelled. The agent knows it exists, nothing more. */
  | { sent: "reference"; reason: string }
  /** Produced by the agent, so delivery does not apply. */
  | { sent: "produced" };

/** Classify by MIME first, extension second — pickers lie about MIME often enough. */
export function attachmentKind(mime: string, name: string): AttachmentKind {
  if (mime.startsWith("image/")) return "image";
  if (mime.startsWith("audio/")) return "audio";
  const ext = name.slice(name.lastIndexOf(".") + 1).toLowerCase();
  if (mime === "application/pdf" || ext === "pdf") return "document";
  if (/^(docx?|odt|rtf|pages)$/.test(ext)) return "document";
  if (/^(csv|tsv|json|xlsx?|ods|parquet)$/.test(ext)) return "data";
  if (mime === "application/json" || mime === "text/csv") return "data";
  if (/^(ts|tsx|js|jsx|py|rb|go|rs|java|c|h|cpp|sql|sh|yml|yaml|toml|css|html)$/.test(ext)) {
    return "code";
  }
  if (mime.startsWith("text/") || /^(txt|md|log)$/.test(ext)) return "other";
  return "other";
}

/* ── Events ──────────────────────────────────────────────────────────────────
 *
 * The wire contract, restated locally. The Lens SDK declares equivalents but
 * does not re-export them from any of its entry points, and restating them is
 * what lets a non-Lens transport exist at all.
 */

export type AgentEvent =
  | { type: "text"; content: string }
  | { type: "tool_call"; name: string; parameters: Record<string, unknown> }
  /**
   * What a running tool has produced so far — a terminal's output, the tests
   * finished yet. Replaces the running call's `partial`; `tool_result` settles it.
   */
  | { type: "tool_progress"; name: string; partial: unknown }
  | {
      type: "tool_result";
      name: string;
      result: { success: boolean; result?: unknown; error?: string };
      /** Files the tool produced. Rendered in the transcript beside the chip. */
      attachments?: Attachment[];
    }
  | { type: "action_request"; correlationId: string; action: string; parameters: Record<string, unknown> }
  | { type: "error"; error: string; fatal: boolean }
  | { type: "done" }
  | { type: "sources"; sources: Source[] }
  | { type: "reasoning"; step: string }
  | { type: "reasoning_done"; ms: number }
  | { type: "confidence"; confidence: import("./run").Confidence }
  /** Follow-up prompts the agent offers under this answer. */
  | { type: "suggestions"; items: string[] }
  | { type: "run"; event: import("./run").RunEvent };

/* ── Sources & regenerations ─────────────────────────────────────────────── */

/** A citation the answer points at. `n` is the footnote number shown inline. */
export type Source = { id: string; n: number; title: string; url: string; domain: string; snippet?: string };

/** One alternative wording of a turn, kept so the user can flip between them. */
export type Version = { id: string; text: string };

/* ── Turns ───────────────────────────────────────────────────────────────── */

export type TurnStatus = "running" | "ok" | "error";

export type UserTurn = {
  kind: "user";
  id: string;
  text: string;
  attachments?: Attachment[];
  /** Prior wordings of this message, when it has been edited. */
  versions?: Version[];
  /** Index into `versions` currently shown, when there are any. */
  activeVersion?: number;
  /** When the message was sent, epoch ms — the meta row's "2m ago". Absent renders no time. */
  at?: number;
};

export type TextTurn = {
  kind: "text";
  id: string;
  text: string;
  attachments?: Attachment[];
  /** When the answer started arriving, epoch ms. Absent renders no time. */
  at?: number;
  /**
   * True while this is the turn the model is still streaming into. The
   * transcript uses it for the cursor, and the resolver uses it to tell
   * "writing" from "written".
   */
  streaming?: boolean;
  /** Citations the answer points at, keyed by footnote number. */
  sources?: Source[];
  /** Prior regenerated answers, when the user asked for another take. */
  regenerations?: Version[];
  /** Index into `regenerations` currently shown, when there are any. */
  activeVersion?: number;
  /** How sure the model says it is about this answer. */
  confidence?: import("./run").Confidence;
  /**
   * Follow-up prompts offered under this answer — distinct from a workspace's
   * starter prompts, which only belong to an empty conversation.
   */
  suggestions?: string[];
  /** The chain-of-thought summary shown collapsed above the answer. */
  reasoning?: { steps: string[]; ms?: number };
  /** The model that wrote this answer, when the transport knows it. */
  model?: string;
};

export type ToolTurn = {
  kind: "tool";
  id: string;
  name: string;
  params: Record<string, unknown>;
  status: TurnStatus;
  result?: unknown;
  /** What the call has produced while still running — see `tool_progress`. */
  partial?: unknown;
  error?: string;
  attachments?: Attachment[];
  /** Wall-clock at dispatch, and how long the call took once settled. */
  startedAt: number;
  ms?: number;
  /** Incremented when the same tool is re-called after a failure. Drives `retrying`. */
  attempt: number;
};

export type ActionTurn = {
  kind: "action";
  id: string;
  action: string;
  params: Record<string, unknown>;
  status: TurnStatus;
  error?: string;
  startedAt: number;
  ms?: number;
  /** Set when this action is held at an approval card rather than run. */
  approval?: "pending" | "approved" | "rejected";
};

export type ErrorTurn = { kind: "error"; id: string; message: string; fatal: boolean };

export type AgentTurn = UserTurn | TextTurn | ToolTurn | ActionTurn | ErrorTurn;

/* ── Transport ───────────────────────────────────────────────────────────────
 *
 * The one interface that has to be implemented to point this workspace at a
 * different agent. Everything above the line is pure; everything below it is
 * somebody else's protocol.
 */

export type SendOptions = {
  attachments?: Attachment[];
  /** Chosen in the model picker. A transport that cannot switch models ignores it. */
  model?: string;
  /**
   * What actually goes on the wire, when that differs from what the user wrote.
   *
   * Attachments are folded into the message text — see `serialiseAttachments` —
   * which means the string the agent receives carries file contents and a block
   * explaining what could not be sent. None of that is the user's sentence, and
   * showing it back to them in their own message bubble reads as the product
   * leaking its plumbing. So the transcript keeps `text` and the transport sends
   * this.
   */
  wireText?: string;
  /**
   * Workspace preferences chosen in the settings sheet — autonomy mode,
   * sampling temperature, response length — forwarded only when the
   * transport advertises `capabilities.settings`. A transport with no way to
   * receive these never sees the field at all, so the gate stays honest end
   * to end rather than only hiding the controls that would have set it.
   */
  settings?: {
    autonomy: "ask" | "plan" | "act";
    temperature: number;
    length: number;
    /** The Prompt Bar's effort level, low to high — "Low" … "Max". */
    effort?: string;
  };
  /**
   * Ids of the sources the user picked with @. A transport without retrieval
   * ignores it — nothing renders or forwards this unless
   * `capabilities.sources` is true, the same honesty rule every other
   * `SendOptions` field follows.
   */
  sources?: string[];
  /** The composer's web-search toggle. A transport without search ignores it. */
  webSearch?: boolean;
};

export type AgentTransport = {
  /** The transcript, in order. Owned by the transport so it can settle tool calls. */
  turns: AgentTurn[];
  send: (text: string, options?: SendOptions) => Promise<void>;
  abort: () => void;
  reset: () => void;
  isLoading: boolean;
  error: Error | null;
  /**
   * False while the transport is still acquiring whatever it needs before it can
   * carry a message — a session cookie, a socket, a warm handler. The composer
   * disables itself rather than dropping the first message on the floor.
   */
  isReady: boolean;
  /**
   * Replace the timeline with a stored conversation.
   *
   * The transport owns `turns`, so it is what restores them. Optional: a
   * transport with no history behind it simply does not implement this, and the
   * workspace renders no history control.
   */
  restore?: (messages: RestoredMessage[]) => void;
  /**
   * Requests the transport is holding at an approval gate, keyed by turn id.
   * Answering one resolves the promise the agent is blocked on.
   */
  pendingApprovals: PendingApproval[];
  /** Advertised so the workspace can render only what this agent can actually do. */
  capabilities: TransportCapabilities;
  /**
   * The agent-side session this conversation is running under, when the
   * transport has one. Stored alongside a conversation so reopening it resumes
   * the agent's own memory rather than starting a stranger behind an old title.
   */
  sessionId?: string;

  /* ── Run lifecycle ─────────────────────────────────────────────────────
   *
   * All optional. A transport with no run model (most of them, today) simply
   * does not implement these, and the workspace renders none of the plan/queue/
   * checkpoint UI — `capabilities` is what a control actually gates on, this
   * is what makes the gate honest.
   */

  /** The run in progress, when the transport has one. */
  runState?: import("./run").RunState;
  /** Approve a proposed or edited plan. `plan` when the caller is also editing it. */
  approvePlan?: (version: number, plan?: import("./run").PlanStep[]) => void;
  pause?: () => void;
  resume?: (checkpointId?: string) => void | Promise<void>;
  cancel?: () => void;
  skipStep?: (stepId: string) => void;
  retryStep?: (stepId: string) => void;
  /** Re-confirms a low-confidence step, clearing its `ConfidenceMark` banner. */
  verifyStep?: (stepId: string) => void;
  retryEffect?: (effectId: string) => void;
  compensate?: () => void;
  /** Hand the run to a person. `owner` names who takes it, when the caller chose one. */
  handoff?: (note?: string, owner?: string) => void;
  /**
   * Answers an approval gate that requires a one-time code rather than a
   * plain yes/no. `false` means the code was wrong — the caller (`CodeGate`,
   * `components/agent/parts/approval-card.tsx`) clears the field and shows an
   * inline error rather than silently doing nothing. `true`, `void` or a
