  /** Lifespan: the spark fades in, then out, over this long. */
  span: number;
};

/** How sparks are born. */
export const SPAWN = {
  /** Sparks scattered through the box the moment the field arms. */
  SCATTERED: 26,
  /** Population ceiling while running. */
  MAX: 30,
  /** One new spark from the bottom edge this often, until the ceiling. */
  INTERVAL_S: 0.14,
  /** Fraction of the box's height, from the top, where scattered sparks may start. */
  SCATTER_TOP: 0.2,
  /** Head start on its age that a scattered spark may be given (random up to this). */
  HEAD_START_S: 1.2,
  /** How far below the bottom edge a rising spark starts, and the top edge it recycles past. */
  MARGIN_PX: 3,
  RECYCLE_ABOVE_PX: 4,
} as const;

/** How sparks look and move at rest. */
export const SPARK = {
  RADIUS_MIN_PX: 0.9,
  RADIUS_SPREAD_PX: 1.1,
  RISE_MIN_PX_S: 7,
  RISE_SPREAD_PX_S: 9,
  /** Total sideways range, so a spark drifts +/- half of it. */
  SWAY_RANGE_PX: 10,
  LIFE_MIN_S: 2.4,
  LIFE_SPREAD_S: 2.4,
  /** Sparks fade out within this distance of the top and bottom edges. */
  EDGE_FADE_PX: 14,
  /** Drift wave: period 2*pi*this ms at rest, quickened by typing. */
  SWAY_MS: 900,
  /** Twinkle wave: likewise. */
  TWINKLE_MS: 160,
  TWINKLE_FLOOR: 0.7,
  TWINKLE_DEPTH: 0.3,
} as const;

/** What typing does to the field. */
export const TYPING = {
  /** Energy one keystroke adds, and the most it can hold. */
  PER_KEY: 0.22,
  CAP: 1.6,
  /** Energy decays exponentially with this time constant. */
  TIME_CONSTANT_S: 0.8,
  /** A keystroke also flares the glow; the flare decays much faster. */
  FLARE_TIME_CONSTANT_S: 0.16,
  /** Rise speed multiplier is 1 + energy * this (about x7 at the cap). */
  SPEED_GAIN: 6,
  /** The rise speed eases toward its target over this long. */
  SPEED_EASE_S: 0.15,
  /** Brightness, size and drift quickening per unit of energy. */
  ALPHA_GAIN: 0.25,
  SIZE_GAIN: 0.35,
  SWAY_GAIN: 0.8,
} as const;

/** Glow blur radius at rest, and what energy and the flare add to it. */
export const GLOW = { BASE_PX: 6, PER_ENERGY_PX: 10, PER_FLARE_PX: 6 } as const;

/** The largest step the loop takes, so a background tab does not teleport the sparks. */
const MAX_FRAME_S = 0.05;
/** Backing-store pixel ratio ceiling. */
const MAX_DPR = 2;

type Random = () => number;

/** A new spark: scattered through the box on arm, otherwise rising from below the bottom edge. */
export function spawnSpark(width: number, height: number, scattered: boolean, random: Random = Math.random): Spark {
  return {
    x: random() * width,
    y: scattered ? height * (SPAWN.SCATTER_TOP + random() * (1 - SPAWN.SCATTER_TOP)) : height + SPAWN.MARGIN_PX,
    r: SPARK.RADIUS_MIN_PX + random() * SPARK.RADIUS_SPREAD_PX,
    vy: -(SPARK.RISE_MIN_PX_S + random() * SPARK.RISE_SPREAD_PX_S),
    sway: (random() - 0.5) * SPARK.SWAY_RANGE_PX,
    phase: random() * Math.PI * 2,
    life: scattered ? random() * SPAWN.HEAD_START_S : 0,
    span: SPARK.LIFE_MIN_S + random() * SPARK.LIFE_SPREAD_S,
  };
}

/**
 * Age and move one spark by `dt` seconds at rise multiplier `speed`. A spark that
 * floats past the top is recycled to the bottom at a new x; returns false once
 * its life is spent and it should be dropped.
 */
export function stepSpark(
  spark: Spark,
  dt: number,
  speed: number,
  width: number,
  height: number,
  random: Random = Math.random,
): boolean {
  spark.life += dt;
  if (spark.life > spark.span) return false;
  spark.y += spark.vy * dt * speed;
  if (spark.y < -SPAWN.RECYCLE_ABOVE_PX) {
    spark.y = height + SPAWN.MARGIN_PX;
    spark.x = random() * width;
  }
  return true;
}

/** Typing energy after one more keystroke. */
export const bumpTyping = (energy: number) => Math.min(TYPING.CAP, energy + TYPING.PER_KEY);

/** Exponential decay over `dt` seconds toward zero. */
export const decayTyping = (value: number, dt: number, timeConstantS: number = TYPING.TIME_CONSTANT_S) =>
  value * Math.exp(-dt / timeConstantS);

/** Paint one spark. The caller sets the fill colour and the glow once per frame. */
export function drawSpark(
  ctx: CanvasRenderingContext2D,
  spark: Spark,
  nowMs: number,
  energy: number,
  height: number,
) {
  const age = spark.life / spark.span;
  const twinkle =
    SPARK.TWINKLE_FLOOR +
    SPARK.TWINKLE_DEPTH * Math.sin((nowMs / SPARK.TWINKLE_MS) * (1 + energy) + spark.phase);
  const edge = Math.min(
    1,
    Math.max(0, spark.y / SPARK.EDGE_FADE_PX),
    Math.max(0, (height - spark.y) / SPARK.EDGE_FADE_PX),
  );
  const fade = Math.sin(age * Math.PI) * (0.9 + energy * TYPING.ALPHA_GAIN) * twinkle;
  const drift =
    Math.sin((nowMs / SPARK.SWAY_MS) * (1 + energy * TYPING.SWAY_GAIN) + spark.phase) * spark.sway;
  ctx.globalAlpha = Math.min(1, fade) * edge;
  ctx.beginPath();
  ctx.arc(spark.x + drift, spark.y, spark.r * twinkle * (1 + energy * TYPING.SIZE_GAIN), 0, Math.PI * 2);
  ctx.fill();
}

export function SparkField({
  active,
  ref,
  className,
}: {
  active: boolean;
  ref?: React.Ref<SparkFieldHandle>;
  className?: string;
}) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  // Shared with the loop: how worked-up the typist is, and whether a flare is owed.
  const typing = React.useRef({ energy: 0, flarePending: false });

  React.useImperativeHandle(ref, () => ({
    bump: () => {
      typing.current.energy = bumpTyping(typing.current.energy);
      typing.current.flarePending = true;
    },
  }));

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!active || !canvas) return undefined;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;

    const color = getComputedStyle(canvas).color;
    typing.current.flarePending = false;

    const sparks: Spark[] = [];
    let frame = 0;
    let previous = performance.now();
    let width = 0;
    let height = 0;
    let sinceSpawn = 0;
    let speed = 1;
    let flare = 0;

    const fit = () => {
      const box = canvas.getBoundingClientRect();
      const ratio = Math.min(MAX_DPR, window.devicePixelRatio || 1);
      width = box.width;
      height = box.height;
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    };

    const loop = (now: number) => {
      const dt = Math.min(MAX_FRAME_S, (now - previous) / 1000);
      previous = now;

      const state = typing.current;
      state.energy = decayTyping(state.energy, dt);
      flare = decayTyping(flare, dt, TYPING.FLARE_TIME_CONSTANT_S);
      if (state.flarePending) {
        state.flarePending = false;
        flare = 1;
      }
      const energy = state.energy;

      const targetSpeed = 1 + energy * TYPING.SPEED_GAIN;
      speed += (targetSpeed - speed) * (1 - Math.exp(-dt / TYPING.SPEED_EASE_S));

      sinceSpawn += dt;
      while (sinceSpawn > SPAWN.INTERVAL_S) {
        sinceSpawn -= SPAWN.INTERVAL_S;
        if (sparks.length < SPAWN.MAX) sparks.push(spawnSpark(width, height, false));
      }

      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = color;
      ctx.shadowColor = color;
      ctx.shadowBlur = GLOW.BASE_PX + energy * GLOW.PER_ENERGY_PX + flare * GLOW.PER_FLARE_PX;
      for (let i = sparks.length - 1; i >= 0; i -= 1) {
        if (stepSpark(sparks[i], dt, speed, width, height)) drawSpark(ctx, sparks[i], now, energy, height);
        else sparks.splice(i, 1);
      }
      frame = requestAnimationFrame(loop);
    };

    fit();
    for (let i = 0; i < SPAWN.SCATTERED; i += 1) sparks.push(spawnSpark(width, height, true));
    const observer = new ResizeObserver(fit);
    observer.observe(canvas);
    frame = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      ctx.clearRect(0, 0, width, height);
    };
  }, [active]);

  return (
    <>
      <span
        aria-hidden
        data-slot="spark-tint"
        className={cn(
          "bg-agent/15 pointer-events-none absolute inset-0 -z-10 rounded-[inherit] opacity-0 transition-opacity duration-slow",
          active && "opacity-100",
          className,
        )}
      />
      <canvas
        ref={canvasRef}
        aria-hidden
        data-slot="spark-field"
        data-active={active ? "" : undefined}
        className="text-agent pointer-events-none absolute inset-0 -z-10 size-full rounded-[inherit]"
      />
    </>
  );
}

"use client";

/**
 * VoiceOrb — the agent's face while voice is active.
 *
 * Plain DOM and the agent token, nothing fetched and no canvas. Each state is
 * a different shape as well as a different motion, so it reads in both themes
 * and still reads when the system stops the animations for reduced motion:
 *
 *  - listening: a solid agent disc with a card-coloured dot, the whole disc
 *    fading to 75% and back (`anim-pulse`).
 *  - thinking: a faint disc with a solid dot inside a turning arc (`anim-spin`).
 *  - speaking: a faint disc with three solid bars that blink out of step
 *    (`anim-caret`, offset by a third of its cycle each).
 *
 * `anim-pulse` also paints a hard-coded green ring; the root clips to its own
 * circle, so only the fade shows. `--agent` is the lifted end of the action
 * ramp in dark and the deep end in light.
 */

import * as React from "react";

import { cn } from "@/lib/utils";
import type { VoiceState } from "@/components/agent/workspace/workspace-composer";

export type VoiceOrbState = Exclude<VoiceState, "idle">;

/** Bar heights and where each bar starts in the blink cycle (a negative delay = already under way). */
const BARS = [
  { height: "h-2", phase: 0 },
  { height: "h-4", phase: -1 / 3 },
  { height: "h-3", phase: -2 / 3 },
] as const;

export function VoiceOrb({
  state,
  className,
  ...props
}: { state: VoiceOrbState } & React.ComponentProps<"div">) {
  return (
    <div
      data-slot="voice-orb"
      data-state={state}
      role="img"
      aria-label={`Voice: ${state}`}
      className={cn("relative grid size-8 place-items-center overflow-hidden rounded-full", className)}
      {...props}
    >
      <span
        aria-hidden="true"
        data-part="disc"
        className={cn("absolute inset-0 rounded-full", state === "listening" ? "bg-agent anim-pulse" : "bg-agent/15")}
      />
      {state === "listening" ? (
        <span aria-hidden="true" data-part="dot" className="bg-background size-3 rounded-full" />
      ) : null}
      {state === "thinking" ? (
        <>
          <span
            aria-hidden="true"
            data-part="arc"
            className="anim-spin border-agent/25 border-t-agent absolute inset-1 rounded-full border-2"
          />
          <span aria-hidden="true" data-part="dot" className="bg-agent size-3 rounded-full" />
        </>
      ) : null}
      {state === "speaking" ? (
        <span aria-hidden="true" data-part="bars" className="relative flex items-center gap-0.5">
          {BARS.map(({ height, phase }) => (
            <span
              key={height}
              data-part="bar"
              className={cn("anim-caret bg-agent w-1 rounded-full", height)}
              style={{ animationDelay: `calc(var(--duration-caret) * ${phase})` }}
            />
          ))}
        </span>
      ) : null}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";

/**
 * The assistant reading its answer out loud.
 *
 * `SpeechAdapter` is the seam. The workspace only ever speaks through this
 * interface, so replacing the browser's synthesiser with ElevenLabs — or with
 * anything that returns audio — is one module that satisfies the type. Nothing
 * above this file learns which one is in use.
 *
 * The browser implementation below is the default because it costs nothing,
 * needs no key, works offline, and is available on every machine this will be
 * demoed on. Its one real limitation is stated rather than hidden:
 *
 *   `speechSynthesis` gives you no audio stream. There is no AnalyserNode and
 *   therefore no waveform data, so `analyser` is null and anything drawing a
 *   level has to animate procedurally. A network adapter that plays through
 *   WebAudio returns a real analyser here and that drawing becomes a genuine
 *   reading of the audio, with no change to the components.
 */

export type SpeechVoice = {
  id: string;
  label: string;
  lang: string;
  /** Shipped with the OS rather than fetched. Local voices start instantly. */
  local: boolean;
};

export type SpeechAdapter = {
  /** False when this environment cannot speak at all. The workspace hides the control. */
  isSupported: boolean;
  isSpeaking: boolean;
  isPaused: boolean;
  voices: SpeechVoice[];
  voiceId: string | null;
  setVoiceId: (id: string) => void;
  speak: (text: string) => void;
  pause: () => void;
  resume: () => void;
  stop: () => void;
  /**
   * Live audio for anything that draws a level, when the adapter has one. Null means the
   * caller should animate procedurally rather than draw a flat line.
   */
  analyser: AnalyserNode | null;
};

/**
 * Strip markdown before speaking.
 *
 * The model writes markdown, and a synthesiser reads the asterisks out loud.
 * This is deliberately blunt — it removes syntax rather than parsing structure,
 * because the goal is a sentence that sounds right, not a faithful rendering.
 */
export function speakableText(markdown: string): string {
  return markdown
    // Fenced code is never worth reading aloud.
    .replace(/```[\s\S]*?```/g, " — code block — ")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/(\*\*|__)(.*?)\1/g, "$2")
    .replace(/(\*|_)(.*?)\1/g, "$2")
    .replace(/^\s*[-*+]\s+/gm, "")
    .replace(/^\s*>\s?/gm, "")
    .replace(/\|/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * The browser's own synthesiser.
 *
 * Voice loading is asynchronous and, in Chrome, returns an empty list on the
 * first synchronous call — hence the `voiceschanged` subscription rather than a
 * single read at mount.
 */
/* Support never changes after load, so the store never emits. */
const subscribeNever = () => () => {};
const hasSynthesis = () =>
  typeof window !== "undefined" && "speechSynthesis" in window;

/**
 * The one utterance the shared `speechSynthesis` is currently speaking,
 * shared across every `useBrowserSpeech` instance in the tree.
 *
 * The browser only ever plays one utterance at a time — a second reply's
 * "Read aloud" starting is correctly a global takeover, cancelling
 * whichever reply was speaking. But the console mounts a FRESH hook
 * instance per reply (`WorkspaceThread`'s meta row), and that instance's
 * own unmount effect used to call `speechSynthesis.cancel()`
 * unconditionally — so scrolling to (or otherwise unmounting) an OLDER
 * reply while a NEWER one was still reading cut the newer one off, because
 * the older instance's cleanup fired and cancelled the shared synthesiser
 * out from under it. This module-level ref is what lets an instance tell
 * "am I the one still talking" from "someone else already took over"
 * before it cancels — on `stop()` or on unmount — rather than cancelling
 * unconditionally.
 */
let activeUtterance: SpeechSynthesisUtterance | null = null;

export function useBrowserSpeech({
  lang = "en-US",
  enabled = true,
}: { lang?: string; enabled?: boolean } = {}): SpeechAdapter {
  /* A fact about the environment, not state — so it is read, not set. Detecting
     it in an effect would make the first paint claim "unsupported" and then
     correct itself, which flickers the whole speech control. */
  const isSupported = useSyncExternalStore(subscribeNever, hasSynthesis, () => false);
  const [isSpeaking, setSpeaking] = useState(false);
  const [isPaused, setPaused] = useState(false);
  const [voices, setVoices] = useState<SpeechVoice[]>([]);
  const [picked, setVoiceId] = useState<string | null>(null);

  const nativeVoices = useRef<SpeechSynthesisVoice[]>([]);
  /** Whichever utterance THIS instance most recently started — compared
   *  against the module-level `activeUtterance` to decide whether this
   *  instance is still the one actually speaking. */
  const myUtterance = useRef<SpeechSynthesisUtterance | null>(null);

  useEffect(() => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;

    const read = () => {
      const list = window.speechSynthesis.getVoices();
      if (!list.length) return;
      nativeVoices.current = list;
      setVoices(
        list.map((voice) => ({
          id: voice.voiceURI,
          label: voice.name,
          lang: voice.lang,
          local: voice.localService,
        })),
      );
    };

    read();
    window.speechSynthesis.addEventListener("voiceschanged", read);
    return () => window.speechSynthesis.removeEventListener("voiceschanged", read);
  }, []);

  /**
   * Which voice speaks.
   *
   * Derived rather than synced. Local voices first, because a network voice
   * stalls for a beat before the first syllable and that reads as the feature
   * being broken. `picked` holds only what the user chose, so the default keeps
   * following `lang` until they override it — an effect that wrote the default
   * into state would pin the first language the component ever saw.
   */
  const voiceId = useMemo(() => {
    if (picked) return picked;
    if (!voices.length) return null;
    const base = lang.split("-")[0];
    const match =
      voices.find((v) => v.lang === lang && v.local) ??
      voices.find((v) => v.lang.startsWith(base) && v.local) ??
      voices.find((v) => v.lang.startsWith(base)) ??
      voices[0];
    return match?.id ?? null;
  }, [lang, picked, voices]);

  const stop = useCallback(() => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    // Only cancel the SHARED synthesiser when this instance is the one
    // actually speaking. An instance that never started anything (or whose
    // utterance another instance already superseded) has nothing of its own
    // to stop, and cancelling would cut off whoever the active speaker
    // actually is.
    if (activeUtterance && activeUtterance === myUtterance.current) {
      window.speechSynthesis.cancel();
      activeUtterance = null;
    }
    setSpeaking(false);
    setPaused(false);
  }, []);

  const speak = useCallback(
    (text: string) => {
      if (!enabled || typeof window === "undefined" || !("speechSynthesis" in window)) return;
      const body = speakableText(text);
      if (!body) return;

      // Cancel first. Queueing utterances means the assistant reads three
      // answers back to back after the user has moved on. This is the one
      // place a genuine global takeover is correct — whoever else was
      // speaking loses, on purpose — unlike `stop()` and the unmount
      // cleanup below, which must not cancel someone else's read.
      window.speechSynthesis.cancel();

      const utterance = new SpeechSynthesisUtterance(body);
      utterance.lang = lang;
      const voice = nativeVoices.current.find((v) => v.voiceURI === voiceId);
      if (voice) utterance.voice = voice;

      myUtterance.current = utterance;
      activeUtterance = utterance;

      utterance.onstart = () => {
        setSpeaking(true);
        setPaused(false);
      };
      utterance.onend = () => {
        setSpeaking(false);
        setPaused(false);
        if (activeUtterance === utterance) activeUtterance = null;
      };
      utterance.onerror = () => {
        setSpeaking(false);
        setPaused(false);
        if (activeUtterance === utterance) activeUtterance = null;
      };

      window.speechSynthesis.speak(utterance);
    },
    [enabled, lang, voiceId],
  );

  const pause = useCallback(() => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    window.speechSynthesis.pause();
    setPaused(true);
  }, []);

  const resume = useCallback(() => {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    window.speechSynthesis.resume();
    setPaused(false);
  }, []);

  // A page that navigates away mid-sentence leaves the synthesiser talking to
  // an empty room — it is a global, not a component. But an individual
  // instance unmounting (a reply scrolled out of the transcript, say) must
  // NOT cancel the shared synthesiser unless it was actually the one
  // speaking — `myUtterance.current` is read here, not captured, so it
  // reflects whatever this instance most recently started even though the
  // effect itself only ever runs its cleanup once, on unmount.
  useEffect(() => () => {
    if (
      typeof window !== "undefined" &&
      "speechSynthesis" in window &&
      activeUtterance &&
      activeUtterance === myUtterance.current
    ) {
      window.speechSynthesis.cancel();
      activeUtterance = null;
    }
  }, []);

  return useMemo(
    () => ({
      isSupported,
      isSpeaking,
      isPaused,
      voices,
      voiceId,
      setVoiceId,
      speak,
      pause,
      resume,
      stop,
      analyser: null,
    }),
    [isSupported, isSpeaking, isPaused, voices, voiceId, speak, pause, resume, stop],
  );
}

/**
 * The one adapter between our transcript and AI Elements.
 *
 * AI Elements is written against the AI SDK's message parts: one assistant
 * message per reply, one seven-value state per tool part, an approval object
 * on the part it gates. Our transcript is flatter — a run of `AgentTurn`s,
 * tools and approvals as separate kinds, a run model beside it. Everything
 * the workspace draws goes through these functions, so the translation lives
 * in one tested place instead of being re-derived inside each component.
 *
 * Pure: no React, no DOM. Types from `ai` are imported as types only.
 */

import type { LanguageModelUsage, ToolUIPart } from "ai";

import type { QueueMessage } from "@/components/ai-elements/queue";

import type { Checkpoint, QueueItem, RunStatus, StepStatus } from "@/components/agent/core/run";
import type {
  ActionTurn,
  AgentTurn,
  Attachment,
  ContextUsage,
  Source,
  ToolTurn,
  UserTurn,
} from "@/components/agent/core/types";

/* ── Replies ─────────────────────────────────────────────────────────────── */

/** One assistant reply: every turn between two user turns, in order. */
export type Reply = {
  /** First turn's id. */
  id: string;
  /** The user turn it answers. */
  userTurnId: string;
  /** Text / tool / action / error turns, in order. */
  turns: AgentTurn[];
  /** All text turns joined (Copy, Read aloud). */
  text: string;
  /** Merged, de-duplicated by url, in first-seen order. */
  sources: Source[];
  /** A text turn still streams, or the transport is busy on this last reply. */
  streaming: boolean;
  /** First turn's `at`, when it has one. */
  at?: number;
};

export type ReplyPair = { user: UserTurn; reply: Reply | null };

/**
 * Pair every user turn with the reply that answers it.
 *
 * A user turn with nothing after it yet has `reply: null` — the thread draws
 * the waiting state there. Turns before the first user turn have no question
 * to answer and are not paired; every transport here starts a transcript
 * with the user's send, so none exist in practice.
 */
export function groupReplies(turns: AgentTurn[], busy: boolean): ReplyPair[] {
  const pairs: { user: UserTurn; turns: AgentTurn[] }[] = [];
  for (const turn of turns) {
    if (turn.kind === "user") pairs.push({ user: turn, turns: [] });
    else pairs.at(-1)?.turns.push(turn);
  }
  return pairs.map((pair, i) => ({
    user: pair.user,
    reply: pair.turns.length ? toReply(pair.user.id, pair.turns, busy && i === pairs.length - 1) : null,
  }));
}

/**
 * Which user turn a run answers: the last one sent at or before the run
 * started. The run's Plan, Task and Commit render inside that turn's reply.
 * Falls back to the last user turn when none carries a time, and null only
 * when there is no user turn at all.
 */
export function runOwner(pairs: ReplyPair[], runStartedAt: number): string | null {
  let owner: string | null = null;
  for (const { user } of pairs) {
    if (user.at === undefined || user.at <= runStartedAt) owner = user.id;
  }
  return owner ?? pairs.at(-1)?.user.id ?? null;
}

function toReply(userTurnId: string, turns: AgentTurn[], lastAndBusy: boolean): Reply {
  const first = turns[0];
  const texts = turns.filter((t) => t.kind === "text");
  return {
    id: first.id,
    userTurnId,
    turns,
    text: texts.map((t) => t.text.trim()).filter(Boolean).join("\n\n"),
    sources: mergeSources(texts.flatMap((t) => t.sources ?? [])),
    streaming: lastAndBusy || texts.some((t) => t.streaming),
    at: "at" in first ? first.at : undefined,
  };
}

function mergeSources(sources: Source[]): Source[] {
  const seen = new Set<string>();
  return sources.filter((s) => (seen.has(s.url) ? false : (seen.add(s.url), true)));
}

/**
 * Run statuses during which the run is still going — a new message waits in the
 * queue, and the reply that owns the run is not finished (no actions, no
 * follow-ups) even when nothing is streaming, e.g. while it is paused.
 */
export const RUN_IN_FLIGHT: ReadonlySet<RunStatus> = new Set(["queued", "running", "paused", "waiting_for_approval", "cancelling"]);

/* ── Tools and approvals ─────────────────────────────────────────────────── */

export type ToolState = ToolUIPart["state"];

/**
 * The AI Elements `Tool` state for a tool call or a gated action.
 *
 * We carry a call's progress (`status`) and its approval separately; AI
 * Elements carries one value. The approval wins while it is open or refused,
 * then the call's own status takes over. There is no `input-streaming`: our
 * tool turns exist only once their parameters are complete.
 */
export function toolState(turn: ToolTurn | ActionTurn): ToolState {
  if (turn.kind === "action" && turn.approval) {
    if (turn.approval === "pending") return "approval-requested";
    if (turn.approval === "rejected") return "output-denied";
    if (turn.status === "running") return "approval-responded";
  }
  if (turn.status === "running") return "input-available";
  return turn.status === "ok" ? "output-available" : "output-error";
}

/** AI Elements' `ToolUIPartApproval` — the shape `Confirmation` reads. */
export type ToolApproval =
  | { id: string; approved?: never; reason?: never }
  | { id: string; approved: true; reason?: string }
  | { id: string; approved: false; reason?: string }
  | undefined;

/** The `approval` prop for `Confirmation`, or undefined for an ungated action. */
export function toolApproval(turn: ActionTurn): ToolApproval {
  switch (turn.approval) {
    case "pending": return { id: turn.id };
    case "approved": return { id: turn.id, approved: true };
    case "rejected": return { id: turn.id, approved: false, reason: turn.error };
    default: return undefined;
  }
}

/* ── Plan, task, queue ───────────────────────────────────────────────────── */

export type { QueueMessage };

/** `ChainOfThoughtStep` status for a plan step. Failed and skipped steps are finished. */
export function stepChainStatus(status: StepStatus): "complete" | "active" | "pending" {
  if (status === "running") return "active";
  if (status === "pending") return "pending";
  return "complete";
}

/** Messages held behind a busy run, as `Queue` messages: the text, then each file. */
export function queueMessages(queue: QueueItem[]): QueueMessage[] {
  return queue.map((item) => ({
    id: item.id,
    parts: [
      { type: "text", text: item.text },
      ...(item.attachments ?? []).map((a) => ({
        type: "file",
        url: a.url,
        filename: a.name,
        mediaType: a.mime,
      })),
    ],
  }));
}

/* ── Checkpoints ─────────────────────────────────────────────────────────── */

/**
 * Restore points keyed by the turn they follow, so the thread can draw each
 * `Checkpoint` right after its turn. Several on one turn keep their order.
 */
export function checkpointsByTurn(checkpoints: Checkpoint[]): Map<string, Checkpoint[]> {
  const byTurn = new Map<string, Checkpoint[]>();
  for (const cp of checkpoints) byTurn.set(cp.turnId, [...(byTurn.get(cp.turnId) ?? []), cp]);
  return byTurn;
}

/* ── Context ─────────────────────────────────────────────────────────────── */

export type ContextMeterProps = {
  usedTokens: number;
  maxTokens: number;
  usage?: LanguageModelUsage;
  modelId?: string;
};

/** Our token accounting as the props AI Elements' `Context` takes. */
export function contextProps(usage: ContextUsage): ContextMeterProps {
  const hasBreakdown =
    usage.inputTokens !== undefined ||
    usage.outputTokens !== undefined ||
    usage.reasoningTokens !== undefined ||
    usage.cachedInputTokens !== undefined;
  return {
    usedTokens: usage.usedTokens,
    maxTokens: usage.maxTokens,
    modelId: usage.modelId,
    usage: hasBreakdown
      ? {
          inputTokens: usage.inputTokens,
          inputTokenDetails: {
            noCacheTokens: undefined,
            cacheReadTokens: usage.cachedInputTokens,
            cacheWriteTokens: undefined,
          },
          outputTokens: usage.outputTokens,
          outputTokenDetails: { textTokens: undefined, reasoningTokens: usage.reasoningTokens },
          totalTokens: usage.usedTokens,
          reasoningTokens: usage.reasoningTokens,
          cachedInputTokens: usage.cachedInputTokens,
        }
      : undefined,
  };
}

/* ── Images ──────────────────────────────────────────────────────────────── */

export type GeneratedImage = { base64: string; uint8Array: Uint8Array; mediaType: string };

/**
 * An image attachment as the `Image` component's props, when its bytes are
 * inline (a `data:` url). A blob: or remote url has no base64 to hand over —
 * null, and the caller draws it as an attachment instead. So is a data url
 * whose payload does not decode.
 */
export function generatedImage(attachment: Attachment): GeneratedImage | null {
  const match = attachment.url?.match(/^data:([^;,]+);base64,([\s\S]*)$/);
  if (!match) return null;
  const [, mediaType, base64] = match;
  let binary: string;
  try {
    binary = atob(base64);
  } catch {
    // Not valid base64 after all — no bytes to hand over.
    return null;
  }
  const uint8Array = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return { base64, uint8Array, mediaType };
}

"use client";

