const HANDOFF_OWNERS = ["Me", "Support team", "On-call engineer"] as const;
const CANCELLABLE: ReadonlySet<RunStatus> = new Set(["running", "paused", "waiting_for_approval", "queued"]);
const ERROR_STATUSES: ReadonlySet<RunStatus> = new Set(["partially_failed", "handoff_required", "cancelled"]);

/* ── Plan approval notices (conversation 4) ─────────────────────────────── */

/**
 * Why the plan on offer was not simply approved: an approval that expired, or
 * one for an older version that the newer plan replaced. Read from the
 * structured `reason` on the latest approval entry of the run's timeline; a
 * later "Plan edited" entry carries none and clears it.
 */
export function planNotice(timeline: ActivityEntry[] | undefined): { kind: "expired" | "stale"; text: string } | null {
  const last = [...(timeline ?? [])].reverse().find((e) => e.kind === "approval");
  if (last?.reason === "approval_expired") return { kind: "expired", text: last.text };
  if (last?.reason === "approval_stale") return { kind: "stale", text: last.text };
  return null;
}

/* ── Plan ───────────────────────────────────────────────────────────────── */

function ProposedPlan({ transport, run, className }: RunInlineProps) {
  // Local until the plan runs; reset by keying this component on the version.
  const [edits, setEdits] = useState<Record<string, string>>({});
  const [editing, setEditing] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const [workflowOpen, setWorkflowOpen] = useState(false);

  const plan: PlanStep[] = run.plan.map((s) => (edits[s.id] ? { ...s, title: edits[s.id] } : s));
  const edited = plan.some((s, i) => s.title !== run.plan[i].title);
  const streaming = run.plan.length === 0;
  const notice = planNotice(transport.runState?.timeline);
  const canApprove = Boolean(transport.approvePlan);

  const setTitle = (id: string, title: string) => {
    setEdits((prev) => ({ ...prev, [id]: title }));
    toast.success("Step updated. Run the plan to use it.");
  };
  const save = (id: string) => {
    const title = draft.trim();
    if (title && title !== run.plan.find((s) => s.id === id)?.title) setTitle(id, title);
    setEditing(null);
  };

  return (
    <Plan className={className} defaultOpen isStreaming={streaming}>
      <PlanHeader>
        <div className="flex min-w-0 flex-col gap-1">
          <div className="flex items-center gap-2">
            <Icon icon={FileTextIcon} size="md" tone="muted" />
            <PlanTitle>{run.goal}</PlanTitle>
          </div>
          <PlanDescription>
            {streaming
              ? "Drafting the plan…"
              : `${plan.length} ${plan.length === 1 ? "step" : "steps"}${run.version > 1 ? ` · Plan v${run.version}` : ""}`}
          </PlanDescription>
        </div>
        <PlanAction className="flex items-center gap-1">
          <Button
            aria-label="View as workflow"
            disabled={plan.length === 0}
            onClick={() => setWorkflowOpen(true)}
            size="icon"
            variant="ghost"
          >
            <Icon icon={WorkflowIcon} size="sm" tone="inherit" />
          </Button>
          <PlanTrigger />
        </PlanAction>
      </PlanHeader>
      <PlanContent>
        <div className="flex flex-col gap-3">
          {notice && (
            <Confirmation
              approval={{ id: `plan-${run.version}`, approved: false, reason: notice.text }}
              className={RECORD_CONFIRMATION}
              state="output-denied"
            >
              <ConfirmationTitle>
                <ConfirmationRejected>
                  <span className="inline-flex items-center gap-2">
                    <Icon icon={XIcon} size="sm" tone="error" />
                    <span>{notice.text}</span>
                  </span>
                </ConfirmationRejected>
              </ConfirmationTitle>
            </Confirmation>
          )}
          <ol className="flex flex-col gap-2">
            {plan.map((step, i) => (
              <li className="flex items-start gap-3" key={step.id}>
                <span className="mt-1 w-5 shrink-0 text-right type-number-sm text-muted-foreground">{i + 1}</span>
                {editing === step.id ? (
                  <form
                    className="flex min-w-0 flex-1 items-center gap-2"
                    onSubmit={(e) => {
                      e.preventDefault();
                      save(step.id);
                    }}
                  >
                    <Input
                      aria-label={`Title of step ${i + 1}`}
                      autoFocus
                      onChange={(e) => setDraft(e.target.value)}
                      onKeyDown={(e) => e.key === "Escape" && setEditing(null)}
                      value={draft}
                    />
                    <Button size="sm" type="submit">
                      Save
                    </Button>
                    <Button onClick={() => setEditing(null)} size="sm" type="button" variant="ghost">
                      Cancel
                    </Button>
                  </form>
                ) : (
                  <>
                    <div className="min-w-0 flex-1 py-1">
                      <p className="type-small">{step.title}</p>
                      {step.detail && <p className="type-small text-muted-foreground">{step.detail}</p>}
                    </div>
                    <Button
                      aria-label={`Edit step ${i + 1}`}
                      className="-my-1.5 shrink-0"
                      onClick={() => {
                        setDraft(step.title);
                        setEditing(step.id);
                      }}
                      size="icon"
                      variant="ghost"
                    >
                      <Icon icon={PencilIcon} size="sm" tone="inherit" />
                    </Button>
                  </>
                )}
              </li>
            ))}
          </ol>
          {!streaming && canApprove && (
            <Confirmation approval={{ id: `plan-${run.version}` }} state="approval-requested">
              <ConfirmationTitle>
                <ConfirmationRequest>{`Approve plan v${run.version} to start the run.`}</ConfirmationRequest>
              </ConfirmationTitle>
              <ConfirmationActions>
                <ConfirmationAction
                  onClick={() => {
                    transport.approvePlan?.(run.version, edited ? plan : undefined);
                    toast.success(`Running plan v${run.version}`);
                  }}
                >
                  <Icon icon={PlayIcon} size="sm" tone="inherit" />
                  Run plan
                </ConfirmationAction>
              </ConfirmationActions>
            </Confirmation>
          )}
        </div>
      </PlanContent>
      <WorkflowDialog
        onEditStep={setTitle}
        onOpenChange={setWorkflowOpen}
        open={workflowOpen}
        run={{ ...run, plan }}
      />
    </Plan>
  );
}

/* ── Task ───────────────────────────────────────────────────────────────── */

type Answer = "verified" | "skipped";

function StepRow({
  transport,
  run,
  step,
  effects,
  answer,
  onAnswer,
  askFirst,
}: {
  transport: AgentTransport;
  run: Run;
  step: PlanStep;
  effects: Effect[];
  answer?: Answer;
  onAnswer: (id: string, answer: Answer) => void;
  /** True only for the first unsettled low-confidence step: one question at a time. */
  askFirst: boolean;
}) {
  const unsettled = step.status === "running" || step.status === "pending";
  const asks = askFirst && step.confidence === "low" && unsettled && (step.status === "running" || run.status === "waiting_for_approval");
  const canVerify = Boolean(transport.verifyStep);
  const canSkip = Boolean(transport.skipStep);
  const failedEffects = effects.filter((e) => e.status === "failed");

  return (
    <TaskItem className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <StepStatusMark status={step.status} />
        {step.status === "running" ? (
          <Shimmer as="span" className="type-small">{step.title}</Shimmer>
        ) : (
          <span className={cn("type-small", step.status === "pending" || step.status === "skipped" ? "text-muted-foreground" : "text-foreground")}>
            {step.title}
          </span>
        )}
        {step.ms !== undefined && <span className="ml-auto type-small text-muted-foreground">{formatDuration(step.ms)}</span>}
        {step.status === "failed" && transport.retryStep && (
          <Button
            className={step.ms === undefined ? "ml-auto" : undefined}
            onClick={() => {
              transport.retryStep?.(step.id);
              toast.success(`Retrying "${step.title}"`);
            }}
            size="sm"
            variant="outline"
          >
            <Icon icon={RotateCcwIcon} size="sm" tone="inherit" />
            Retry
          </Button>
        )}
      </div>
      {(asks || answer) && (canVerify || canSkip || answer) && (
        <Confirmation
          approval={
            answer
              ? { id: step.id, approved: answer === "verified" }
              : { id: step.id }
          }
          className={answer ? RECORD_CONFIRMATION : undefined}
          state={answer ? "approval-responded" : "approval-requested"}
        >
          <ConfirmationTitle>
            <ConfirmationRequest>This step is low confidence. Verify it before it goes ahead, or skip it.</ConfirmationRequest>
            <ConfirmationAccepted>
              <span className="inline-flex items-center gap-2">
                <Icon icon={CheckIcon} size="sm" tone="success" />
                <span>Verified</span>
              </span>
            </ConfirmationAccepted>
            <ConfirmationRejected>
              <span className="inline-flex items-center gap-2">
                <Icon icon={MinusIcon} size="sm" tone="muted" />
                <span>Skipped</span>
              </span>
            </ConfirmationRejected>
          </ConfirmationTitle>
          <ConfirmationActions>
            {canSkip && (
              <ConfirmationAction
                onClick={() => {
                  transport.skipStep?.(step.id);
                  onAnswer(step.id, "skipped");
                  toast.success(`Skipped "${step.title}"`);
                }}
                variant="outline"
              >
                Skip
              </ConfirmationAction>
            )}
            {canVerify && (
              <ConfirmationAction
                onClick={() => {
                  transport.verifyStep?.(step.id);
                  onAnswer(step.id, "verified");
                  toast.success(`Verified "${step.title}"`);
                }}
              >
                Verify
              </ConfirmationAction>
            )}
          </ConfirmationActions>
        </Confirmation>
      )}
      {failedEffects.map((effect) => (
        <div className="flex items-center gap-2 pl-6" key={effect.id}>
          <span className="min-w-0 flex-1 type-small text-destructive-ink">
            {effect.description}
            {effect.error ? `: ${effect.error}` : ""}
          </span>
          {transport.retryEffect && (
            <Button
              aria-label={`Retry: ${effect.description}`}
              onClick={() => {
                transport.retryEffect?.(effect.id);
                toast.success(`Retrying "${effect.description}"`);
              }}
              size="sm"
              variant="outline"
            >
              <Icon icon={RotateCcwIcon} size="sm" tone="inherit" />
              Retry
            </Button>
          )}
        </div>
      ))}
    </TaskItem>
  );
}

function RunTask({ transport, run, className }: RunInlineProps) {
  const [answers, setAnswers] = useState<Record<string, Answer>>({});
  const caps = transport.capabilities;
  const done = run.plan.filter((s) => s.status === "done").length;
  const canPause = Boolean(caps.pause && transport.pause) && run.status === "running";
  const canResume = Boolean(caps.pause && transport.resume) && run.status === "paused";
  const canCancel = Boolean(transport.cancel) && CANCELLABLE.has(run.status);
  const { reverse, irreversible } = compensationOrder(run);
  const askingId = run.plan.find((s) => s.confidence === "low" && (s.status === "running" || s.status === "pending"))?.id;
  const canUndo = run.status === "completed" && reverse.length > 0 && Boolean(caps.compensation && transport.compensate);

  return (
    <Task className={cn("flex flex-col gap-3", className)} defaultOpen>
      <div className="flex flex-wrap items-center justify-between gap-2">
        {/* Task's default glyph is a magnifier (research steps); a run's steps are a checklist. */}
        <TaskTrigger className="min-w-0 flex-1" title={`${run.goal} · ${done} of ${run.plan.length}`}>
          <button
            type="button"
            className="relative after:absolute after:inset-x-0 after:-inset-y-3 flex w-full cursor-pointer items-center gap-2 text-left type-small text-muted-foreground transition-colors hover:text-foreground"
          >
            <Icon icon={ListChecksIcon} size="sm" tone="inherit" />
            <span className="min-w-0 truncate">{`${run.goal} · ${done} of ${run.plan.length}`}</span>
            <Icon className="transition-transform group-data-[state=open]:rotate-180" icon={ChevronDownIcon} size="sm" tone="inherit" />
          </button>
        </TaskTrigger>
        <div className="flex items-center gap-2">
          {canPause && (
            <Button
              onClick={() => {
                transport.pause?.();
                toast.success("Pausing after this step");
              }}
              size="sm"
              variant="outline"
            >
              <Icon icon={PauseIcon} size="sm" tone="inherit" />
              Pause
            </Button>
          )}
          {canResume && (
            <Button
              onClick={() => {
                void transport.resume?.();
                toast.success("Resuming");
              }}
              size="sm"
            >
              <Icon icon={PlayIcon} size="sm" tone="inherit" />
              Resume
            </Button>
          )}
          {canCancel && (
            <Button
              onClick={() => {
                transport.cancel?.();
                toast.success("Cancelling the run");
              }}
              size="sm"
              variant="ghost"
            >
              <Icon icon={XIcon} size="sm" tone="inherit" />
              Cancel
            </Button>
          )}
        </div>
      </div>
      <p aria-live="polite" className="type-small text-muted-foreground" role="status">
        {RUN_STATUS_LABEL[run.status]}
      </p>
      <TaskContent>
        {run.plan.map((step) => (
          <StepRow
            answer={answers[step.id]}
            askFirst={step.id === askingId}
            effects={run.effects.filter((e) => e.stepId === step.id)}
            key={step.id}
            onAnswer={(id, a) => setAnswers((prev) => ({ ...prev, [id]: a }))}
            run={run}
            step={step}
            transport={transport}
          />
        ))}
      </TaskContent>
      {(canUndo || (run.status === "completed" && irreversible.length > 0)) && (
        <div className="flex flex-col gap-2">
          {canUndo && (
            <div className="flex items-center gap-3">
              <Button
                onClick={() => {
                  transport.compensate?.();
                  toast.success("Undoing changes");
                }}
                variant="outline"
              >
                <Icon icon={Undo2Icon} size="sm" tone="inherit" />
                Undo changes
              </Button>
              <span className="type-small text-muted-foreground">
                {`${reverse.length} ${reverse.length === 1 ? "change" : "changes"} can be undone`}
              </span>
            </div>
          )}
          {irreversible.length > 0 && (
            <p className="type-small text-muted-foreground">
              {`Can't be undone: ${irreversible.map((e) => e.description).join(", ")}`}
            </p>
          )}
        </div>
      )}
    </Task>
  );
}

/* ── Handoff and error ──────────────────────────────────────────────────── */

function HandoffForm({ transport, run }: { transport: AgentTransport; run: Run }) {
  const [sent, setSent] = useState(false);
  const handed = run.handoff?.owner || run.handoff?.note || sent;
  const canHandoff = Boolean(transport.capabilities.handoff && transport.handoff);

  const showForm = !handed && canHandoff;
  if (!showForm && !run.handoff) return null;

  return (
    <div className="flex flex-col gap-3">
      {showForm && (
        <Question
          onSubmit={({ selectedValues, text }) => {
            transport.handoff?.(text?.trim() || undefined, selectedValues[0]);
            setSent(true);
            toast.success(selectedValues[0] ? `Handed off to ${selectedValues[0]}` : "Handed off");
          }}
          selectionMode="single"
        >
          <div className="space-y-1">
            <QuestionPrompt>Who should take this over?</QuestionPrompt>
            <QuestionDescription>Choose an owner and leave a note for them.</QuestionDescription>
          </div>
          <QuestionOptions aria-label="Owner">
            {HANDOFF_OWNERS.map((owner) => (
              <QuestionOption key={owner} value={owner}>
                {owner}
              </QuestionOption>
            ))}
          </QuestionOptions>
          <QuestionInput aria-label="Note for the owner" placeholder="What should they know?" />
          <QuestionActions>
            <QuestionSubmit>Hand off</QuestionSubmit>
          </QuestionActions>
        </Question>
      )}
      {run.handoff && <HandoffSummary handoff={run.handoff} />}
    </div>
  );
}

function HandoffSummary({ handoff }: { handoff: NonNullable<Run["handoff"]> }) {
  const lists: [string, string[]][] = [
    ["Done", handoff.done],
    ["Failed", handoff.failed],
    ["Unknown", handoff.unknown],
  ];
  return (
    <section aria-label="Handoff summary" className="flex flex-col gap-2 rounded-lg border p-4">
      <p className="type-small text-foreground">{handoff.goal}</p>
      {lists
        .filter(([, items]) => items.length > 0)
        .map(([label, items]) => (
          <p className="type-small text-muted-foreground" key={label}>
            <span className="text-foreground">{label}:</span> {items.join(", ")}
          </p>
        ))}
      {handoff.owner && (
        <p className="type-small text-muted-foreground">
          <span className="text-foreground">Owner:</span> {handoff.owner}
        </p>
      )}
      {handoff.note && (
        <p className="type-small text-muted-foreground">
          <span className="text-foreground">Note:</span> {handoff.note}
        </p>
      )}
    </section>
  );
}

function RunErrorNotice({ error }: { error: NonNullable<Run["error"]> }) {
  return (
    <Alert variant="destructive">
      <AlertTitle>{error.what}</AlertTitle>
      <AlertDescription>
        <p>{error.why}</p>
        <p>{error.next}</p>
      </AlertDescription>
    </Alert>
  );
}

/**
 * Everything the run shows inside its owning reply, in order: the proposed
 * Plan while `proposed`; the Task once approved; the handoff when a person
 * has to take over; the error in plain words.
 */
export function RunInline({ transport, run, className }: RunInlineProps) {
  const proposed = run.status === "proposed";
  const needsHandoff = run.status === "handoff_required" || Boolean(run.error?.fatal && run.handoff === undefined && transport.handoff);

  return (
    <div className={cn("flex flex-col gap-3", className)} data-run-status={run.status}>
      {proposed ? (
        <ProposedPlan key={run.version} run={run} transport={transport} />
      ) : (
        <>
          <Confirmation
            approval={{ id: `plan-${run.version}`, approved: true }}
            className={RECORD_CONFIRMATION}
            state="approval-responded"
          >
            <ConfirmationTitle>
              <ConfirmationAccepted>
                <span className="inline-flex items-center gap-2">
                  <Icon icon={CheckIcon} size="sm" tone="success" />
                  <span>{`Plan v${run.version} approved`}</span>
                </span>
              </ConfirmationAccepted>
            </ConfirmationTitle>
          </Confirmation>
          <RunTask run={run} transport={transport} />
        </>
      )}
      {/* The reducer keeps the last error after a recovery; show it only while it still describes the run. */}
      {run.error && ERROR_STATUSES.has(run.status) && <RunErrorNotice error={run.error} />}
      {(needsHandoff || run.handoff) && <HandoffForm run={run} transport={transport} />}
    </div>
  );
}

/* ── Queue ──────────────────────────────────────────────────────────────── */

/**
 * Messages held while the agent works — the Queue attached above the composer
 * (reorder, remove, send now). Renders nothing when the queue is empty. The
 * plan is not repeated here: it already lives in the reply that owns the run.
 */
export function RunQueue({ transport, run, className }: RunInlineProps) {
  const queued = transport.capabilities.queue ? queueMessages(run.queue) : [];
  if (queued.length === 0) return null;

  const ids = queued.map((m) => m.id);
  const move = (index: number, by: -1 | 1) => {
    const next = [...ids];
    [next[index], next[index + by]] = [next[index + by], next[index]];
    transport.reorderQueue?.(next);
  };
  const revealOnTouch = "focus-visible:opacity-100 pointer-coarse:opacity-100";

  return (
    <Queue className={cn("max-h-40 w-full overflow-y-auto border-input", className)}>
      {queued.length > 0 && (
        <QueueSection>
          <QueueSectionTrigger>
            <QueueSectionLabel count={queued.length} label="Queued" />
          </QueueSectionTrigger>
          <QueueSectionContent>
            <ul>
              {queued.map((message, i) => {
                const text = message.parts.find((p) => p.type === "text")?.text ?? "";
                const files = message.parts.filter((p) => p.type === "file");
                return (
                  <QueueItem key={message.id}>
                    <div className="flex items-center gap-2">
                      <QueueItemIndicator />
                      <QueueItemContent>{text}</QueueItemContent>
                      <QueueItemActions>
                        {transport.reorderQueue && (
                          <>
                            <QueueItemAction
                              aria-label="Move up"
                              className={revealOnTouch}
                              disabled={i === 0}
                              onClick={() => move(i, -1)}
                            >
                              <Icon icon={ArrowUpIcon} size="xs" tone="inherit" />
                            </QueueItemAction>
                            <QueueItemAction
                              aria-label="Move down"
                              className={revealOnTouch}
                              disabled={i === queued.length - 1}
                              onClick={() => move(i, 1)}
                            >
                              <Icon icon={ArrowDownIcon} size="xs" tone="inherit" />
                            </QueueItemAction>
                          </>
                        )}
                        {transport.sendQueuedNow && (
                          <QueueItemAction
                            aria-label="Send now"
                            className={revealOnTouch}
                            onClick={() => {
                              transport.sendQueuedNow?.(message.id);
                              toast.success("Sent now");
                            }}
                          >
                            <Icon icon={SendHorizontalIcon} size="xs" tone="inherit" />
                          </QueueItemAction>
                        )}
                        {transport.dequeue && (
                          <QueueItemAction
                            aria-label="Remove from queue"
                            className={revealOnTouch}
                            onClick={() => {
                              transport.dequeue?.(message.id);
                              toast.success("Removed from the queue");
                            }}
                          >
                            <Icon icon={Trash2Icon} size="xs" tone="inherit" />
                          </QueueItemAction>
                        )}
                      </QueueItemActions>
                    </div>
                    {files.length > 0 && (
                      <QueueItemAttachment>
                        {files.map((f, n) =>
                          f.mediaType?.startsWith("image/") && f.url ? (
                            <QueueItemImage alt={f.filename ?? "Attached image"} key={n} src={f.url} />
                          ) : (
                            <QueueItemFile key={n}>{f.filename ?? "Attachment"}</QueueItemFile>
                          ),
                        )}
                      </QueueItemAttachment>
                    )}
                  </QueueItem>
                );
              })}
            </ul>
          </QueueSectionContent>
        </QueueSection>
      )}
    </Queue>
  );
}

import { CheckIcon, CircleIcon, MinusIcon, XIcon } from "lucide-react";

import type { StepStatus } from "@/components/agent/core/run";
import { Icon } from "@/components/ui/icon";

/** One status vocabulary for a plan step, shared by the Task and the workflow graph. */
export const STEP_STATUS_LABEL: Record<StepStatus, string> = {
  pending: "Waiting",
  running: "Running",
  done: "Done",
  failed: "Failed",
  skipped: "Skipped",
};

export function formatDuration(ms: number): string {
  return ms < 1000 ? `${ms} ms` : `${(ms / 1000).toFixed(1)} s`;
}

/**
 * The mark for a step's status. Announced by default; pass `decorative` when
 * the status is already written beside it.
 */
export function StepStatusMark({ status, decorative = false }: { status: StepStatus; decorative?: boolean }) {
  const label = decorative ? undefined : STEP_STATUS_LABEL[status];
  switch (status) {
    case "done":
      return <Icon icon={CheckIcon} label={label} size="sm" tone="success" />;
    case "failed":
      return <Icon icon={XIcon} label={label} size="sm" tone="error" />;
    case "skipped":
      return <Icon icon={MinusIcon} label={label} size="sm" tone="muted" />;
    case "running":
      return decorative ? (
        <span aria-hidden className="size-2 rounded-pill bg-action-ink anim-pulse" />
      ) : (
        <span aria-label={label} className="size-2 rounded-pill bg-action-ink anim-pulse" role="img" />
      );
    default:
      return <Icon icon={CircleIcon} label={label} size="xs" tone="muted" />;
  }
}

/**
 * A Confirmation that records an answer already given — approved, rejected,
 * expired — rather than asking for one. Our Alert blooms, and glow is
 * rationed to what calls for action, so a record hides the bloom's two layers
 * and its starfield.
 */
export const RECORD_CONFIRMATION = "before:hidden after:hidden [&>[data-slot=alert-stars]]:hidden";

/**
 * What a tool's result means, so the thread can draw the AI Elements
 * component made for it.
 *
 * `ToolTurn.result` is `unknown` on purpose — the transcript does not know
 * what a tool returns. A result that carries one of these `kind`s is
 * promising a shape, and `toolOutput` checks the promise before the thread
 * trusts it: a malformed result falls back to the plain `Tool` output, never
 * to a crash. The same shapes are what a running tool reports through
 * `tool_progress` (`ToolTurn.partial`), so a terminal or a test run fills in
 * while it works.
 *
 * Pure: no React, no DOM.
 */

import type { ToolTurn } from "@/components/agent/core/types";

export type TestStatus = "passed" | "failed" | "skipped" | "running";

export type ToolOutput =
  /** Terminal: a command's output, ANSI and all. */
  | { kind: "terminal"; command: string; output: string; exitCode?: number }
  /** TestResults. `duration` in ms. */
  | {
      kind: "test-results";
      summary: { passed: number; failed: number; skipped: number; total: number; duration?: number };
      suites: {
        name: string;
        status: TestStatus;
        tests: { name: string; status: TestStatus; duration?: number; error?: { message: string; stack?: string } }[];
      }[];
    }
  /** StackTrace: the raw trace text; the component parses it. */
  | { kind: "stack-trace"; trace: string }
  /** FileTree: the files a step touched. Paths use "/". */
  | { kind: "file-tree"; files: { path: string; change: "added" | "modified" | "deleted" }[] }
  /** Commit. `date` is epoch ms. */
  | {
      kind: "commit";
      hash: string;
      message: string;
      author: string;
      date: number;
      files: { path: string; status: "added" | "modified" | "deleted" | "renamed"; additions: number; deletions: number }[];
    }
  /** PackageInfo. */
  | {
      kind: "package-info";
      name: string;
      currentVersion?: string;
      newVersion?: string;
      changeType?: "major" | "minor" | "patch" | "added" | "removed";
      description?: string;
      dependencies?: { name: string; version: string }[];
    }
  /** EnvironmentVariables. `value` is what masking hides. */
  | { kind: "environment-variables"; variables: { name: string; value: string; required?: boolean }[] }
  /** SchemaDisplay. */
  | {
      kind: "schema-display";
      method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
      path: string;
      description?: string;
      parameters?: { name: string; type: string; required?: boolean; description?: string; location?: "path" | "query" | "header" }[];
      requestBody?: SchemaProperty[];
      responseBody?: SchemaProperty[];
    }
  /** Sandbox: code the agent ran and what it printed. */
  | { kind: "sandbox"; title?: string; language: string; code: string; output: string }
  /** Artifact: a generated document or file. */
  | { kind: "artifact"; title: string; description?: string; language?: string; content: string }
  /** WebPreview: a generated page. */
  | { kind: "web-preview"; url: string; logs?: { level: "log" | "warn" | "error"; message: string; at: number }[] }
  /** JSXPreview: a generated component, rendered live. */
  | { kind: "jsx-preview"; jsx: string }
  /** ChainOfThought search step: the query and the results found. */
  | { kind: "search"; query: string; results: { title: string; url: string; domain: string }[] }
  /** What a running image tool reports through `tool_progress`; the finished picture is an attachment. */
  | { kind: "image"; stage: ImageStage };

export type ImageStage = "queued" | "generating" | "refining" | "complete" | "error";
const IMAGE_STAGES: readonly string[] = ["queued", "generating", "refining", "complete", "error"];

export type SchemaProperty = {
  name: string;
  type: string;
  required?: boolean;
  description?: string;
  properties?: SchemaProperty[];
  items?: SchemaProperty;
};

export type ToolOutputKind = ToolOutput["kind"];

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null;
const isStr = (v: unknown): v is string => typeof v === "string";
const isNum = (v: unknown): v is number => typeof v === "number";
const isArr = Array.isArray;
/** An absolute http(s) url — the only kind a generated page may be previewed or opened from. */
export const isWebUrl = (url: string): boolean => /^https?:\/\//i.test(url.trim());

/** The minimum each kind must carry to be drawn by its component. */
const VALID: Record<ToolOutputKind, (v: Record<string, unknown>) => boolean> = {
  terminal: (v) => isStr(v.command) && isStr(v.output),
  "test-results": (v) =>
    isObj(v.summary) && ["passed", "failed", "skipped", "total"].every((k) => isNum((v.summary as Record<string, unknown>)[k])) && isArr(v.suites),
  "stack-trace": (v) => isStr(v.trace),
  "file-tree": (v) => isArr(v.files) && v.files.every((f) => isObj(f) && isStr(f.path)),
  commit: (v) => isStr(v.hash) && isStr(v.message) && isStr(v.author) && isNum(v.date) && isArr(v.files),
  "package-info": (v) => isStr(v.name),
  "environment-variables": (v) => isArr(v.variables) && v.variables.every((x) => isObj(x) && isStr(x.name) && isStr(x.value)),
  "schema-display": (v) => isStr(v.method) && isStr(v.path),
  sandbox: (v) => isStr(v.language) && isStr(v.code) && isStr(v.output),
  artifact: (v) => isStr(v.title) && isStr(v.content),
  // Only http(s): the url lands in an iframe and window.open, and a javascript: or
  // data: url from a tool result would run script in the host page.
  "web-preview": (v) => isStr(v.url) && isWebUrl(v.url),
  "jsx-preview": (v) => isStr(v.jsx),
  search: (v) => isStr(v.query) && isArr(v.results),
  image: (v) => isStr(v.stage) && IMAGE_STAGES.includes(v.stage),
};

/** `value` as a `ToolOutput`, or null when it does not keep the promise its `kind` makes. */
export function asToolOutput(value: unknown): ToolOutput | null {
  if (!isObj(value) || !isStr(value.kind) || !(value.kind in VALID)) return null;
  return VALID[value.kind as ToolOutputKind](value) ? (value as ToolOutput) : null;
}

/**
 * What to draw for a tool call: its settled result, or — while it runs — what
 * it has reported so far. Null means "no special component; plain Tool output".
 */
export function toolOutput(turn: ToolTurn): ToolOutput | null {
  return asToolOutput(turn.status === "running" ? turn.partial : turn.result);
}

/**
 * A flat path list as the nested tree `FileTree` draws: folders first, then
 * files, each alphabetical. `path` on a folder is its full path, which is
 * what `FileTree`'s `expanded` set holds.
 */
export type FileNode =
  | { type: "folder"; name: string; path: string; children: FileNode[] }
  | { type: "file"; name: string; path: string; change: "added" | "modified" | "deleted" };

export function fileTree(files: { path: string; change: "added" | "modified" | "deleted" }[]): FileNode[] {
  const root: FileNode[] = [];
  for (const file of files) {
    const parts = file.path.split("/").filter(Boolean);
    let level = root;
    parts.forEach((name, i) => {
      const path = parts.slice(0, i + 1).join("/");
      if (i === parts.length - 1) {
        level.push({ type: "file", name, path, change: file.change });
        return;
      }
      let folder = level.find((n): n is Extract<FileNode, { type: "folder" }> => n.type === "folder" && n.name === name);
      if (!folder) {
        folder = { type: "folder", name, path, children: [] };
        level.push(folder);
      }
      level = folder.children;
    });
  }
  const sort = (nodes: FileNode[]): FileNode[] =>
    nodes
      .map((n) => (n.type === "folder" ? { ...n, children: sort(n.children) } : n))
      .sort((a, b) => (a.type === b.type ? a.name.localeCompare(b.name) : a.type === "folder" ? -1 : 1));
  return sort(root);
}

"use client";

/**
 * "View as workflow" — the run's plan drawn as a graph.
 *
 * Built from the AI Elements workflow parts the way their `workflow.tsx` /
 * `demo-workflow.tsx` examples use them: a `Canvas`, one `Node` per step
 * (`NodeHeader` title, `NodeContent` detail, `NodeFooter` status), an `Edge`
 * between consecutive steps, the `Connection` line, `Controls`, a `Panel`
 * naming the goal and version, and a `Toolbar` on each node.
 *
 * Read-only. A plan is a line of steps, not a graph the person wires up, so
 * `nodesConnectable` is off, nothing can be dragged or deleted, and the xyflow
 * handles are decoration. The one edit is the step's title, through the
 * toolbar, handed back to the caller (`onEditStep`) so it is the same local
 * edit the Plan card makes.
 */

import { useRef, useState } from "react";
import type { Edge as FlowEdge, Node as FlowNode, NodeProps as FlowNodeProps } from "@xyflow/react";
import { PencilIcon } from "lucide-react";

import { remVarToPx, useContainerInlineSize } from "@/components/agent/core/use-container-width";
import type { PlanStep, Run } from "@/components/agent/core/run";
import { formatDuration, STEP_STATUS_LABEL, StepStatusMark } from "@/components/agent/workspace/step-status";
import { Canvas } from "@/components/ai-elements/canvas";
import { Connection } from "@/components/ai-elements/connection";
import { Controls } from "@/components/ai-elements/controls";
import { Edge } from "@/components/ai-elements/edge";
import { Node, NodeContent, NodeDescription, NodeFooter, NodeHeader, NodeTitle } from "@/components/ai-elements/node";
import { Panel } from "@/components/ai-elements/panel";
import { Toolbar } from "@/components/ai-elements/toolbar";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Icon } from "@/components/ui/icon";
import { Input } from "@/components/ui/input";

export type WorkflowDialogProps = {
  run: Run;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Present when the plan may still be edited; the node toolbar offers "Edit step". */
  onEditStep?: (stepId: string, title: string) => void;
};

/**
 * Distance between node origins, in React Flow's own coordinate space (plain
 * px at zoom 1 - not a CSS length, so no token applies). It is coupled to the
 * node's width: a step node is `w-60` (15rem = 240px), so COLUMN_STEP = 240 plus
 * a 60px run for the edge, and ROW_STEP clears a node's ~112px height plus
 * its toolbar. Kept small so fit-to-view keeps a four-step plan near zoom 1 —
 * at 384px nodes the graph zoomed out until the text was unreadable. Change
 * the node size and these move with it.
 */
const COLUMN_STEP = 300;
const ROW_STEP = 180;

type StepNodeData = {
  step: PlanStep;
  index: number;
  total: number;
  editable: boolean;
  onEditStep?: (stepId: string, title: string) => void;
  [key: string]: unknown;
};

type StepFlowNode = FlowNode<StepNodeData, "step">;

/**
 * The plan as a graph: one node per step in a line, an edge between each
 * consecutive pair. The edge into the running step travels; the edge into a
 * skipped step is the dashed alternate path.
 */
export function buildWorkflowGraph(
  run: Run,
  options: { vertical?: boolean; editable?: boolean; onEditStep?: WorkflowDialogProps["onEditStep"] } = {},
): { nodes: StepFlowNode[]; edges: FlowEdge[] } {
  const { vertical = false, editable = false, onEditStep } = options;
  const nodes: StepFlowNode[] = run.plan.map((step, index) => ({
    id: step.id,
    type: "step",
    position: vertical ? { x: 0, y: index * ROW_STEP } : { x: index * COLUMN_STEP, y: 0 },
    data: { step, index, total: run.plan.length, editable, onEditStep },
    draggable: false,
    connectable: false,
    deletable: false,
  }));
  const edges: FlowEdge[] = run.plan.slice(1).map((step, i) => ({
    id: `${run.plan[i].id}->${step.id}`,
    source: run.plan[i].id,
    target: step.id,
    type: step.status === "running" ? "animated" : step.status === "skipped" ? "temporary" : "default",
    deletable: false,
    reconnectable: false,
  }));
  return { nodes, edges };
}

function StepNode({ data }: FlowNodeProps<StepFlowNode>) {
  const { step, index, total, editable, onEditStep } = data;
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(step.title);

  const save = () => {
    const title = draft.trim();
    if (title && title !== step.title) onEditStep?.(step.id, title);
    setEditing(false);
  };

  return (
    <Node className="w-60" handles={{ target: index > 0, source: index < total - 1 }}>
      <NodeHeader>
        <NodeTitle>{step.title}</NodeTitle>
        <NodeDescription>{`Step ${index + 1} of ${total}`}</NodeDescription>
      </NodeHeader>
      <NodeContent>
        {editing ? (
          <form
            className="nodrag nopan flex items-center gap-2"
            onSubmit={(e) => {
              e.preventDefault();
              save();
            }}
          >
            <Input aria-label={`Title of step ${index + 1}`} autoFocus onChange={(e) => setDraft(e.target.value)} value={draft} />
            <Button size="sm" type="submit">
              Save
            </Button>
            <Button
              onClick={() => {
                setDraft(step.title);
                setEditing(false);
              }}
              size="sm"
              type="button"
              variant="ghost"
            >
              Cancel
            </Button>
          </form>
        ) : (
          <p className="type-small text-muted-foreground">{step.detail ?? "No further detail."}</p>
        )}
      </NodeContent>
      <NodeFooter className="justify-between gap-2">
        <span className="inline-flex items-center gap-2 type-small">
          <StepStatusMark decorative status={step.status} />
          {STEP_STATUS_LABEL[step.status]}
        </span>
        {step.ms !== undefined && <span className="type-small text-muted-foreground">{formatDuration(step.ms)}</span>}
      </NodeFooter>
      {/* Shown for the selected node only — React Flow's default — not under every node at once. */}
      {editable && (
        <Toolbar>
          <Button
            onClick={() => {
              setDraft(step.title);
              setEditing(true);
            }}
            size="sm"
            variant="ghost"
          >
            <Icon icon={PencilIcon} size="sm" tone="inherit" />
            Edit step
          </Button>
        </Toolbar>
      )}
    </Node>
  );
}

const nodeTypes = { step: StepNode };
const edgeTypes = { animated: Edge.Animated, temporary: Edge.Temporary };

function WorkflowGraph({ run, onEditStep }: Pick<WorkflowDialogProps, "run" | "onEditStep">) {
  const ref = useRef<HTMLDivElement>(null);
  const width = useContainerInlineSize(ref);
  // 0 until measured: draw the wide layout rather than flash a column.
  const vertical = width > 0 && width < remVarToPx("--container-3xl", 48);
  const editable = Boolean(onEditStep) && run.status === "proposed";
  const { nodes, edges } = buildWorkflowGraph(run, { vertical, editable, onEditStep });

  return (
    <div className="h-full min-h-0 w-full" data-testid="workflow-canvas" ref={ref}>
      <Canvas
        connectionLineComponent={Connection}
        deleteKeyCode={null}
        edges={edges}
        edgeTypes={edgeTypes}
        edgesReconnectable={false}
        // Re-fit when the layout flips between a row and a column.
        key={vertical ? "column" : "row"}
        nodes={nodes}
        nodesConnectable={false}
        nodesDraggable={false}
        nodeTypes={nodeTypes}
      >
        <Controls showInteractive={false} />
        <Panel position="top-left">
          <p className="px-2 py-1 type-small">
            <span className="text-foreground">{run.goal}</span>
            <span className="text-muted-foreground">{` · Plan v${run.version}`}</span>
          </p>
        </Panel>
      </Canvas>
    </div>
  );
}

export function WorkflowDialog({ run, open, onOpenChange, onEditStep }: WorkflowDialogProps) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      {/* h-3/4: the dialog is fixed to the viewport, so 3/4 is three quarters of it. */}
      <DialogContent className="flex h-3/4 flex-col sm:max-w-5xl">
        <DialogHeader>
          <DialogTitle>Workflow</DialogTitle>
          <DialogDescription>
            {`${run.plan.length} ${run.plan.length === 1 ? "step" : "steps"}, in the order they run.`}
          </DialogDescription>
        </DialogHeader>
        <div className="min-h-0 flex-1 overflow-hidden rounded-md border">
          <WorkflowGraph onEditStep={onEditStep} run={run} />
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * WorkspaceComposer — the AgentWorkspace's input, built from AI Elements'
 * `PromptInput` the way `chatbot.tsx` / `queue-prompt-input.tsx` build it:
 *
 *   dock (the Queue, glued to the top edge)
 *   PromptInput
 *     PromptInputHeader   attachments (inline chips, hover preview) + the live transcript
 *     PromptInputBody     PromptInputTextarea
 *     PromptInputFooter
 *       PromptInputTools  + menu (files · sources · skills) · Search · ModelSelector · Effort
 *       trailing          Summarise (≥ 90 % full) · Context · SpeechInput + MicSelector · PromptInputSubmit
 *   palette (a Popover anchored on the composer: `@` sources or `/` commands)
 *
 *   Narrow (a phone, or a composer under COMPACT_BELOW wide) keeps only what a
 *   message needs inside the box — +, the mic, Send — and moves Search, the
 *   model, Effort, Summarise and the context meter to a row under it.
 *
 * What the component owns and what it does not:
 *  - The text, web-search flag and model are CONTROLLED by the caller — the
 *    controller also builds `SendOptions.settings` (autonomy, length,
 *    temperature) from the settings sheet, so this file never sees them.
 *  - Attachments are PromptInput's own (`FileUIPart`s); on submit they are read
 *    back into our `Attachment` through `readAttachment` and folded into the
 *    message with `serialiseAttachments`, so
 *    `SendOptions.attachments` / `wireText` keep their meaning.
 *  - Dictation has two paths. With `transport.transcribe` the composer records
 *    from the input device chosen in `MicSelector` (SpeechInput's MediaRecorder
 *    path) and sends the audio to the transport; without it the browser's own
 *    recogniser is used, which cannot pick a device, so `MicSelector` is hidden.
 *    Either way `SpeechInput.onListeningChange` is lifted as a `VoiceState` for
 *    the header's voice orb: "listening" while recording, "thinking" only once a
 *    dictated message has been sent and until `status` returns to "ready".
 *  - `@` and `/` are palettes: typing either at the start of a
 *    word opens a `PromptInputCommand` list above the composer and takes the
 *    trigger character back out of the text. The + menu is one
 *    panel: files, then the sources (checkable), then the skills. Picked
 *    sources ride the send as `SendOptions.sources` (ids) and show as chips;
 *    a command either runs in the browser or writes its directive into the text.
 *  - Effort is a chip that opens a slider (`EffortSlider`); at the last level,
 *    while the message is focused, the box runs the shared `SparkField`.
 */

import * as React from "react";
import { GaugeIcon, GlobeIcon, ListCollapseIcon, SquareSlashIcon } from "lucide-react";
import { toast } from "sonner";

import {
  AttachmentHoverCard,
  AttachmentHoverCardContent,
  AttachmentHoverCardTrigger,
  Attachment,
  AttachmentInfo,
  AttachmentPreview,
  AttachmentRemove,
  Attachments,
  getAttachmentLabel,
  getMediaCategory,
} from "@/components/ai-elements/attachments";
import {
  Context,
  ContextCacheUsage,
  ContextContent,
  ContextContentBody,
  ContextContentFooter,
  ContextContentHeader,
  ContextInputUsage,
  ContextOutputUsage,
  ContextReasoningUsage,
  ContextTrigger,
} from "@/components/ai-elements/context";
import {
  MicSelector,
  MicSelectorContent,
  MicSelectorEmpty,
  MicSelectorInput,
  MicSelectorItem,
  MicSelectorLabel,
  MicSelectorList,
  MicSelectorTrigger,
} from "@/components/ai-elements/mic-selector";
import {
  ModelSelector,
  ModelSelectorContent,
  ModelSelectorEmpty,
  ModelSelectorGroup,
  ModelSelectorInput,
  ModelSelectorItem,
  ModelSelectorList,
  ModelSelectorLogo,
  ModelSelectorName,
  ModelSelectorTrigger,
} from "@/components/ai-elements/model-selector";
import {
  PromptInput,
  PromptInputActionAddAttachments,
  PromptInputActionMenu,
  PromptInputActionMenuContent,
  PromptInputActionMenuItem,
  PromptInputActionMenuTrigger,
  PromptInputBody,
  PromptInputButton,
  PromptInputCommand,
  PromptInputCommandEmpty,
  PromptInputCommandGroup,
  PromptInputCommandInput,
  PromptInputCommandItem,
  PromptInputCommandList,
  PromptInputFooter,
  PromptInputHeader,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
  usePromptInputAttachments,
  type PromptInputMessage,
} from "@/components/ai-elements/prompt-input";
import { Shimmer } from "@/components/ai-elements/shimmer";
import { SpeechInput } from "@/components/ai-elements/speech-input";
import { Transcription, TranscriptionSegment } from "@/components/ai-elements/transcription";
import { Icon } from "@/components/ui/icon";
import {
  DropdownMenuCheckboxItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import { Popover, PopoverAnchor, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Spinner } from "@/components/ui/spinner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { MAX_FILE_BYTES, readAttachment, serialiseAttachments } from "@/components/agent/core/attachments";
import type { AgentCommand, Attachment as AgentAttachment, AgentTransport, PromptSource, SendOptions } from "@/components/agent/core/types";
import { EffortSlider, isMaxEffort } from "@/components/agent/parts/effort-slider";
import { SparkField, type SparkFieldHandle } from "@/components/agent/parts/spark-field";
import { usePrefersReducedMotion } from "@/hooks/use-reduced-motion";
import { cn } from "@/lib/utils";

import { contextProps } from "./reply-model";

export type VoiceState = "idle" | "listening" | "thinking" | "speaking";

export type WorkspaceComposerProps = {
  transport: AgentTransport;
  value: string;
  onValueChange: (value: string) => void;
  /** Send (the controller queues it instead while busy with a queue-capable transport). */
  onSubmit: (text: string, options: SendOptions) => void;
  onStop: () => void;
  /** AI SDK ChatStatus for PromptInputSubmit. */
  status: "ready" | "submitted" | "streaming" | "error";
  models?: { id: string; name: string; provider?: string }[];
  model?: string;
  onModelChange?: (id: string) => void;
  webSearch: boolean;
  onWebSearchChange: (on: boolean) => void;
  /** What `@` offers. Shown only when `transport.capabilities.sources` is true. */
  sources?: PromptSource[];
  /** What `/` offers; the `skill` ones are also in the + menu. */
  commands?: AgentCommand[];
  /** Effort levels, low to high. Empty or absent renders no Effort control. */
  efforts?: string[];
  effort?: string;
  onEffortChange?: (effort: string) => void;
  /** Rendered attached above the input (the Queue — RunQueue). */
  dock?: React.ReactNode;
  /** Dictation state, lifted so the header's voice orb can show it. */
  onVoiceStateChange?: (state: VoiceState) => void;
  disabled?: boolean;
  disabledReason?: string;
  className?: string;
};

/**
 * Below this width the composer is "compact": only +, the mic and Send stay in
 * the box. 448px is Tailwind's `@md` container step, so the composer turns
 * compact at the same width its `@md/composer` styles would.
 */
const COMPACT_BELOW = 448;

/** The meter offers Summarise from here up — the same point the Context hover card turns urgent. */
const SUMMARISE_AT = 0.9;

const subscribeNever = () => () => {};
const canRecognise = () =>
  typeof window !== "undefined" && ("SpeechRecognition" in window || "webkitSpeechRecognition" in window);
const canRecord = () => typeof window !== "undefined" && "MediaRecorder" in window && "mediaDevices" in navigator;

const isBusy = (status: WorkspaceComposerProps["status"]) => status === "submitted" || status === "streaming";

/** A `FileUIPart` (data: or blob: url) back to the `File` it came from, then to our `Attachment`. */
async function toAttachment(part: PromptInputMessage["files"][number]): Promise<AgentAttachment> {
  const name = part.filename ?? "attachment";
  const type = part.mediaType ?? "";
  let file: File;
  try {
    const blob = await (await fetch(part.url)).blob();
    file = new File([blob], name, { type: type || blob.type });
  } catch {
    // The bytes could not be read back — still send what the user picked, by name.
    file = new File([], name, { type });
  }
  return readAttachment(file);
}

/** One chip in the header: preview swaps for remove on hover, a hover card shows the full image. */
function ComposerAttachment({
  attachment,
  onRemove,
}: {
  attachment: ReturnType<typeof usePromptInputAttachments>["files"][number];
  onRemove: (id: string) => void;
}) {
  const handleRemove = React.useCallback(() => onRemove(attachment.id), [onRemove, attachment.id]);
  const category = getMediaCategory(attachment);
  const label = getAttachmentLabel(attachment);

  return (
    <AttachmentHoverCard>
      <AttachmentHoverCardTrigger asChild>
        <Attachment data={attachment} onRemove={handleRemove}>
          <div className="relative size-5 shrink-0">
            <div className="absolute inset-0 transition-opacity group-hover:opacity-0">
              <AttachmentPreview />
            </div>
            <AttachmentRemove className="absolute inset-0" />
          </div>
          <AttachmentInfo />
        </Attachment>
      </AttachmentHoverCardTrigger>
      <AttachmentHoverCardContent>
        <div className="space-y-3">
          {category === "image" && attachment.type === "file" && attachment.url ? (
            <div className="flex max-h-96 w-80 items-center justify-center overflow-hidden rounded-md border">
              {/* A local object/data url — not an optimisable remote asset. */}
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                alt={label}
                className="max-h-full max-w-full object-contain"
                height={384}
                src={attachment.url}
                width={320}
              />
            </div>
          ) : null}
          <div className="space-y-1 px-0.5">
            <p className="type-nav">{label}</p>
            {attachment.mediaType ? (
              <p className="type-identifier text-muted-foreground">{attachment.mediaType}</p>
            ) : null}
          </div>
        </div>
      </AttachmentHoverCardContent>
    </AttachmentHoverCard>
  );
}

function ComposerAttachments() {
  const attachments = usePromptInputAttachments();
  if (attachments.files.length === 0) return null;
  return (
    <Attachments variant="inline">
      {attachments.files.map((file) => (
        <ComposerAttachment key={file.id} attachment={file} onRemove={attachments.remove} />
      ))}
    </Attachments>
  );
}

/** A picked source as the `Attachment` chip AI Elements draws for a source document. */
const sourceChip = (s: PromptSource) => ({
  type: "source-document" as const,
  id: s.id,
  sourceId: s.id,
  title: s.label,
  filename: s.description,
  mediaType: "text/plain",
});

/** `@` or `/` typed at the start of a word — the character a palette opens on, or null. */
function paletteTrigger(previous: string, next: string, caret: number): "@" | "/" | null {
  if (next.length !== previous.length + 1 || caret < 1) return null;
  const typed = next[caret - 1];
  if (typed !== "@" && typed !== "/") return null;
  return caret === 1 || /\s/.test(next[caret - 2]) ? typed : null;
}

/** Submit: Stop while a reply is on its way, otherwise disabled until there is something to send. */
function ComposerSubmit({
  status,
  onStop,
  hasText,
  disabled,
}: {
  status: WorkspaceComposerProps["status"];
  onStop: () => void;
  hasText: boolean;
  disabled?: boolean;
}) {
  const attachments = usePromptInputAttachments();
  const busy = isBusy(status);
  const empty = !hasText && attachments.files.length === 0;
  return <PromptInputSubmit disabled={busy ? false : disabled || empty} onStop={onStop} status={status} />;
}

export function WorkspaceComposer({
  transport,
  value,
  onValueChange,
  onSubmit,
  onStop,
  status,
  models,
  model,
  onModelChange,
  webSearch,
  onWebSearchChange,
  sources,
  commands,
  efforts,
  effort,
  onEffortChange,
  dock,
  onVoiceStateChange,
  disabled,
  disabledReason,
  className,
}: WorkspaceComposerProps) {
  const { capabilities, usage, summarise } = transport;
  const showModels = Boolean(models?.length && capabilities.models);
  const selectedModel = models?.find((m) => m.id === model) ?? models?.[0];
  const [modelOpen, setModelOpen] = React.useState(false);
  const [micId, setMicId] = React.useState<string | undefined>();
  const [summarising, setSummarising] = React.useState(false);

  /* ── Dictation ───────────────────────────────────────────────────────── */

  // With `transcribe` we record and send the audio; otherwise the browser recognises.
  const recording = Boolean(transport.transcribe);
  const dictation = React.useSyncExternalStore(subscribeNever, recording ? canRecord : canRecognise, () => false);
  const valueRef = React.useRef(value);
  const [listening, setListening] = React.useState(false);
  const [dictated, setDictated] = React.useState(false);
  const [thinking, setThinking] = React.useState(false);
  const [transcribing, setTranscribing] = React.useState(false);
  const [segments, setSegments] = React.useState<{ text: string; startSecond: number; endSecond: number }[]>([]);

  React.useEffect(() => {
    valueRef.current = value;
  }, [value]);

  const handleListeningChange = React.useCallback((next: boolean) => {
    setListening(next);
    if (next) setSegments([]);
  }, []);

  // Dictated text that is emptied again was never going to be sent.
  if (dictated && !value.trim()) setDictated(false);

  // Thinking lasts until the send that followed it settles (busy → ready). Adjusting
  // state while rendering is the supported way to react to a prop change.
  const [prevStatus, setPrevStatus] = React.useState(status);
  if (prevStatus !== status) {
    setPrevStatus(status);
    if (isBusy(prevStatus) && status === "ready" && thinking) setThinking(false);
  }

  // Transcribing a recording is the agent working on what was said — the orb thinks.
  const voiceState: VoiceState = listening ? "listening" : thinking || transcribing ? "thinking" : "idle";
  const reported = React.useRef<VoiceState>("idle");
  const onVoiceStateChangeRef = React.useRef(onVoiceStateChange);
  React.useEffect(() => {
    onVoiceStateChangeRef.current = onVoiceStateChange;
  });
  React.useEffect(() => {
    if (reported.current === voiceState) return;
    reported.current = voiceState;
    onVoiceStateChangeRef.current?.(voiceState);
  }, [voiceState]);
  // Leaving while the voice is active must not strand the header's voice orb.
  React.useEffect(
    () => () => {
      if (reported.current !== "idle") {
        reported.current = "idle";
        onVoiceStateChangeRef.current?.("idle");
      }
    },
    [],
  );

  const handleTranscription = React.useCallback(
    (text: string) => {
      const chunk = text.trim();
      if (!chunk) return;
      const current = valueRef.current;
      const next = current && !/\s$/.test(current) ? `${current} ${chunk}` : `${current}${chunk}`;
      valueRef.current = next;
      onValueChange(next);
      setDictated(true);
      setSegments((prev) => [...prev, { text: chunk, startSecond: prev.length, endSecond: prev.length + 1 }]);
    },
    [onValueChange],
  );

  /** SpeechInput's recorder path: audio in, text out. Failure is a toast, never silence. */
  const transcribe = transport.transcribe;
  const handleAudio = React.useCallback(
    async (audio: Blob) => {
      if (!transcribe) return "";
      setTranscribing(true);
      try {
        return await transcribe(audio);
      } catch {
        toast.error("Could not transcribe that recording. Try again.");
        return "";
      } finally {
        setTranscribing(false);
      }
    },
    [transcribe],
  );

  /* ── @ sources and / commands ────────────────────────────────────────── */

  const showSources = Boolean(capabilities.sources && sources?.length);
  const [chosen, setChosen] = React.useState<PromptSource[]>([]);
  const [palette, setPalette] = React.useState<"@" | "/" | null>(null);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  // Where the trigger was typed, so a command's directive goes back in that spot.
  const insertAt = React.useRef<number | null>(null);
  const skills = (commands ?? []).filter((c) => c.group === "skill");

  const closePalette = () => setPalette(null);

  const addSource = (source: PromptSource) => {
    setChosen((prev) => (prev.some((s) => s.id === source.id) ? prev : [...prev, source]));
    closePalette();
  };
  const removeSource = (id: string) => setChosen((prev) => prev.filter((s) => s.id !== id));
  const toggleSource = (source: PromptSource, on: boolean) =>
    setChosen((prev) => (on ? (prev.some((s) => s.id === source.id) ? prev : [...prev, source]) : prev.filter((s) => s.id !== source.id)));

  const runCommand = React.useCallback((command: AgentCommand) => {
    setPalette(null);
    if (command.run) {
      command.run();
      return;
    }
    const insert = command.directive ?? `/${command.id}`;
    const current = valueRef.current;
    const at = Math.min(insertAt.current ?? current.length, current.length);
    const head = current.slice(0, at);
    const tail = current.slice(at);
    const next = `${head}${head && !/\s$/.test(head) ? " " : ""}${insert} ${tail.replace(/^\s+/, "")}`;
    valueRef.current = next;
    onValueChange(next);
  }, [onValueChange]);

  const handleTextChange = React.useCallback((event: React.ChangeEvent<HTMLTextAreaElement>) => {
    const next = event.currentTarget.value;
    const caret = event.currentTarget.selectionStart ?? next.length;
    const trigger = paletteTrigger(valueRef.current, next, caret);
    if ((trigger === "@" && showSources) || (trigger === "/" && commands?.length)) {
      // The palette takes the keystroke: the trigger does not stay in the message.
      const without = next.slice(0, caret - 1) + next.slice(caret);
      valueRef.current = without;
      onValueChange(without);
      insertAt.current = caret - 1;
      setPalette(trigger);
      return;
    }
    valueRef.current = next;
    onValueChange(next);
    sparks.current?.bump();
  }, [showSources, commands?.length, onValueChange]);

  const showEffort = Boolean(efforts?.length && onEffortChange);
  const [effortOpen, setEffortOpen] = React.useState(false);
  const maxed = showEffort && isMaxEffort(efforts ?? [], effort);
  const reduce = usePrefersReducedMotion();
  const [focused, setFocused] = React.useState(false);
  const sparks = React.useRef<SparkFieldHandle>(null);
  const sparking = maxed && focused && !reduce;

  /* Compact is measured, not a media query: the composer is embedded at any
     width. A layout effect so the first painted frame already has it right. */
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [compact, setCompact] = React.useState(false);
  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root || typeof ResizeObserver === "undefined") return undefined;
    const measure = () => {
      const width = root.getBoundingClientRect().width;
      setCompact(width > 0 && width < COMPACT_BELOW);
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  /* ── Send ────────────────────────────────────────────────────────────── */

  const handleSubmit = async (message: PromptInputMessage) => {
    const text = message.text.trim();
    if (!text && message.files.length === 0) return;
    const read = message.files.length ? await Promise.all(message.files.map(toAttachment)) : [];
    const payload = read.length ? serialiseAttachments(text, read) : { text, attachments: [] as AgentAttachment[] };
    const options: SendOptions = {
      ...(payload.attachments.length ? { attachments: payload.attachments } : {}),
      ...(payload.text !== text ? { wireText: payload.text } : {}),
      ...(showModels && selectedModel ? { model: selectedModel.id } : {}),
      ...(webSearch ? { webSearch: true } : {}),
      ...(showSources && chosen.length ? { sources: chosen.map((s) => s.id) } : {}),
    };
    valueRef.current = "";
    setChosen([]);
    if (dictated) {
      setDictated(false);
      setThinking(true);
    }
    onValueChange("");
    onSubmit(text, options);
  };

  const handleSummarise = async () => {
    if (!summarise || summarising) return;
    setSummarising(true);
    try {
      await summarise();
      toast.success("Conversation summarised");
    } catch {
      toast.error("Could not summarise the conversation. Try again.");
    } finally {
      setSummarising(false);
    }
  };

  const usedFraction = usage && usage.maxTokens > 0 ? usage.usedTokens / usage.maxTokens : 0;
  const offerSummarise = Boolean(summarise) && usedFraction >= SUMMARISE_AT;

  /* + — one panel: files, then sources (checkable), then skills. */
  const showFiles = capabilities.attachments !== "none";
  const plusMenu =
    showFiles || showSources || skills.length ? (
      <PromptInputActionMenu>
        <PromptInputActionMenuTrigger aria-label="Add files, sources or skills" disabled={disabled} />
        <PromptInputActionMenuContent className="w-64">
          {showFiles ? <PromptInputActionAddAttachments /> : null}
          {showSources ? (
            <>
              {showFiles ? <DropdownMenuSeparator /> : null}
              <DropdownMenuLabel>Sources</DropdownMenuLabel>
              {sources?.map((source) => (
                <DropdownMenuCheckboxItem
                  checked={chosen.some((c) => c.id === source.id)}
                  key={source.id}
                  onCheckedChange={(on) => toggleSource(source, on === true)}
                  // Several sources are picked in one visit: the panel stays open.
                  onSelect={(event) => event.preventDefault()}
                >
                  {source.icon ? <Icon icon={source.icon} size="md" tone="inherit" /> : null}
                  {source.label}
                </DropdownMenuCheckboxItem>
              ))}
            </>
          ) : null}
          {skills.length ? (
            <>
              {showFiles || showSources ? <DropdownMenuSeparator /> : null}
              <DropdownMenuLabel>Skills</DropdownMenuLabel>
              {skills.map((skill) => (
                <PromptInputActionMenuItem key={skill.id} onSelect={() => runCommand(skill)}>
                  <Icon icon={skill.icon ?? SquareSlashIcon} size="md" tone="inherit" />
                  {skill.label}
                </PromptInputActionMenuItem>
              ))}
            </>
          ) : null}
        </PromptInputActionMenuContent>
      </PromptInputActionMenu>
    ) : null;

  /* Dictation and its microphone choice are one split control, beside Send. */
  const dictationControl = dictation ? (
    <div className="flex shrink-0 items-center" data-slot="composer-dictation">
      <SpeechInput
        className="shrink-0"
        deviceId={recording ? micId : undefined}
        disabled={disabled}
        onAudioRecorded={recording ? handleAudio : undefined}
        onListeningChange={handleListeningChange}
        onTranscriptionChange={handleTranscription}
        preferMediaRecorder={recording}
        size="icon-sm"
        // Inside the form, a bare button would submit the message.
        type="button"
        variant="ghost"
      />
      {recording ? (
        <MicSelector onValueChange={setMicId} value={micId}>
          <MicSelectorTrigger aria-label="Choose microphone" className="-ml-1 px-1" size="sm" type="button" variant="ghost" />
          <MicSelectorContent popoverOptions={{ align: "end", side: "top" }}>
            <MicSelectorInput />
            <MicSelectorEmpty />
            <MicSelectorList>
              {(devices) =>
                devices.map((device) => (
                  <MicSelectorItem key={device.deviceId} value={device.deviceId}>
                    <MicSelectorLabel device={device} />
                  </MicSelectorItem>
                ))
              }
            </MicSelectorList>
          </MicSelectorContent>
        </MicSelector>
      ) : null}
    </div>
  ) : null;

  /* Search · model · Effort — in the box when there is room, under it when compact. */
  const secondary = (
    <div className="flex min-w-0 items-center gap-1" data-slot="composer-options">
      <PromptInputButton
        aria-label="Search the web"
        aria-pressed={webSearch}
        onClick={() => onWebSearchChange(!webSearch)}
        tooltip="Search the web for this message"
        type="button"
        variant={webSearch ? "default" : "ghost"}
      >
        <Icon icon={GlobeIcon} size="md" />
        <span className="hidden @sm/composer:inline">Search</span>
      </PromptInputButton>

      {showModels && selectedModel ? (
        <ModelSelector onOpenChange={setModelOpen} open={modelOpen}>
          <ModelSelectorTrigger asChild>
            <PromptInputButton type="button">
              {selectedModel.provider ? <ModelSelectorLogo provider={selectedModel.provider} /> : null}
              <ModelSelectorName className="max-w-20 truncate @sm/composer:max-w-40">{selectedModel.name}</ModelSelectorName>
            </PromptInputButton>
          </ModelSelectorTrigger>
          <ModelSelectorContent title="Choose a model">
            <ModelSelectorInput placeholder="Search models..." />
            <ModelSelectorList>
              <ModelSelectorEmpty>No models found.</ModelSelectorEmpty>
              {Array.from(new Set(models?.map((m) => m.provider ?? "Models"))).map((provider) => (
                <ModelSelectorGroup heading={provider} key={provider}>
                  {models
                    ?.filter((m) => (m.provider ?? "Models") === provider)
                    .map((m) => (
                      <ModelSelectorItem
                        key={m.id}
                        onSelect={() => {
                          onModelChange?.(m.id);
                          setModelOpen(false);
                        }}
                        value={`${m.name} ${m.id}`}
                      >
                        {m.provider ? <ModelSelectorLogo provider={m.provider} /> : null}
                        <ModelSelectorName>{m.name}</ModelSelectorName>
                      </ModelSelectorItem>
                    ))}
                </ModelSelectorGroup>
              ))}
            </ModelSelectorList>
          </ModelSelectorContent>
        </ModelSelector>
      ) : null}

      {showEffort && effort ? (
        <Popover onOpenChange={setEffortOpen} open={effortOpen}>
          <PopoverTrigger asChild>
            <PromptInputButton
              aria-label={`Choose effort, ${effort}`}
              className={cn(maxed && "text-agent hover:text-agent")}
              disabled={disabled}
              type="button"
            >
              <Icon icon={GaugeIcon} size="md" tone="inherit" />
              <span className="hidden @sm/composer:inline">{effort}</span>
            </PromptInputButton>
          </PopoverTrigger>
          <PopoverContent
            align="end"
            aria-label="Effort"
            className="w-64 p-3.5"
            onCloseAutoFocus={(event) => {
              // Back to the message, so the sparks it just armed are seen.
              event.preventDefault();
              textareaRef.current?.focus();
            }}
            side="top"
          >
            <EffortSlider
              efforts={efforts ?? []}
              onEscape={() => setEffortOpen(false)}
              onValueChange={(level) => onEffortChange?.(level)}
              value={effort}
            />
          </PopoverContent>
        </Popover>
      ) : null}
    </div>
  );

  /* Summarise · the context meter. */
  const meters =
    offerSummarise || usage ? (
      <div className="flex shrink-0 items-center gap-1" data-slot="composer-meters">
        {offerSummarise ? (
          <PromptInputButton
            aria-label="Summarise"
            // Not while a reply is being written: the summary would land inside it.
            disabled={summarising || status !== "ready"}
            onClick={handleSummarise}
            tooltip="Condense this conversation to free up context"
            type="button"
          >
            {summarising ? <Spinner /> : <Icon icon={ListCollapseIcon} size="md" />}
            <span className="hidden @sm/composer:inline">Summarise</span>
          </PromptInputButton>
        ) : null}
        {usage ? (
          <Context {...contextProps(usage)}>
            <ContextTrigger className="[&>span]:hidden @sm/composer:[&>span]:inline" size="sm" />
            <ContextContent>
              <ContextContentHeader />
              <ContextContentBody className="space-y-1.5">
                <ContextInputUsage />
                <ContextOutputUsage />
                <ContextReasoningUsage />
                <ContextCacheUsage />
              </ContextContentBody>
              <ContextContentFooter />
            </ContextContent>
          </Context>
        ) : null}
      </div>
    ) : null;

  return (
    <TooltipProvider>
      <div
        data-slot="workspace-composer"
        data-compact={compact ? "" : undefined}
        ref={rootRef}
        className={cn("@container/composer flex w-full flex-col", className)}
      >
        {dock ? (
          <div
            data-slot="workspace-composer-dock"
            className="mx-auto w-[95%] *:rounded-b-none *:border-b-0"
          >
            {dock}
          </div>
        ) : null}

        {/* `@` and `/` open their palette above the whole composer. */}
        <Popover onOpenChange={(open) => (open ? undefined : closePalette())} open={palette !== null}>
          <PopoverAnchor asChild>
            <div>
        {/* A tall composer as a pill clips its own placeholder on a phone; Claude's is a rounded rectangle. */}
        <PromptInput
          className="[&_[data-slot=input-group]]:isolate [&_[data-slot=input-group]]:rounded-3xl"
          globalDrop
          multiple
          maxFileSize={MAX_FILE_BYTES}
          onError={(error) => toast.error(error.message)}
          onSubmit={handleSubmit}
        >
          <SparkField active={sparking} ref={sparks} />
          <PromptInputHeader>
            <ComposerAttachments />
            {showSources && chosen.length > 0 ? (
              <Attachments aria-label="Sources" variant="inline">
                {chosen.map((source) => (
                  <Attachment data={sourceChip(source)} key={source.id} onRemove={() => removeSource(source.id)}>
                    <AttachmentPreview />
                    <AttachmentInfo />
                    <AttachmentRemove label={`Remove ${source.label}`} />
                  </Attachment>
                ))}
              </Attachments>
            ) : null}
            {listening && segments.length > 0 ? (
              <Transcription
                aria-live="polite"
                className="w-full"
                currentTime={segments.length - 0.5}
                segments={segments}
              >
                {(segment, index) => (
                  <TranscriptionSegment
                    key={`${segment.startSecond}-${segment.endSecond}`}
                    index={index}
                    segment={segment}
                  />
                )}
              </Transcription>
            ) : null}
            {transcribing ? (
              <Shimmer as="p" className="type-small text-muted-foreground">
                Transcribing…
              </Shimmer>
            ) : null}
          </PromptInputHeader>

          <PromptInputBody>
            <PromptInputTextarea
              aria-label="Message"
              disabled={disabled}
              onBlur={() => setFocused(false)}
              onChange={handleTextChange}
              onFocus={() => setFocused(true)}
              ref={textareaRef}
              placeholder={disabled && disabledReason ? disabledReason : "Message the agent…"}
              value={value}
            />
          </PromptInputBody>

          <PromptInputFooter>
            <PromptInputTools className="min-w-0 flex-1 flex-wrap gap-y-1">
              {plusMenu}
              {compact ? null : secondary}
            </PromptInputTools>

            <div className="ml-auto flex shrink-0 items-center gap-1">
              {compact ? null : meters}
              {dictationControl}
              <ComposerSubmit disabled={disabled} hasText={value.trim().length > 0} onStop={onStop} status={status} />
            </div>
          </PromptInputFooter>
        </PromptInput>
            </div>
          </PopoverAnchor>
          <PopoverContent
            align="start"
            aria-label={palette === "@" ? "Sources" : "Commands"}
            className="p-0"
            onCloseAutoFocus={(event) => {
              // Back to the message, not to whatever opened the palette.
              event.preventDefault();
              textareaRef.current?.focus();
            }}
            side="top"
          >
            <PromptInputCommand>
              <PromptInputCommandInput
                aria-label={palette === "@" ? "Search sources" : "Search commands"}
                placeholder={palette === "@" ? "Add a source…" : "Run a command…"}
              />
              <PromptInputCommandList>
                <PromptInputCommandEmpty>{palette === "@" ? "No sources found." : "No commands found."}</PromptInputCommandEmpty>
                {palette === "@" ? (
                  <PromptInputCommandGroup heading="Sources">
                    {sources
                      ?.filter((s) => !chosen.some((c) => c.id === s.id))
                      .map((source) => (
                        <PromptInputCommandItem
                          key={source.id}
                          onSelect={() => addSource(source)}
                          value={`${source.label} ${source.description ?? ""}`}
                        >
                          {source.icon ? <Icon icon={source.icon} size="md" tone="inherit" /> : null}
                          <span className="flex min-w-0 flex-col">
                            <span className="type-nav truncate">{source.label}</span>
                            {source.description ? (
                              <span className="type-small truncate text-muted-foreground">{source.description}</span>
                            ) : null}
                          </span>
                        </PromptInputCommandItem>
                      ))}
                  </PromptInputCommandGroup>
                ) : (
                  <PromptInputCommandGroup heading="Commands">
                    {commands?.map((command) => (
                      <PromptInputCommandItem
                        key={command.id}
                        onSelect={() => runCommand(command)}
                        value={`${command.label} ${command.hint ?? ""}`}
                      >
                        <Icon icon={command.icon ?? SquareSlashIcon} size="md" tone="inherit" />
                        <span className="flex min-w-0 flex-col">
                          <span className="type-nav truncate">
                            {/* A command is typed as /name; a skill keeps its own name. */}
                          {command.group === "skill" || command.label.startsWith("/") ? command.label : `/${command.label}`}
                          </span>
                          {command.hint ? (
                            <span className="type-small truncate text-muted-foreground">{command.hint}</span>
                          ) : null}
                        </span>
                      </PromptInputCommandItem>
                    ))}
                  </PromptInputCommandGroup>
                )}
              </PromptInputCommandList>
            </PromptInputCommand>
          </PopoverContent>
        </Popover>

        {compact ? (
          <div className="mt-2 flex items-center gap-1 px-1" data-slot="composer-below">
            {secondary}
            <div className="ml-auto">{meters}</div>
          </div>
        ) : null}
      </div>
    </TooltipProvider>
  );
}

"use client";

/**
 * WorkspaceHeader — thin, Claude-style: leading slot · agent avatar · name / title ·
 * voice orb (only while voice is active) · settings gear. No activity toggle, no
 * New-chat icon, no status text — those live where they belong (the history
 * sidebar, the run inline in the thread).
 *
 * The face is the agent's own avatar (`CubeAvatar` by default — the set of
 * twenty-six animated scenes, one per agent state), drawn for the agent's
 * current `state`, so the header shows at a glance that it is thinking,
 * running a tool or waiting. A caller that brings its own face passes
 * `avatar` (an `AvatarRenderer`).
 *
 * `VoiceOrb` is the voice-mode face. It mounts through `usePresence` when
 * `voiceState` leaves "idle" and plays its exit before it unmounts, keeping the
 * last active state on screen while it leaves rather than flickering to
 * "idle". `VoiceState` is the composer's: listening / thinking / speaking are
 * the orb's own states, unchanged.
 *
 * The gear opens the settings `Sheet` only when `showSettings` is true, i.e. when
 * the transport advertises `capabilities.settings`.
 */

import * as React from "react";
import { SettingsIcon } from "lucide-react";

import { CubeAvatar } from "@/components/agent/avatar/cube-avatar";
import { usePresence } from "@/components/agent/core/use-presence";
import { VoiceOrb, type VoiceOrbState } from "@/components/agent/parts/voice-orb";
import type { AvatarRenderer } from "@/components/agent/avatar/types";
import type { AgentState } from "@/components/agent/core/states";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import type { VoiceState } from "./workspace-composer";
import { WorkspaceSettings, type WorkspaceSettingsProps } from "./workspace-settings";

export type WorkspaceHeaderProps = {
  /** The agent's display name, beside the logo. Default "Agent". */
  name?: string;
  /** The conversation's own title. Absent renders nothing — no placeholder. */
  title?: string;
  /** The agent's face, drawn for `state`. Defaults to `CubeAvatar`. */
  avatar?: AvatarRenderer;
  /** The agent's state, for `avatar`. */
  state?: AgentState;
  /** Leading slot — the controller puts the history SidebarTrigger here. */
  leading?: React.ReactNode;
  /** The voice orb shows only while voice is active (state !== "idle"); the avatar stays the face. */
  voiceState: VoiceState;
  settings: WorkspaceSettingsProps;
  /** Whether `transport.capabilities.settings` is true — gates the gear and its sheet. */
  showSettings?: boolean;
  settingsOpen?: boolean;
  onSettingsOpenChange?: (open: boolean) => void;
  className?: string;
};

export function WorkspaceHeader({
  name = "Agent",
  title,
  avatar: Avatar = CubeAvatar,
  state = "idle",
  leading,
  voiceState,
  settings,
  showSettings = true,
  settingsOpen,
  onSettingsOpenChange,
  className,
}: WorkspaceHeaderProps) {
  const active = voiceState !== "idle";
  const presence = usePresence(active);

  // Keep showing the last active state while the orb plays its exit.
  const [shown, setShown] = React.useState<VoiceOrbState>("listening");
  if (voiceState !== "idle" && shown !== voiceState) setShown(voiceState);

  return (
    <header
      data-slot="workspace-header"
      className={cn("flex items-center gap-3 border-b border-border px-4 py-3", className)}
    >
      {leading}

      <div data-slot="workspace-header-avatar" className="shrink-0">
        <Avatar state={state} size="sm" />
      </div>

      <div className="min-w-0 flex-1">
        <p className="type-small truncate text-foreground">{name}</p>
        {title ? <p className="type-small truncate text-muted-foreground">{title}</p> : null}
      </div>

      {presence.mounted ? (
        <div data-slot="workspace-header-voice" className={cn("size-8 shrink-0", presence.className)}>
          <VoiceOrb state={shown} />
        </div>
      ) : null}

      {showSettings ? (
        <Sheet open={settingsOpen} onOpenChange={onSettingsOpenChange}>
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <SheetTrigger asChild>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
                    className="min-h-(--size-target-min) min-w-(--size-target-min)"
                    aria-label="Open workspace settings"
                  >
                    <Icon icon={SettingsIcon} size="sm" tone="inherit" aria-hidden />
                  </Button>
                </SheetTrigger>
              </TooltipTrigger>
              <TooltipContent>Settings</TooltipContent>
            </Tooltip>
          </TooltipProvider>
          <SheetContent side="right">
            <WorkspaceSettings {...settings} />
          </SheetContent>
        </Sheet>
      ) : null}
    </header>
  );
}

"use client";

/**
 * Conversation history, in the Claude pattern, on our shadcn Sidebar.
 *
 * AI Elements has no history component, so this is `components/ui/sidebar.tsx`
 * composed: a "New chat" button on top, one `SidebarGroup` per age bucket
 * (Today / Yesterday / Previous 7 days / Older), rows that are the title only,
 * and a `⋯` menu per row (Archive, Delete). Delete is undoable from its toast.
 *
 * It renders the Sidebar's *content*. The host places it inside
 * `SidebarProvider` + `Sidebar` and puts the `SidebarTrigger` in its header;
 * on mobile the Sidebar's own Sheet carries it.
 */

import * as React from "react";
import { ArchiveIcon, MoreHorizontalIcon, PlusIcon, Trash2Icon } from "lucide-react";
import { toast } from "sonner";

import type { ConversationSummary } from "@/components/agent/core/conversations";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Icon } from "@/components/ui/icon";
import {
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";

export type WorkspaceHistoryProps = {
  items: ConversationSummary[];
  activeId?: string;
  onOpen: (id: string) => void;
  onNew?: () => void;
  onArchive?: (id: string) => void;
  onDelete?: (id: string) => void;
  /** Undo for Delete's toast — puts the row back. */
  onRestore?: (item: ConversationSummary) => void;
  /** "Now" for the date grouping (tests). Defaults to Date.now(). */
  now?: number;
};

export type HistoryBucket = "Today" | "Yesterday" | "Previous 7 days" | "Older";

const BUCKETS: HistoryBucket[] = ["Today", "Yesterday", "Previous 7 days", "Older"];

function startOfDay(ms: number): number {
  const d = new Date(ms);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

/** Which age bucket a timestamp falls in, by calendar day relative to `now`. */
export function historyBucket(updatedAt: string, now: number): HistoryBucket {
  const t = new Date(updatedAt).getTime();
  const today = startOfDay(now);
  const day = 24 * 60 * 60 * 1000;
  if (Number.isNaN(t) || t >= today) return "Today";
  if (t >= today - day) return "Yesterday";
  if (t >= today - 7 * day) return "Previous 7 days";
  return "Older";
}

/** Items grouped into non-empty buckets, newest first within each. */
export function groupHistory(items: ConversationSummary[], now: number) {
  const sorted = [...items].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  return BUCKETS.map((label) => ({
    label,
    items: sorted.filter((i) => historyBucket(i.updatedAt, now) === label),
  })).filter((g) => g.items.length > 0);
}

export function WorkspaceHistory({
  items,
  activeId,
  onOpen,
  onNew,
  onArchive,
  onDelete,
  onRestore,
  now,
}: WorkspaceHistoryProps) {
  // Read once per mount so server and client group identically.
  const [mountedAt] = React.useState(() => Date.now());
  const groups = groupHistory(items, now ?? mountedAt);

  const remove = (item: ConversationSummary) => {
    onDelete?.(item.id);
    toast("Conversation deleted", {
      description: item.title,
      action: onRestore ? { label: "Undo", onClick: () => onRestore(item) } : undefined,
    });
  };

  const archive = (item: ConversationSummary) => {
    onArchive?.(item.id);
    toast("Conversation archived", { description: item.title });
  };

  return (
    <>
      <SidebarHeader>
        {onNew ? (
          <Button variant="outline" className="w-full justify-start gap-2" onClick={onNew}>
            <Icon icon={PlusIcon} size="sm" tone="inherit" aria-hidden />
            New chat
          </Button>
        ) : null}
      </SidebarHeader>
      <SidebarContent>
        {groups.length === 0 ? (
          <p className="type-small px-6 py-4 text-muted-foreground">No conversations yet.</p>
        ) : (
          groups.map((group) => (
            <SidebarGroup key={group.label} aria-label={group.label}>
              <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
              <SidebarGroupContent>
                <SidebarMenu>
                  {group.items.map((item) => (
                    <SidebarMenuItem key={item.id}>
                      <SidebarMenuButton isActive={item.id === activeId} onClick={() => onOpen(item.id)}>
                        <span>{item.title}</span>
                      </SidebarMenuButton>
                      {onArchive || onDelete ? (
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <SidebarMenuAction showOnHover aria-label={`Actions for ${item.title}`}>
                              <Icon icon={MoreHorizontalIcon} size="sm" tone="inherit" aria-hidden />
                            </SidebarMenuAction>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            {onArchive ? (
                              <DropdownMenuItem onSelect={() => archive(item)}>
                                <Icon icon={ArchiveIcon} size="sm" tone="inherit" aria-hidden />
                                Archive
                              </DropdownMenuItem>
                            ) : null}
                            {onDelete ? (
                              <DropdownMenuItem variant="destructive" onSelect={() => remove(item)}>
                                <Icon icon={Trash2Icon} size="sm" tone="inherit" aria-hidden />
                                Delete
                              </DropdownMenuItem>
                            ) : null}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      ) : null}
                    </SidebarMenuItem>
                  ))}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          ))
        )}
      </SidebarContent>
    </>
  );
}

