/* ── Markdown: citations, code, snippets ─────────────────────────────────── */

const SourcesContext = React.createContext<AgentSource[]>([]);

const CITE = "#cite-";

/**
 * Turn `[1]` / `[1][2]` markers into links to `#cite-1` / `#cite-1-2` so the
 * renderer can draw them as `InlineCitation`s. Only markers that name a real
 * source become links, and code (fenced or inline) is left alone.
 */
export function linkCitations(text: string, sources: AgentSource[]): string {
  if (!sources.length || !text.includes("[")) return text;
  const known = new Set(sources.map((s) => s.n));
  return text
    .split(/(```[\s\S]*?(?:```|$)|`[^`\n]*`)/)
    .map((part, i) =>
      i % 2 === 1
        ? part
        : part.replace(/((?:\[\d{1,3}\])+)(?!\()/g, (run) => {
            const ns = [...run.matchAll(/\[(\d+)\]/g)].map((m) => Number(m[1])).filter((n) => known.has(n));
            return ns.length ? `[cite](${CITE}${ns.join("-")})` : run;
          }),
    )
    .join("");
}

function sourceUrl(s: AgentSource): string {
  try {
    return new URL(s.url).href;
  } catch {
    return `https://${s.domain}`;
  }
}

function Citation({ ns }: { ns: number[] }) {
  const sources = React.useContext(SourcesContext);
  const picked = ns.map((n) => sources.find((s) => s.n === n)).filter((s): s is AgentSource => Boolean(s));
  if (!picked.length) return null;
  return (
    <InlineCitation>
      <InlineCitationCard>
        <InlineCitationCardTrigger sources={picked.map(sourceUrl)} tabIndex={0} />
        <InlineCitationCardBody>
          <InlineCitationCarousel>
            {picked.length > 1 ? (
              <InlineCitationCarouselHeader>
                <InlineCitationCarouselPrev />
                <InlineCitationCarouselNext />
                <InlineCitationCarouselIndex />
              </InlineCitationCarouselHeader>
            ) : null}
            <InlineCitationCarouselContent>
              {picked.map((s) => (
                <InlineCitationCarouselItem key={s.id}>
                  <InlineCitationSource description={s.snippet} title={s.title} url={sourceUrl(s)} />
                </InlineCitationCarouselItem>
              ))}
            </InlineCitationCarouselContent>
          </InlineCitationCarousel>
        </InlineCitationCardBody>
      </InlineCitationCard>
    </InlineCitation>
  );
}

function MarkdownLink({ href, children }: React.ComponentProps<"a">) {
  if (href?.startsWith(CITE)) {
    const ns = href.slice(CITE.length).split("-").map(Number).filter(Number.isFinite);
    return <Citation ns={ns} />;
  }
  return (
    <a className="text-action-ink underline underline-offset-4" href={href} rel="noreferrer noopener" target="_blank">
      {children}
    </a>
  );
}

function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(textOf).join("");
  if (React.isValidElement<{ children?: React.ReactNode }>(node)) return textOf(node.props.children);
  return "";
}

const SHELL = new Set(["sh", "bash", "shell", "zsh", "console", "terminal", "shellscript", "powershell", "cmd", "bat"]);

/** A fenced block: a one-line shell command is a `Snippet`, anything else a `CodeBlock`. */
function MarkdownBlockCode({ className, children }: React.ComponentProps<"code">) {
  const language = /language-([\w+-]+)/.exec(className ?? "")?.[1] ?? "";
  const code = textOf(children).replace(/\n$/, "");
  const onCopy = () => toast.success("Copied to clipboard");

  if (SHELL.has(language.toLowerCase()) && !code.includes("\n") && code.length <= 160) {
    const command = code.replace(/^\$\s+/, "");
    return (
      <Snippet className="my-4 max-w-full" code={command}>
        <SnippetAddon className="pl-1">
          <SnippetText>$</SnippetText>
        </SnippetAddon>
        <SnippetInput aria-label="Command" />
        <SnippetAddon align="inline-end" className="pr-2">
          <SnippetCopyButton onCopy={onCopy} onError={copyFailed} />
        </SnippetAddon>
      </Snippet>
    );
  }

  return (
    <CodeBlock className="my-4" code={code} language={codeLanguage(language)}>
      <CodeBlockHeader>
        <CodeBlockTitle>
          <CodeBlockFilename>{language || "text"}</CodeBlockFilename>
        </CodeBlockTitle>
        <CodeBlockActions>
          <CodeBlockCopyButton onCopy={onCopy} onError={copyFailed} />
        </CodeBlockActions>
      </CodeBlockHeader>
    </CodeBlock>
  );
}

function MarkdownInlineCode({ className, children }: React.ComponentProps<"code">) {
  return <code className={cn("rounded-sm bg-muted px-1.5 py-0.5 type-code", className)}>{children}</code>;
}

const MARKDOWN_COMPONENTS = {
  a: MarkdownLink,
  code: MarkdownBlockCode,
  inlineCode: MarkdownInlineCode,
};

function Response({ turn, text, sources }: { turn: TextTurn; text: string; sources: AgentSource[] }) {
  return (
    <SourcesContext.Provider value={sources}>
      <MessageContent>
        <MessageResponse components={MARKDOWN_COMPONENTS} isAnimating={Boolean(turn.streaming)}>
          {linkCitations(text, sources)}
        </MessageResponse>
      </MessageContent>
    </SourcesContext.Provider>
  );
}

/* ── User message ────────────────────────────────────────────────────────── */

export type WorkspaceUserMessageProps = {
  turn: UserTurn;
  transport: AgentTransport;
  className?: string;
};

/**
 * A user message: its attachments (image tiles, file chips), the text in a
 * bubble, and under it Copy, Edit (inline) and — once edited — `MessageBranch`
 * ‹ n of m › over the versions.
 */
export function WorkspaceUserMessage({ turn, transport, className }: WorkspaceUserMessageProps) {
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(turn.text);
  const [saving, setSaving] = React.useState(false);
  const { copied, copy } = useCopy(turn.text);

  const branching = Boolean(transport.capabilities.branching);
  const canNavigate = branching && Boolean(transport.selectBranch);
  const canEdit = branching && Boolean(transport.editMessage);

  const all = turn.versions?.length ? turn.versions : [{ id: `${turn.id}-v1`, text: turn.text }];
  const active = Math.min(turn.activeVersion ?? all.length - 1, all.length - 1);
  const versions = canNavigate ? all : [{ ...all[active], text: turn.text }];
  const images = (turn.attachments ?? []).filter((a) => a.kind === "image");
  const files = (turn.attachments ?? []).filter((a) => a.kind !== "image");

  const save = async () => {
    const next = draft.trim();
    if (!next || next === turn.text || !transport.editMessage) return;
    setSaving(true);
    try {
      await transport.editMessage(turn.id, next);
      setEditing(false);
    } catch {
      toast.error("Couldn't save your edit. Try again.");
    } finally {
      setSaving(false);
    }
  };

  const startEditing = () => {
    setDraft(turn.text);
    setEditing(true);
  };

  if (editing) {
    return (
      <Message className={className} from="user">
        <form
          className="flex w-full flex-col gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            void save();
          }}
        >
          <Textarea
            aria-label="Edit your message"
            autoFocus
            disabled={saving}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Escape") setEditing(false);
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                void save();
              }
            }}
            value={draft}
          />
          <div className="flex justify-end gap-2">
            <Button disabled={saving} onClick={() => setEditing(false)} type="button" variant="ghost">
              Cancel
            </Button>
            <Button disabled={!draft.trim() || draft.trim() === turn.text} loading={saving} type="submit">
              Save and resend
            </Button>
          </div>
        </form>
      </Message>
    );
  }

  return (
    <Message className={className} from="user">
      {images.length ? (
        <Attachments variant="grid">
          {images.map((a) => (
            <Attachment data={toData(a)} key={a.id}>
              <AttachmentPreview />
            </Attachment>
          ))}
        </Attachments>
      ) : null}
      {files.length ? (
        <Attachments className="ml-auto w-fit justify-end" variant="inline">
          {files.map((a) => (
            <Attachment className="cursor-default" data={toData(a)} key={a.id}>
              <AttachmentPreview />
              <AttachmentInfo />
            </Attachment>
          ))}
        </Attachments>
      ) : null}
      <MessageBranch
        defaultBranch={active}
        key={`${turn.id}:${versions.length}`}
        onBranchChange={(i) => transport.selectBranch?.(turn.id, i)}
      >
        <MessageBranchContent>
          {versions.map((v, i) => (
            <MessageContent key={v.id}>{i === active || !canNavigate ? turn.text : v.text}</MessageContent>
          ))}
        </MessageBranchContent>
        {/* A user message's row sits under its bubble, at the end — the selector renders nothing for a single version. */}
        <MessageToolbar className={cn("mt-0 justify-end", ACTION_ROW)}>
          {canNavigate ? (
            <MessageBranchSelector>
              <MessageBranchPrevious />
              <MessageBranchPage />
              <MessageBranchNext />
            </MessageBranchSelector>
          ) : (
            <span />
          )}
          <MessageActions>
            <MessageAction label="Copy message" onClick={() => void copy()} tooltip="Copy">
              <CopyGlyph copied={copied} />
            </MessageAction>
            {canEdit ? (
              <MessageAction label="Edit message" onClick={startEditing} tooltip="Edit">
                <Icon icon={PencilIcon} size="sm" tone="inherit" aria-hidden />
              </MessageAction>
            ) : null}
          </MessageActions>
        </MessageToolbar>
      </MessageBranch>
    </Message>
  );
}

/* ── Steps: Tool, Confirmation, the code gate ────────────────────────────── */

function ApprovalCode({
  turn,
  transport,
}: {
  turn: ActionTurn;
  transport: AgentTransport;
}) {
  const [code, setCode] = React.useState("");
  const [error, setError] = React.useState<string | null>(null);
  const [checking, setChecking] = React.useState(false);
  const input = React.useRef<HTMLInputElement>(null);
  const entry = transport.pendingApprovals.find((p) => p.turnId === turn.id);
  const errorId = `${turn.id}-code-error`;

  const submit = async () => {
    if (!code.trim() || !transport.approveWithCode) return;
    setChecking(true);
    try {
      const result = await transport.approveWithCode(code.trim());
      if (result === false) {
        setError("That code isn't right. Check it and try again.");
        setCode("");
        input.current?.focus();
      } else {
        setError(null);
      }
    } catch {
      setError("Couldn't check the code. Try again.");
    } finally {
      setChecking(false);
    }
  };

  return (
    <ConfirmationActions className="w-full self-stretch">
      <form
        className="flex w-full flex-wrap items-start justify-end gap-2"
        onSubmit={(e) => {
          e.preventDefault();
          void submit();
        }}
      >
        <Field className="min-w-48 flex-1">
          <Input
            aria-describedby={error ? errorId : undefined}
            aria-invalid={error ? true : undefined}
            aria-label="Approval code"
            autoComplete="one-time-code"
            disabled={checking}
            onChange={(e) => {
              setCode(e.target.value);
              if (error) setError(null);
            }}
            placeholder="Approval code"
            ref={input}
            value={code}
          />
          <FieldError id={errorId}>{error}</FieldError>
        </Field>
        <ConfirmationAction disabled={!entry || checking} onClick={() => entry?.reject()} size="default" variant="outline">
          Reject
        </ConfirmationAction>
        <ConfirmationAction
          disabled={!transport.approveWithCode || !code.trim()}
          loading={checking}
          size="default"
          type="submit"
        >
          Approve
        </ConfirmationAction>
      </form>
    </ConfirmationActions>
  );
}

function ActionConfirmation({ turn, transport }: { turn: ActionTurn; transport: AgentTransport }) {
  const approval = toolApproval(turn);
  const state = toolState(turn);
  const entry = transport.pendingApprovals.find((p) => p.turnId === turn.id);
  const high = turn.params.risk === "high";

  return (
    <Confirmation
      approval={approval}
      className={state === "approval-requested" ? undefined : RECORD_CONFIRMATION}
      state={state}
    >
      <ConfirmationTitle>
        <ConfirmationRequest>
          {high
            ? `This is a high-risk action: ${humanise(turn.action)}. Enter your approval code to continue.`
            : `Allow the agent to ${humanise(turn.action)}?`}
        </ConfirmationRequest>
        <ConfirmationAccepted>
          <span className="inline-flex items-center gap-2">
            <Icon icon={CheckIcon} size="md" tone="success" />
            <span>Approved</span>
          </span>
        </ConfirmationAccepted>
        <ConfirmationRejected>
          <span className="inline-flex items-center gap-2">
            <Icon icon={XIcon} size="md" tone="error" />
            <span>{approval?.reason ? `Rejected: ${approval.reason}` : "Rejected"}</span>
          </span>
        </ConfirmationRejected>
      </ConfirmationTitle>
      {high ? (
        <ApprovalCode transport={transport} turn={turn} />
      ) : (
        <ConfirmationActions>
          <ConfirmationAction disabled={!entry} onClick={() => entry?.reject()} size="default" variant="outline">
            Reject
          </ConfirmationAction>
          <ConfirmationAction disabled={!entry} onClick={() => entry?.approve()} size="default">
            Approve
          </ConfirmationAction>
        </ConfirmationActions>
      )}
    </Confirmation>
  );
}

function ToolStepCard({
  turn,
  output,
  transport,
  onRetry,
}: {
  turn: ToolTurn | ActionTurn;
  output: OutputData | null;
  transport: AgentTransport;
  onRetry?: () => void;
}) {
  const state = toolState(turn);
  const [open, setOpen] = useDisclosure(state === "approval-requested" || state === "output-error" || state === "output-denied");
  const isTool = turn.kind === "tool";
  const name = isTool ? turn.name : turn.action;
  const params = turn.params;
  /* Only a stack trace draws the failure itself (message and Retry), so only
     then does the step keep quiet — every other failed tool says what went
     wrong, and offers "Try again", in its own step. */
  const drawnBelow = output !== null && output.kind !== "search" && output.kind !== "image";
  const owned = output?.kind === "stack-trace";
  const failed = state === "output-error" && !owned;
  const attempt = isTool && turn.attempt > 1 ? turn.attempt : 0;
  const rawResult = isTool && !drawnBelow ? turn.result : undefined;

  return (
    <Tool className="mb-0" onOpenChange={setOpen} open={open}>
      <ToolHeader
        state={state}
        title={attempt ? `${name} · attempt ${attempt}` : undefined}
        toolName={name}
        type="dynamic-tool"
      />
      <ToolContent>
        {Object.keys(params).length ? <ToolInput input={params} /> : null}
        {turn.kind === "action" ? <ActionConfirmation transport={transport} turn={turn} /> : null}
        <ToolResult
          errorText={failed ? turn.error : undefined}
          output={rawResult as React.ComponentProps<typeof ToolResult>["output"]}
        />
        {failed && onRetry ? (
          <Button onClick={onRetry} variant="outline">
            <Icon icon={RotateCcwIcon} size="md" tone="inherit" />
            Try again
          </Button>
        ) : null}
      </ToolContent>
    </Tool>
  );
}

/* ── The reply ───────────────────────────────────────────────────────────── */

export type WorkspaceReplyProps = {
  /** The user message this reply answers (Open in…, Retry). */
  user: UserTurn;
  /** The reply, or null while the user turn has none yet (the waiting shell). */
  reply: Reply | null;
  transport: AgentTransport;
  /** The agent is working. */
  busy: boolean;
  /** The last reply in the thread — Suggestions, Retry and Reconnecting belong to it. */
  isLast: boolean;
  /** The run this reply started, when it is the run's owner — drawn with `RunInline`. */
  run?: Run | null;
  speak?: (text: string) => Promise<string>;
  /** Chat services the "Open in…" menu offers, each opened with the user message as the query. Empty or absent renders no menu. */
  openIn?: OpenInTarget[];
  onSend: (text: string) => void;
  /** Hides follow-up Suggestions once the user starts typing. Defaults to true. */
  composerEmpty?: boolean;
  className?: string;
};

/** The same transient status words everywhere a reply is waiting. */
function ReplyStatus({ children }: { children: string }) {
  return (
    <div role="status">
      <Shimmer as="span">{children}</Shimmer>
    </div>
  );
}

export function WorkspaceReply({
  user,
  reply,
  transport,
  busy,
  isLast,
  run,
  speak,
  openIn,
  onSend,
  composerEmpty = true,
  className,
}: WorkspaceReplyProps) {
  const turns = React.useMemo(() => reply?.turns ?? [], [reply]);
  const streaming = reply ? reply.streaming : busy && isLast;
  const connection = transport.runState?.connection ?? "connected";
  const reconnecting = isLast && connection !== "connected";

  const textTurns = turns.filter((t): t is TextTurn => t.kind === "text");
  const stepTurns = turns.filter((t): t is ToolTurn | ActionTurn => t.kind === "tool" || t.kind === "action");
  const errorTurns = turns.flatMap((t) => (t.kind === "error" ? [t] : []));
  // A fatal error owns the reply's one Retry; the failed step it came from does not repeat it.
  const fatalError = errorTurns.some((e) => e.fatal);
  const reasoningSteps = textTurns.flatMap((t) => t.reasoning?.steps ?? []);
  const reasoningMs = textTurns.reduce<number | undefined>(
    (sum, t) => (t.reasoning?.ms === undefined ? sum : (sum ?? 0) + t.reasoning.ms),
    undefined,
  );
  const sources = reply?.sources ?? [];

  /* `regenerate` takes the answer to write again — the reply's last text
     turn — falling back to the question when there is no answer yet. */
  const answerId = [...turns].reverse().find((t) => t.kind === "text")?.id ?? user.id;
  const retry = React.useCallback(() => {
    if (transport.regenerate && transport.capabilities.branching) void transport.regenerate(answerId);
    else onSend(user.text);
  }, [transport, answerId, user.text, onSend]);
  const canRetry = isLast && !busy;

  /* Which tool calls get a component of their own below the answer. */
  const outputs = stepTurns.flatMap((t) => {
    if (t.kind !== "tool") return [];
    const data = toolOutput(t);
    return data && data.kind !== "search" && data.kind !== "image" ? [{ turn: t, data }] : [];
  });
  /* An image a tool is making appears in a GeneratedImage, from its first stage
     to the finished picture; whatever else a tool hands back is a produced file. */
  const frames = stepTurns.flatMap((t) => {
    if (t.kind !== "tool") return [];
    const data = toolOutput(t);
    const image = (t.attachments ?? []).find((a) => a.kind === "image");
    if (data?.kind !== "image" && !image) return [];
    const stage: ImageStage =
      data?.kind === "image" ? data.stage
      : t.status === "error" ? "error"
      : t.status === "running" ? "generating"
      : "complete";
    return [{ turn: t, image, stage }];
  });
  const images = stepTurns.flatMap((t) =>
    t.kind === "tool" ? (t.attachments ?? []).filter((a) => !frames.some((f) => f.image === a)) : [],
  );

  const hasSteps = stepTurns.length > 0;
  const hasText = textTurns.some((t) => t.text.trim());
  const thinkingOnly = !hasSteps && reasoningSteps.length > 0;
  const stepCount = reasoningSteps.length + stepTurns.length;
  const needsYou = stepTurns.some((t) => t.kind === "action" && t.approval === "pending");
  const stepRunning = stepTurns.some((t) => t.status === "running");
  const working = streaming && (stepRunning || !hasText);
  /* Open while the reply is being written or a step is waiting on the reader,
     closed again once it is done — unless the reader opened it. */
  const [chainChoice, setChainChoice] = React.useState<boolean | null>(null);
  const anyStepFailed = stepTurns.some((t) => toolState(t) === "output-error");
  const chainOpen = chainChoice ?? (streaming || needsYou || anyStepFailed);

  /* The text turn whose regenerations the reader can page through. An edit
     gives the question a new version AND its answer a new one; the question's
     own ‹ n of m › already pages that pair, so the answer shows a selector
     only once it has more versions than the question (a real Regenerate). */
  const editVersions = user.versions?.length ?? 0;
  const branchTurn = [...textTurns]
    .reverse()
    .find((t) => (t.regenerations?.length ?? 0) > 1 && (t.regenerations?.length ?? 0) > editVersions);
  const canNavigate = Boolean(transport.capabilities.branching && transport.selectBranch);
  const branchVersions = canNavigate && branchTurn ? (branchTurn.regenerations ?? []) : [];
  const branchActive = branchTurn ? Math.min(branchTurn.activeVersion ?? 0, Math.max(branchVersions.length - 1, 0)) : 0;

  // A reply whose run is still going (paused, waiting on the reader) is not finished either.
  const finished = Boolean(reply) && !streaming && !(run && RUN_IN_FLIGHT.has(run.status));
  const copy = useCopy(reply?.text ?? "");
  const readAloud = useReadAloud(reply?.text ?? "", speak);
  const player = usePresence(Boolean(readAloud?.open));

  const lastText = textTurns.at(-1);
  const suggestions = isLast && finished && composerEmpty ? (lastText?.suggestions ?? []) : [];

  // A run drawn in this reply already says what is happening — no "Thinking…" above it.
  const waiting = streaming && !hasText && !hasSteps && !thinkingOnly && !errorTurns.length && !run;

  if (!reply && !waiting && !run && !reconnecting) return null;

  const showError = isLast && !errorTurns.length && transport.error && !busy;

  return (
    <div className={cn("flex flex-col gap-4", className)}>
      <Message className="max-w-full" from="assistant">
        <MessageBranch
          className="gap-4"
          defaultBranch={branchActive}
          key={`${branchTurn?.id ?? "single"}:${branchVersions.length}`}
          onBranchChange={(i) => branchTurn && transport.selectBranch?.(branchTurn.id, i)}
        >
          {thinkingOnly ? (
            <Reasoning
              className="mb-0"
              duration={streaming && !hasText ? undefined : reasoningMs === undefined ? undefined : Math.ceil(reasoningMs / 1000)}
              isStreaming={streaming && !hasText}
            >
              <ReasoningTrigger />
              <ReasoningContent>{reasoningSteps.join("\n\n")}</ReasoningContent>
            </Reasoning>
          ) : null}

          {hasSteps ? (
            <ChainOfThought onOpenChange={setChainChoice} open={chainOpen}>
              <ChainOfThoughtHeader>
                {working ? <Shimmer as="span">Working…</Shimmer> : `Worked through ${stepCount} ${stepCount === 1 ? "step" : "steps"}`}
              </ChainOfThoughtHeader>
              <ChainOfThoughtContent>
                {reasoningSteps.map((step, i) => (
                  <ChainOfThoughtStep key={`r${i}`} label={step} status="complete" />
                ))}
                {stepTurns.map((t) => {
                  const data = t.kind === "tool" ? toolOutput(t) : null;
                  const status = stepChainStatus(t.status === "running" ? "running" : "done");
                  if (t.kind === "tool" && data?.kind === "search" && t.status !== "error") {
                    return (
                      <ChainOfThoughtStep
                        icon={SearchIcon}
                        key={t.id}
                        label={`${t.status === "running" ? "Searching for" : "Searched for"} “${data.query}”`}
                        status={status}
                      >
                        <ChainOfThoughtSearchResults>
                          {data.results.map((r) => (
                            <ChainOfThoughtSearchResult asChild key={r.url}>
                              <a href={r.url} rel="noreferrer noopener" target="_blank" title={r.title}>
                                {r.domain}
                              </a>
                            </ChainOfThoughtSearchResult>
                          ))}
                        </ChainOfThoughtSearchResults>
                      </ChainOfThoughtStep>
                    );
                  }
                  return (
                    <ChainOfThoughtStep
                      key={t.id}
                      label={
                        <ToolStepCard
                          onRetry={canRetry && !fatalError ? retry : undefined}
                          output={data}
                          transport={transport}
                          turn={t}
                        />
                      }
                      status={status}
                    />
                  );
                })}
              </ChainOfThoughtContent>
            </ChainOfThought>
          ) : null}

          {waiting && !reconnecting ? <ReplyStatus>Thinking…</ReplyStatus> : null}

          {textTurns.map((t) => {
            if (!t.text.trim()) return null;
            if (t === branchTurn && branchVersions.length) {
              return (
                <MessageBranchContent key={t.id}>
                  {branchVersions.map((v, i) => (
                    <Response
                      key={v.id}
                      sources={sources}
                      text={i === branchActive ? t.text : v.text}
                      turn={t}
                    />
                  ))}
                </MessageBranchContent>
              );
            }
            return <Response key={t.id} sources={sources} text={t.text} turn={t} />;
          })}

          {outputs.map(({ turn, data }) => (
            <ToolOutputView
              key={turn.id}
              onRetry={canRetry ? retry : undefined}
              output={data}
              running={turn.status === "running"}
              state={toolState(turn)}
            />
          ))}

          {frames.map(({ turn, image, stage }) => (
            <GeneratedImage key={turn.id} stage={stage} onRetry={canRetry ? retry : undefined} className="max-w-sm">
              {image?.url ? (
                // A data: or blob: url the workspace already holds — next/image has nothing to optimise.
                // eslint-disable-next-line @next/next/no-img-element
                <img src={image.url} alt={image.name} />
              ) : null}
            </GeneratedImage>
          ))}

          {images.length ? <ProducedFiles attachments={images} /> : null}
          {textTurns.some((t) => t.attachments?.length) ? (
            <ProducedFiles attachments={textTurns.flatMap((t) => t.attachments ?? [])} />
          ) : null}

          {errorTurns.map((e) => (
            <Alert key={e.id} variant="destructive">
              <Icon icon={AlertCircleIcon} size="md" tone="inherit" />
              <AlertTitle>{e.fatal ? "Something went wrong" : "That step didn't finish"}</AlertTitle>
              <AlertDescription>
                <p>{e.message}</p>
                {e.fatal && canRetry ? (
                  <Button className="mt-3" onClick={retry} variant="outline">
                    <Icon icon={RotateCcwIcon} size="md" tone="inherit" />
                    Retry
                  </Button>
                ) : null}
              </AlertDescription>
            </Alert>
          ))}
          {showError ? (
            <Alert variant="destructive">
              <Icon icon={AlertCircleIcon} size="md" tone="inherit" />
              <AlertTitle>Something went wrong</AlertTitle>
              <AlertDescription>
                <p>{transport.error?.message}</p>
                <Button className="mt-3" onClick={retry} variant="outline">
                  <Icon icon={RotateCcwIcon} size="md" tone="inherit" />
                  Retry
                </Button>
              </AlertDescription>
            </Alert>
          ) : null}

          {reconnecting ? <ReplyStatus>Reconnecting…</ReplyStatus> : null}

          {run ? <RunInline run={run} transport={transport} /> : null}

          {sources.length ? (
            <Sources className="mb-0">
              <SourcesTrigger count={sources.length} />
              <SourcesContent>
                {sources.map((s) => (
                  <Source href={s.url} key={s.id} title={s.title} />
                ))}
              </SourcesContent>
            </Sources>
          ) : null}

          {finished ? (
            <MessageToolbar className={cn("mt-0", ACTION_ROW)}>
              {canNavigate && branchVersions.length > 1 ? (
                <MessageBranchSelector>
                  <MessageBranchPrevious />
                  <MessageBranchPage />
                  <MessageBranchNext />
                </MessageBranchSelector>
              ) : (
                <span />
              )}
              <MessageActions>
                <MessageAction label="Copy reply" onClick={() => void copy.copy()} tooltip="Copy">
                  <CopyGlyph copied={copy.copied} />
                </MessageAction>
                {transport.regenerate && transport.capabilities.branching ? (
                  <MessageAction
                    label="Regenerate"
                    onClick={() => void transport.regenerate?.(answerId)}
                    tooltip="Regenerate"
                  >
                    <Icon icon={RefreshCwIcon} size="sm" tone="inherit" aria-hidden />
                  </MessageAction>
                ) : null}
                {readAloud ? (
                  <MessageAction
                    label={readAloud.open ? "Stop reading aloud" : readAloud.loading ? "Preparing audio" : "Read aloud"}
                    loading={readAloud.loading}
                    onClick={readAloud.toggle}
                    tooltip={readAloud.open ? "Stop" : "Read aloud"}
                  >
                    <ReadAloudGlyph active={readAloud.open} />
                  </MessageAction>
                ) : null}
                {openIn && openIn.length > 0 ? (
                  <OpenIn query={user.text}>
                    <OpenInTrigger>
                      <MessageAction label="Open in…" tooltip="Open in…">
                        <Icon icon={ExternalLinkIcon} size="sm" tone="inherit" aria-hidden />
                      </MessageAction>
                    </OpenInTrigger>
                    <OpenInContent>
                      <OpenInLabel>Open in</OpenInLabel>
                      {openIn.map((t) => (
                        <OpenInLink key={t.id} target={t} />
                      ))}
                    </OpenInContent>
                  </OpenIn>
                ) : null}
              </MessageActions>
            </MessageToolbar>
          ) : null}

          {player.mounted && readAloud?.url ? (
            <div className={cn("rounded-lg border bg-card p-2", player.className)}>
              <AudioPlayer>
                <AudioPlayerElement autoPlay src={readAloud.url} />
                <AudioPlayerControlBar>
                  <AudioPlayerPlayButton />
                  <AudioPlayerTimeDisplay />
                  <AudioPlayerTimeRange />
                  <AudioPlayerDurationDisplay />
                  <AudioPlayerMuteButton />
                </AudioPlayerControlBar>
              </AudioPlayer>
            </div>
          ) : null}
        </MessageBranch>
      </Message>

      {suggestions.length ? (
        <Suggestions>
          {suggestions.map((s) => (
            <Suggestion key={s} onClick={onSend} suggestion={s} />
          ))}
        </Suggestions>
      ) : null}
    </div>
  );
}

"use client";

/**
 * WorkspaceSettings — the settings `Sheet` content for `AgentWorkspace`.
 *
 *   Autonomy      ask / plan first / act — chosen here now (it used to sit in the
 *                 prompt bar's toolbar; the composer is an AI Elements
 *                 `PromptInput` and carries no mode control)
 *   Response      length and temperature
 *   Voice         the read-aloud voice, chosen in AI Elements' `VoiceSelector`
 *   About         the connected agent in AI Elements' `Agent` — only when the
 *                 transport describes one (`transport.agent`)
 *
 * Every setting is an explicit value / onChange pair, lifted into
 * `AgentWorkspace` so it can also build `SendOptions.settings` from them
 * (`{ autonomy, temperature, length }`, sent only when
 * `transport.capabilities.settings` is true). The voice is not part of
 * `SendOptions` — it is how replies are READ, not how they are written — and
 * `voices` is whatever the speech adapter reports (`useBrowserSpeech().voices`),
 * so the picker lists the real voices of this machine, never an invented
 * catalogue (and so has no preview audio: the browser gives none).
 *
 * The two sliders: "Response length" is `settings.length` (0-100, a verbosity
 * dial); "Temperature" is `settings.temperature` (0-2, step 0.1, default 0.7).
 */

import * as React from "react";
import { ListChecksIcon, MessageCircleIcon, ZapIcon } from "lucide-react";
import type { Tool } from "ai";

import {
  Agent,
  AgentContent,
  AgentHeader,
  AgentInstructions,
  AgentOutput,
  AgentTool,
  AgentTools,
} from "@/components/ai-elements/agent";
import {
  VoiceSelector,
  VoiceSelectorContent,
  VoiceSelectorDescription,
  VoiceSelectorEmpty,
  VoiceSelectorInput,
  VoiceSelectorItem,
  VoiceSelectorList,
  VoiceSelectorName,
  VoiceSelectorTrigger,
} from "@/components/ai-elements/voice-selector";
import type { AgentProfile } from "@/components/agent/core/types";
import type { SpeechVoice } from "@/components/agent/voice/speech";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio";
import { Slider } from "@/components/ui/slider";
import {
  SheetBody,
  SheetClose,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";

export type AutonomyMode = "ask" | "plan" | "act";

const AUTONOMY_LABEL: Record<AutonomyMode, string> = {
  ask: "Ask",
  plan: "Plan first",
  act: "Act",
};

const AUTONOMY_DETAIL: Record<AutonomyMode, { description: string; icon: typeof ZapIcon }> = {
  ask: { description: "Answers, never acts", icon: MessageCircleIcon },
  plan: { description: "Proposes a plan to approve", icon: ListChecksIcon },
  act: { description: "Acts, asking only when it must", icon: ZapIcon },
};

const AUTONOMY_MODES: AutonomyMode[] = ["ask", "plan", "act"];

/** The defaults `AgentWorkspace` itself initialises these to — "Reset to defaults" restores exactly these. */
export const DEFAULT_RESPONSE_LENGTH = 50;
export const DEFAULT_TEMPERATURE = 0.7;

/**
 * Both sliders read as a raw number beside a word — a bare 0-100 or 0-2 figure
 * means nothing to someone who has never seen the scale. Three bands each.
 */
function lengthLabel(value: number): string {
  if (value <= 33) return "Short";
  if (value <= 66) return "Medium";
  return "Long";
}

function temperatureLabel(value: number): string {
  if (value <= 0.66) return "Precise";
  if (value <= 1.33) return "Balanced";
  return "Creative";
}

export type WorkspaceSettingsProps = {
  /** Forwarded as `SendOptions.settings.autonomy`. */
  autonomy: AutonomyMode;
  onAutonomyChange: (autonomy: AutonomyMode) => void;
  /** 0-100 — forwarded as `SendOptions.settings.length`. */
  length: number;
  onLengthChange: (length: number) => void;
  /** 0-2, step 0.1 — forwarded as `SendOptions.settings.temperature`. */
  temperature: number;
  onTemperatureChange: (temperature: number) => void;
  /** The read-aloud voice's id, or null for the system default. */
  voice?: string | null;
  onVoiceChange?: (id: string) => void;
  /** The voices the speech adapter offers. The Voice section renders only when there are some. */
  voices?: SpeechVoice[];
  /** What the connected agent is — the "About this agent" section renders only when present. */
  agent?: AgentProfile;
  /** Restores autonomy, length and temperature to their defaults. */
  onReset?: () => void;
  /** True while the transport is not ready to receive a message yet. */
  disabled?: boolean;
  className?: string;
};

function Section({ id, title, children }: { id: string; title: string; children: React.ReactNode }) {
  return (
    <section aria-labelledby={id} className="space-y-3">
      <h3 id={id} className="type-h4 text-foreground">
        {title}
      </h3>
      {children}
    </section>
  );
}

function AutonomySection({
  autonomy,
  onAutonomyChange,
  disabled,
}: Pick<WorkspaceSettingsProps, "autonomy" | "onAutonomyChange" | "disabled">) {
  return (
    <Section id="workspace-autonomy-title" title="Autonomy">
      <RadioGroup
        aria-labelledby="workspace-autonomy-title"
        value={autonomy}
        onValueChange={(value) => onAutonomyChange(value as AutonomyMode)}
        disabled={disabled}
        className="gap-1"
      >
        {AUTONOMY_MODES.map((mode) => {
          const detail = AUTONOMY_DETAIL[mode];
          return (
            <label
              key={mode}
              htmlFor={`workspace-autonomy-${mode}`}
              className="flex min-h-(--size-target-min) cursor-pointer items-center gap-3 rounded-md px-2 py-2 hover:bg-secondary has-disabled:cursor-not-allowed"
            >
              <RadioGroupItem id={`workspace-autonomy-${mode}`} value={mode} />
              <Icon icon={detail.icon} size="md" tone="muted" aria-hidden />
              <span className="flex min-w-0 flex-col">
                <span className="type-small text-foreground">{AUTONOMY_LABEL[mode]}</span>
                <span className="type-small text-muted-foreground">{detail.description}</span>
              </span>
            </label>
          );
        })}
      </RadioGroup>
    </Section>
  );
}

function VoiceSection({
  voice,
  voices,
  onVoiceChange,
  disabled,
}: {
  voice?: string | null;
  voices: SpeechVoice[];
  onVoiceChange?: (id: string) => void;
  disabled?: boolean;
}) {
  const [open, setOpen] = React.useState(false);
  const selected = voices.find((v) => v.id === voice);
  return (
    <Section id="workspace-voice-title" title="Voice">
      <p className="type-small text-muted-foreground">The voice that reads answers aloud.</p>
      <VoiceSelector open={open} onOpenChange={setOpen} value={voice ?? undefined}>
        <VoiceSelectorTrigger asChild>
          <Button
            type="button"
            variant="outline"
            className="w-full justify-start"
            disabled={disabled}
            aria-label={`Read-aloud voice: ${selected?.label ?? "System default"}`}
          >
            <span className="min-w-0 flex-1 truncate text-left">{selected?.label ?? "System default"}</span>
          </Button>
        </VoiceSelectorTrigger>
        <VoiceSelectorContent title="Read-aloud voice">
          <VoiceSelectorInput placeholder="Search voices..." />
          <VoiceSelectorList>
            <VoiceSelectorEmpty>No voices found.</VoiceSelectorEmpty>
            {voices.map((v) => (
              <VoiceSelectorItem
                key={v.id}
                value={`${v.label} ${v.lang} ${v.id}`}
                onSelect={() => {
                  onVoiceChange?.(v.id);
                  setOpen(false);
                }}
              >
                <VoiceSelectorName>{v.label}</VoiceSelectorName>
                <VoiceSelectorDescription>
                  {v.lang} · {v.local ? "On this device" : "Online"}
                </VoiceSelectorDescription>
              </VoiceSelectorItem>
            ))}
          </VoiceSelectorList>
        </VoiceSelectorContent>
      </VoiceSelector>
    </Section>
  );
}

function AboutSection({ agent }: { agent: AgentProfile }) {
  return (
    <Section id="workspace-about-title" title="About this agent">
      <Agent>
        <AgentHeader name={agent.name} model={agent.model} />
        {agent.instructions || agent.tools?.length || agent.outputSchema ? (
          <AgentContent>
            {agent.instructions ? <AgentInstructions>{agent.instructions}</AgentInstructions> : null}
            {agent.tools?.length ? (
              <AgentTools type="multiple">
                {agent.tools.map((tool) => (
                  <AgentTool
                    key={tool.name}
                    value={tool.name}
                    tool={{ description: tool.description, inputSchema: tool.schema ?? {} } as unknown as Tool}
                  />
                ))}
              </AgentTools>
            ) : null}
            {agent.outputSchema ? <AgentOutput schema={agent.outputSchema} /> : null}
          </AgentContent>
        ) : null}
      </Agent>
    </Section>
  );
}

export function WorkspaceSettings({
  autonomy,
  onAutonomyChange,
  length,
  onLengthChange,
  temperature,
  onTemperatureChange,
  voice,
  onVoiceChange,
  voices,
  agent,
  onReset,
  disabled,
  className,
}: WorkspaceSettingsProps) {
  return (
    <div className={cn("flex h-full min-h-0 flex-col", className)}>
      <SheetHeader>
        <SheetTitle>Workspace settings</SheetTitle>
        <SheetDescription>Autonomy, length and temperature are sent with every message.</SheetDescription>
      </SheetHeader>

      <SheetBody className="space-y-8">
        <AutonomySection autonomy={autonomy} onAutonomyChange={onAutonomyChange} disabled={disabled} />

        <Section id="workspace-response-title" title="Response">
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label htmlFor="workspace-length" className="type-small text-foreground">
                Response length
              </label>
              <span className="anim-change type-small text-foreground" key={lengthLabel(length)}>
                {lengthLabel(length)}
              </span>
            </div>
            <Slider
              id="workspace-length"
              value={[length]}
              onValueChange={(value) => onLengthChange(value[0])}
              min={0}
              max={100}
              step={50}
              disabled={disabled}
              thumbLabels={["Response length"]}
            />
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label htmlFor="workspace-temperature" className="type-small text-foreground">
                Temperature
              </label>
              <span className="flex items-baseline gap-1.5">
                <span className="anim-change type-small text-foreground" key={temperatureLabel(temperature)}>
                  {temperatureLabel(temperature)}
                </span>
                <span className="type-number-sm text-muted-foreground">{temperature.toFixed(1)}</span>
              </span>
            </div>
            <Slider
              id="workspace-temperature"
              value={[temperature]}
              onValueChange={(value) => onTemperatureChange(value[0])}
              min={0}
              max={2}
              step={0.1}
              disabled={disabled}
              thumbLabels={["Temperature"]}
            />
          </div>
        </Section>

        {voices?.length ? (
          <VoiceSection voice={voice} voices={voices} onVoiceChange={onVoiceChange} disabled={disabled} />
        ) : null}

        {agent ? <AboutSection agent={agent} /> : null}
      </SheetBody>

      <SheetFooter className="flex-row justify-between">
        {onReset ? (
          <Button type="button" variant="ghost" onClick={onReset}>
            Reset to defaults
          </Button>
        ) : null}
        <SheetClose asChild>
          <Button type="button" variant="outline">
            Close
          </Button>
        </SheetClose>
      </SheetFooter>
    </div>
  );
}

"use client";

/**
 * WorkspaceThread — the conversation, built from AI Elements.
 *
 * `Conversation` sticks to the bottom and offers the scroll-to-latest button;
 * each user turn and the reply that answers it is one pair
 * (`groupReplies`), drawn by `WorkspaceUserMessage` and `WorkspaceReply`.
 * Between turns the `Checkpoint`s the transport and the run recorded are drawn
 * where they were taken. An empty conversation is a greeting and the starter
 * prompts as `Suggestion`s.
 *
 * There is no status row, run bar or activity panel: the reply itself shows
 * what is happening — a Shimmer, Reasoning, ChainOfThought, a Tool's state,
 * `RunInline`.
 */

import * as React from "react";
import { toast } from "sonner";

import { TooltipProvider } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import {
  Checkpoint,
  CheckpointIcon,
  CheckpointTrigger,
} from "@/components/ai-elements/checkpoint";
import {
  Conversation,
  ConversationContent,
  ConversationEmptyState,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation";
import type { OpenInTarget } from "@/components/ai-elements/open-in-chat";
import { Suggestion, Suggestions } from "@/components/ai-elements/suggestion";

import type { Checkpoint as CheckpointData } from "@/components/agent/core/run";
import type { AgentTransport } from "@/components/agent/core/types";

import { checkpointsByTurn, groupReplies, runOwner } from "./reply-model";
import { WorkspaceReply, WorkspaceUserMessage } from "./workspace-reply";

export type WorkspaceThreadProps = {
  transport: AgentTransport;
  /** resolveState-derived: the agent is working (thinking, streaming, running a tool or run). */
  busy: boolean;
  /** Starter prompts for the empty conversation (Suggestions under the greeting). */
  starters?: string[];
  /** Send a prompt — used by starters, follow-up Suggestions and Retry. */
  onSend: (text: string) => void;
  /** Read aloud: resolves to a playable audio url for `text` (the controller binds the chosen voice). Absent → no Read aloud action. */
  speak?: (text: string) => Promise<string>;
  /** Chat services offered by each reply's "Open in…" menu. Absent or empty → no menu. */
  openIn?: OpenInTarget[];
  /** Hides follow-up Suggestions once the user starts typing (Claude behaviour). */
  composerEmpty?: boolean;
  className?: string;
};

type Restore = { label: string; tooltip: string; onRestore: () => void };

/** The marker between two turns: a bookmark, the checkpoint's label, one click to go back. */
function TurnCheckpoints({ restores }: { restores: (Restore & { id: string })[] }) {
  return restores.map((r) => (
    <Checkpoint key={r.id}>
      <CheckpointIcon />
      <CheckpointTrigger aria-label={`Restore to ${r.label}`} onClick={r.onRestore} tooltip={r.tooltip}>
        {r.label}
      </CheckpointTrigger>
    </Checkpoint>
  ));
}

export function WorkspaceThread({
  transport,
  busy,
  starters,
  onSend,
  speak,
  openIn,
  composerEmpty = true,
  className,
}: WorkspaceThreadProps) {
  const pairs = React.useMemo(() => groupReplies(transport.turns, busy), [transport.turns, busy]);
  const run = transport.runState?.run ?? null;
  const owner = run ? runOwner(pairs, run.startedAt) : null;

  const chatPoints = React.useMemo(() => checkpointsByTurn(transport.restorePoints ?? []), [transport.restorePoints]);
  const runPoints = React.useMemo(() => checkpointsByTurn(run?.checkpoints ?? []), [run?.checkpoints]);

  const { restoreTo, resume } = transport;
  const canRestoreChat = Boolean(restoreTo);
  const canRestoreRun = Boolean(resume && transport.capabilities.checkpoints);

  const restoresAfter = (turnIds: string[]) => {
    const out: (Restore & { id: string })[] = [];
    const chat = (cp: CheckpointData) => ({
      id: `chat-${cp.id}`,
      label: cp.label,
      tooltip: "Restores the conversation to this point",
      onRestore: () => {
        restoreTo?.(cp.turnId);
        toast.success(`Restored to “${cp.label}”`);
      },
    });
    const task = (cp: CheckpointData) => ({
      id: `run-${cp.id}`,
      label: cp.label,
      tooltip: "Resumes the run from this point",
      onRestore: () => {
        void Promise.resolve(resume?.(cp.id)).then(
          () => toast.success(`Resumed from “${cp.label}”`),
          () => toast.error("Couldn't resume from that checkpoint. Try again."),
        );
      },
    });
    for (const id of turnIds) {
      if (canRestoreChat) out.push(...(chatPoints.get(id) ?? []).map(chat));
      if (canRestoreRun) out.push(...(runPoints.get(id) ?? []).map(task));
    }
    return out;
  };

  return (
    <TooltipProvider>
      <Conversation aria-label="Conversation" className={cn("min-h-0", className)}>
        <ConversationContent className="mx-auto w-full max-w-3xl gap-10 p-4">
          {pairs.length === 0 ? (
            <ConversationEmptyState>
              <h2 className="type-h4">How can I help you today?</h2>
              {starters?.length ? (
                <Suggestions className="w-full flex-wrap justify-center">
                  {starters.map((s) => (
                    <Suggestion key={s} onClick={onSend} suggestion={s} />
                  ))}
                </Suggestions>
              ) : null}
            </ConversationEmptyState>
          ) : (
            pairs.map(({ user, reply }, i) => (
              <div className="flex flex-col gap-6" key={user.id}>
                <WorkspaceUserMessage transport={transport} turn={user} />
                <WorkspaceReply
                  busy={busy}
                  composerEmpty={composerEmpty}
                  isLast={i === pairs.length - 1}
                  onSend={onSend}
                  reply={reply}
                  openIn={openIn}
                  run={owner === user.id ? run : null}
                  speak={speak}
                  transport={transport}
                  user={user}
                />
                <TurnCheckpoints restores={restoresAfter([user.id, ...(reply?.turns.map((t) => t.id) ?? [])])} />
              </div>
            ))
          )}
        </ConversationContent>
        <ConversationScrollButton />
      </Conversation>
    </TooltipProvider>
  );
}

