export type TerminalCopyButtonProps = ComponentProps<typeof Button> & {
  onCopy?: () => void;
  onError?: (error: Error) => void;
  timeout?: number;
};

export const TerminalCopyButton = ({
  onCopy,
  onError,
  timeout = 2000,
  children,
  className,
  "aria-label": ariaLabel,
  ...props
}: TerminalCopyButtonProps) => {
  const [isCopied, setIsCopied] = useState(false);
  const timeoutRef = useRef<number>(0);
  const { output } = useContext(TerminalContext);

  const copyToClipboard = useCallback(async () => {
    if (typeof window === "undefined" || !navigator?.clipboard?.writeText) {
      onError?.(new Error("Clipboard API not available"));
      return;
    }

    try {
      await navigator.clipboard.writeText(output);
      setIsCopied(true);
      onCopy?.();
      timeoutRef.current = window.setTimeout(() => setIsCopied(false), timeout);
    } catch (error) {
      onError?.(error as Error);
    }
  }, [output, onCopy, onError, timeout]);

  useEffect(
    () => () => {
      window.clearTimeout(timeoutRef.current);
    },
    []
  );

  return (
    <Button
      aria-label={ariaLabel ?? (isCopied ? "Copied" : "Copy output")}
      className={cn("shrink-0", className)}
      onClick={copyToClipboard}
      size="icon-sm"
      variant="ghost"
      {...props}
    >
      {children ?? (
        <IconSwap
          active={isCopied ? "check" : "copy"}
          icons={{
            copy: <Icon icon={CopyIcon} size="sm" tone="inherit" />,
            check: <Icon icon={CheckIcon} size="sm" tone="success" />,
          }}
        />
      )}
    </Button>
  );
};

export type TerminalClearButtonProps = ComponentProps<typeof Button>;

export const TerminalClearButton = ({
  children,
  className,
  "aria-label": ariaLabel,
  ...props
}: TerminalClearButtonProps) => {
  const { onClear } = useContext(TerminalContext);

  if (!onClear) {
    return null;
  }

  return (
    <Button
      aria-label={ariaLabel ?? "Clear terminal"}
      className={cn("shrink-0", className)}
      onClick={onClear}
      size="icon-sm"
      variant="ghost"
      {...props}
    >
      {children ?? <Icon icon={Trash2Icon} size="sm" tone="inherit" />}
    </Button>
  );
};

export type TerminalContentProps = HTMLAttributes<HTMLDivElement>;

export const TerminalContent = ({
  className,
  children,
  ...props
}: TerminalContentProps) => {
  const { output, isStreaming, autoScroll } = useContext(TerminalContext);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (autoScroll && containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [output, autoScroll]);

  return (
    <div
      className={cn("terminal-ansi max-h-96 overflow-auto p-4", className)}
      ref={containerRef}
      {...props}
    >
      {children ?? (
        <pre className="type-code whitespace-pre-wrap break-words">
          {/* Vendored change: `useClasses` makes ansi-to-react emit
              `ansi-<colour>-fg|-bg` / `ansi-<decoration>` classes instead of
              inline rgb() styles, which ignore the theme (white output
              vanished in light mode). The token-based rules for those classes
              belong in styles/utilities.css. */}
          <Ansi useClasses>{output}</Ansi>
          {isStreaming && (
            /* The streaming cursor is the same idea as the OTP caret — a mark
               that says "input lands here" — so it plays the same named
               blink (`anim-caret`) rather than the vendored pulse utility,
               which both bypasses the motion scale (RULES §6's
               foreign-animation guard) and reads as a loading dim rather
               than a text-insertion caret. */
            <span className="anim-caret ml-0.5 inline-block h-4 w-2 bg-foreground" />
          )}
        </pre>
      )}
    </div>
  );
};

export type TerminalProps = HTMLAttributes<HTMLDivElement> & {
  output: string;
  isStreaming?: boolean;
  autoScroll?: boolean;
  onClear?: () => void;
};

export const Terminal = ({
  output,
  isStreaming = false,
  autoScroll = true,
  onClear,
  className,
  children,
  ...props
}: TerminalProps) => {
  const contextValue = useMemo(
    () => ({ autoScroll, isStreaming, onClear, output }),
    [autoScroll, isStreaming, onClear, output]
  );

  return (
    <TerminalContext.Provider value={contextValue}>
      <div
        className={cn(
          "flex flex-col overflow-hidden rounded-lg border bg-background text-foreground",
          className
        )}
        {...props}
      >
        {children ?? (
          <>
            <TerminalHeader>
              <TerminalTitle />
              <div className="flex items-center gap-1">
                <TerminalStatus />
                <TerminalActions>
                  <TerminalCopyButton />
                  {onClear && <TerminalClearButton />}
                </TerminalActions>
              </div>
            </TerminalHeader>
            <TerminalContent />
          </>
        )}
      </div>
    </TerminalContext.Provider>
  );
};

"use client";

import { Badge } from "@/components/ui/badge";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Icon, type IconTone } from "@/components/ui/icon";
import { cn } from "@/lib/utils";
import type { LucideIcon } from "lucide-react";
import {
  CheckCircle2Icon,
  ChevronRightIcon,
  LoaderCircleIcon,
  CircleIcon,
  XCircleIcon,
} from "lucide-react";
import type { ComponentProps, HTMLAttributes } from "react";
import { createContext, useContext, useMemo } from "react";

type TestStatus = "passed" | "failed" | "skipped" | "running";

interface TestResultsSummary {
  passed: number;
  failed: number;
  skipped: number;
  total: number;
  duration?: number;
}

interface TestResultsContextType {
  summary?: TestResultsSummary;
}

const TestResultsContext = createContext<TestResultsContextType>({});

const formatDuration = (ms: number) => {
  if (ms < 1000) {
    return `${ms}ms`;
  }
  return `${(ms / 1000).toFixed(2)}s`;
};

export type TestResultsHeaderProps = HTMLAttributes<HTMLDivElement>;

export const TestResultsHeader = ({
  className,
  children,
  ...props
}: TestResultsHeaderProps) => (
  <div
    className={cn(
      "flex items-center justify-between border-b px-4 py-3",
      className
    )}
    {...props}
  >
    {children}
  </div>
);

export type TestResultsDurationProps = HTMLAttributes<HTMLSpanElement>;

export const TestResultsDuration = ({
  className,
  children,
  ...props
}: TestResultsDurationProps) => {
  const { summary } = useContext(TestResultsContext);

  if (!summary?.duration) {
    return null;
  }

  return (
    <span className={cn("type-small text-muted-foreground", className)} {...props}>
      {children ?? formatDuration(summary.duration)}
    </span>
  );
};

export type TestResultsSummaryProps = HTMLAttributes<HTMLDivElement>;

export const TestResultsSummary = ({
  className,
  children,
  ...props
}: TestResultsSummaryProps) => {
  const { summary } = useContext(TestResultsContext);

  if (!summary) {
    return null;
  }

  return (
    <div className={cn("flex items-center gap-3", className)} {...props}>
      {children ?? (
        <>
          <Badge className="gap-1" variant="success">
            <Icon icon={CheckCircle2Icon} size="xs" tone="inherit" />
            {summary.passed} passed
          </Badge>
          {summary.failed > 0 && (
            <Badge className="gap-1" variant="destructive">
              <Icon icon={XCircleIcon} size="xs" tone="inherit" />
              {summary.failed} failed
            </Badge>
          )}
          {summary.skipped > 0 && (
            <Badge className="gap-1" variant="warning">
              <Icon icon={CircleIcon} size="xs" tone="inherit" />
              {summary.skipped} skipped
            </Badge>
          )}
        </>
      )}
    </div>
  );
};

export type TestResultsProps = HTMLAttributes<HTMLDivElement> & {
  summary?: TestResultsSummary;
};

export const TestResults = ({
  summary,
  className,
  children,
  ...props
}: TestResultsProps) => {
  const contextValue = useMemo(() => ({ summary }), [summary]);

  return (
    <TestResultsContext.Provider value={contextValue}>
      <div
        className={cn("rounded-lg border bg-background", className)}
        {...props}
      >
        {children ??
          (summary && (
            <TestResultsHeader>
              <TestResultsSummary />
              <TestResultsDuration />
            </TestResultsHeader>
          ))}
      </div>
    </TestResultsContext.Provider>
  );
};

export type TestResultsProgressProps = HTMLAttributes<HTMLDivElement>;

export const TestResultsProgress = ({
  className,
  children,
  ...props
}: TestResultsProgressProps) => {
  const { summary } = useContext(TestResultsContext);

  if (!summary) {
    return null;
  }

  const passedPercent = (summary.passed / summary.total) * 100;
  const failedPercent = (summary.failed / summary.total) * 100;

  return (
    <div className={cn("space-y-2", className)} {...props}>
      {children ?? (
        <>
          {/* A progress fill carries no foreground of its own, so it is on
              the same contract as text (RULES §1 rule 3): the two segments
              name `-ink`, never the raw `--color-success` / `--destructive`,
              matching `Progress`'s own `tone` treatment. */}
          <div className="flex h-2 overflow-hidden rounded-pill bg-muted">
            <div
              className="bg-success-ink transition-[width]"
              style={{ width: `${passedPercent}%` }}
            />
            <div
              className="bg-destructive-ink transition-[width]"
              style={{ width: `${failedPercent}%` }}
            />
          </div>
          <div className="type-small flex justify-between text-muted-foreground">
            <span>
              {summary.passed}/{summary.total} tests passed
            </span>
            <span>{passedPercent.toFixed(0)}%</span>
          </div>
        </>
      )}
    </div>
  );
};

export type TestResultsContentProps = HTMLAttributes<HTMLDivElement>;

export const TestResultsContent = ({
  className,
  children,
  ...props
}: TestResultsContentProps) => (
  <div className={cn("space-y-2 p-4", className)} {...props}>
    {children}
  </div>
);

interface TestSuiteContextType {
  name: string;
  status: TestStatus;
}

const TestSuiteContext = createContext<TestSuiteContextType>({
  name: "",
  status: "passed",
});

/* Every state colour on this file used to name the raw Tailwind palette hue
   with a separate dark-mode override, which is legible on one theme and not
   the other (RULES §1 rule 3 / trap 12). `-ink` is the role built to answer
   per-theme; `running`, which had no state token at all, takes `action` — a
   running test is something actively happening, the meaning `action`
   already owns. */
const STATUS_TONE: Record<TestStatus, IconTone> = {
  failed: "error",
  passed: "success",
  running: "action",
  skipped: "warning",
};

// Vendored change: `running` swaps the vendor's pulsing `CircleDotIcon`
// (`animate-pulse`, off the motion scale) for `LoaderCircleIcon` + `anim-spin`
// — `anim-pulse` is the green live-dot glow, not a generic "active" ring.
const STATUS_ICON: Record<TestStatus, LucideIcon> = {
  failed: XCircleIcon,
  passed: CheckCircle2Icon,
  running: LoaderCircleIcon,
  skipped: CircleIcon,
};

const STATUS_TEXT_CLASS: Record<TestStatus, string> = {
  failed: "text-destructive-ink",
  passed: "text-success-ink",
  running: "text-action-ink",
  skipped: "text-warning-ink",
};

const StatusIcon = ({
  status,
  className,
}: {
  status: TestStatus;
  className?: string;
}) => (
  <Icon
    className={cn(status === "running" && "anim-spin", className)}
    icon={STATUS_ICON[status]}
    size="md"
    tone={STATUS_TONE[status]}
  />
);

export type TestSuiteProps = ComponentProps<typeof Collapsible> & {
  name: string;
  status: TestStatus;
};

export const TestSuite = ({
  name,
  status,
  className,
  children,
  ...props
}: TestSuiteProps) => {
  const contextValue = useMemo(() => ({ name, status }), [name, status]);

  return (
    <TestSuiteContext.Provider value={contextValue}>
      <Collapsible className={cn("rounded-lg border", className)} {...props}>
        {children}
      </Collapsible>
    </TestSuiteContext.Provider>
  );
};

export type TestSuiteNameProps = ComponentProps<typeof CollapsibleTrigger>;

export const TestSuiteName = ({
  className,
  children,
  ...props
}: TestSuiteNameProps) => {
  const { name, status } = useContext(TestSuiteContext);

  return (
    <CollapsibleTrigger
      className={cn(
        "group flex min-h-(--size-target-min) w-full items-center gap-2 px-4 py-3 text-left transition-colors hover:bg-muted/50",
        className
      )}
      {...props}
    >
      <Icon
        className="shrink-0 transition-transform group-data-[state=open]:rotate-90"
        icon={ChevronRightIcon}
        size="md"
        tone="muted"
      />
      <StatusIcon status={status} />
      {/* `type-nav` rather than `type-small` + a bolted-on `font-medium`: a
          clickable row label is exactly the role `type-nav` (weight 500, no
          case) already owns, and §2 rule 1 keeps weight out of the call
          site. */}
      <span className="type-nav">{children ?? name}</span>
    </CollapsibleTrigger>
  );
};

export type TestSuiteStatsProps = HTMLAttributes<HTMLDivElement> & {
  passed?: number;
  failed?: number;
  skipped?: number;
};

export const TestSuiteStats = ({
  passed = 0,
  failed = 0,
  skipped = 0,
  className,
  children,
  ...props
}: TestSuiteStatsProps) => (
  <div
    className={cn("type-small ml-auto flex items-center gap-2", className)}
    {...props}
  >
    {children ?? (
      <>
        {passed > 0 && (
          <span className={STATUS_TEXT_CLASS.passed}>{passed} passed</span>
        )}
        {failed > 0 && (
          <span className={STATUS_TEXT_CLASS.failed}>{failed} failed</span>
        )}
        {skipped > 0 && (
          <span className={STATUS_TEXT_CLASS.skipped}>{skipped} skipped</span>
        )}
      </>
    )}
  </div>
);

export type TestSuiteContentProps = ComponentProps<typeof CollapsibleContent>;

export const TestSuiteContent = ({
  className,
